45	// IsErrUserStatusError returns true if the error is an ErrAccountDisabled or ErrAccountLocked.
46	func IsErrUserStatusError(err error) bool {
47		return IsErrAccountDisabled(err) || IsErrAccountLocked(err)
48	}
