140	// RouteForMail routes all notifications for a user to its email address
141	func (u *User) RouteForMail() (string, error) {
142	
143		if u.Email == "" {
144			s := db.NewSession()
145			defer s.Close()
146			user, err := getUser(s, &User{ID: u.ID}, true)
147			if err != nil && !IsErrUserStatusError(err) {
148				return "", err
149			}
150			return user.Email, nil
151		}
152	
153		return u.Email, nil
154	}
