161	func (u *User) ShouldNotify(sessions ...*xorm.Session) (bool, error) {
162		if u.IsBot() {
163			return false, nil
164		}
165		var s *xorm.Session
166		if len(sessions) > 0 && sessions[0] != nil {
167			s = sessions[0]
168		} else {
169			s = db.NewSession()
170			defer s.Close()
171		}
172		_, err := getUser(s, &User{ID: u.ID}, true)
173		if IsErrUserStatusError(err) {
174			return false, nil
175		}
176		if err != nil {
177			return false, err
178		}
179		return true, nil
180	}
