228	// GetFromAuth returns a user object from a web.Auth object and returns an error if the underlying type
229	// is not a user object
230	func GetFromAuth(a web.Auth) (*User, error) {
231		u, is := a.(*User)
232		if !is {
233			typ := reflect.TypeOf(a)
234			if typ.String() == "*models.LinkSharing" {
235				return nil, &ErrMustNotBeLinkShare{}
236			}
237			return &User{}, fmt.Errorf("user is not user element, is %s", typ)
238		}
239		return u, nil
240	}
