254	// GetUserByID returns user by its ID
255	func GetUserByID(s *xorm.Session, id int64) (user *User, err error) {
256		// Apparently xorm does otherwise look for all users but return only one, which leads to returning one even if the ID is 0
257		if id < 1 {
258			return &User{}, ErrUserDoesNotExist{}
259		}
260	
261		// The memo holds the raw row, shared with GetUsersByIDs, so the status gate runs on every hit.
262		raw, err := db.Remember(s, userMemoKey(id), func() (*User, error) {
263			return loadUser(s, &User{ID: id}, false)
264		})
265		if err != nil {
266			return &User{}, err
267		}
268	
269		u := *raw
270		return &u, finishLoadedUser(&u)
271	}
