283	func GetUsersByUsername(s *xorm.Session, usernames []string, withEmails bool) (users map[int64]*User, err error) {
284		if len(usernames) == 0 {
285			return
286		}
287	
288		users = make(map[int64]*User)
289		err = s.In("username", usernames).Find(&users)
290		if err != nil {
291			return
292		}
293	
294		if !withEmails {
295			for _, u := range users {
296				u.Email = ""
297			}
298		}
299	
300		return
301	}
