308	// GetUsersByIDs returns a map of users from a slice of user ids
309	func GetUsersByIDs(s *xorm.Session, userIDs []int64) (users map[int64]*User, err error) {
310		loaded, err := db.RememberEach(s, userIDs, userMemoKey, func(missing []int64) (map[int64]*User, error) {
311			return GetUsersByCond(s, builder.In("id", missing))
312		})
313		if err != nil {
314			return nil, err
315		}
316	
317		users = make(map[int64]*User, len(loaded))
318		for id, u := range loaded {
319			copied := *u
320			users[id] = &copied
321		}
322		return users, nil
323	}
324	
325	func GetUsersByCond(s *xorm.Session, cond builder.Cond) (users map[int64]*User, err error) {
326		users = make(map[int64]*User)
327	
328		err = s.Where(cond).Find(&users)
329		if err != nil {
330			return
331		}
332	
333		// Obfuscate all user emails
334		for _, u := range users {
335			u.Email = ""
336		}
337	
338		return
339	}
