341	func loadUser(s *xorm.Session, user *User, withEmail bool) (userOut *User, err error) {
342		userOut = &User{} // To prevent a panic if user is nil
343		*userOut = *user
344		exists, err := s.Get(userOut)
345		if err != nil {
346			return nil, err
347		}
348		if !exists {
349			return &User{}, ErrUserDoesNotExist{UserID: user.ID}
350		}
351	
352		if !withEmail {
353			userOut.Email = ""
354		}
355	
356		return userOut, nil
357	}
358	
359	func getUser(s *xorm.Session, user *User, withEmail bool) (userOut *User, err error) {
360		userOut, err = loadUser(s, user, withEmail)
361		if err != nil {
362			return userOut, err
363		}
364	
365		return userOut, finishLoadedUser(userOut)
366	}
