368	func finishLoadedUser(u *User) error {
369		if u.OverdueTasksRemindersTime == "" {
370			u.OverdueTasksRemindersTime = "9:00"
371		}
372	
373		if u.Status == StatusDisabled {
374			return &ErrAccountDisabled{UserID: u.ID}
375		}
376	
377		if u.Status == StatusAccountLocked {
378			return &ErrAccountLocked{UserID: u.ID}
379		}
380	
381		return nil
382	}
