384	func getUserByUsernameOrEmail(s *xorm.Session, usernameOrEmail string) (u *User, err error) {
385		u = &User{}
386		exists, err := s.
387			Where("username = ? OR email = ?", usernameOrEmail, usernameOrEmail).
388			Get(u)
389		if err != nil {
390			return nil, err
391		}
392		if !exists {
393			return nil, ErrUserDoesNotExist{}
394		}
395	
396		u.Email = ""
397		return
398	}
