449	func handleFailedPassword(ctx context.Context, user *User) {
450		if err := events.DispatchWithContext(ctx, &LoginFailedEvent{User: user}); err != nil {
451			log.Errorf("Could not dispatch login failed event: %s", err)
452		}
453	
454		key := user.GetFailedPasswordAttemptsKey()
455		err := keyvalue.IncrBy(key, 1)
456		if err != nil {
457			log.Errorf("Could not set failed password attempts: %s", err)
458			return
459		}
460	
461		a, _, err := keyvalue.Get(key)
462		if err != nil {
463			log.Errorf("Could not get failed password attempts for user %d: %s", user.ID, err)
464			return
465		}
466		attempts, ok := a.(int64)
467		if !ok {
468			attemptsStr, ok := a.(string)
469			if !ok {
470				log.Errorf("Unexpected type for failed password attempts: %v", a)
471				return
472			}
473			var err error
474			attempts, err = strconv.ParseInt(attemptsStr, 10, 64)
475			if err != nil {
476				log.Errorf("Could not convert failed password attempts to int64: %v, value: %s", err, attemptsStr)
477				return
478			}
479		}
480		if attempts != 3 {
481			return
482		}
483	
484		err = notifications.Notify(user, &FailedLoginAttemptNotification{
485			User: user,
486		})
487		if err != nil {
488			log.Errorf("Could not send invalid password mail to user: %s", err)
489			return
490		}
491	
492		err = keyvalue.Del(key)
493		if err != nil {
494			log.Errorf("Could not remove failed password attempts: %s", err)
495			return
496		}
497	}
