499	// CheckUserPassword checks and verifies a user's password. The user object needs to contain the hashed password from the database.
500	func CheckUserPassword(user *User, password string) error {
501		err := bcrypt.CompareHashAndPassword([]byte(user.Password), []byte(password))
502		if err != nil {
503			if errors.Is(err, bcrypt.ErrMismatchedHashAndPassword) {
504				return ErrWrongUsernameOrPassword{}
505			}
506			return err
507		}
508	
509		return nil
510	}
