640	
641	func userUpdateColumns(s *xorm.Session, user, theUser *User, forceOverride bool) (cols []string, err error) {
642		cols = baseUserUpdateColumns[:]
643	
644		if user.Email != "" && user.Email != theUser.Email {
645			// A direct change supersedes a pending one, the link already mailed out must not work anymore.
646			user.PendingEmail = ""
647			cols = append(cols, "pending_email")
648			if err := removeTokens(s, user, TokenEmailConfirm); err != nil {
649				return nil, err
650			}
651		}
652	
653		if forceOverride {
654			// forceOverride is set in paths where we should apply the FrontendSettings update.
655			user.FrontendSettings, err = premarshalFrontendSettings(user.FrontendSettings)
656			if err != nil {
657				return nil, err
658			}
659			cols = append(cols, "frontend_settings")
660		}
661	
662		return cols, nil
663	}
664	
665	// UpdateUser updates a user
666	func UpdateUser(s *xorm.Session, user *User, forceOverride bool) (updatedUser *User, err error) {
667	
668		// Check if it exists
669		theUser, err := GetUserWithEmail(s, &User{ID: user.ID})
670		if err != nil && !IsErrUserStatusError(err) {
671			return &User{}, err
672		}
673	
674		// Check if we have at least a username
675		if user.Username == "" {
676			user.Username = theUser.Username // Dont change the username if we dont have one
677		} else {
678			// Check if the new username already exists
679			uu, err := getUser(s, &User{Username: user.Username}, false)
680			if err != nil && !IsErrUserDoesNotExist(err) {
681				return nil, err
682			}
683			if uu.ID != 0 && uu.ID != user.ID {
684				return nil, &ErrUsernameExists{Username: user.Username, UserID: uu.ID}
685			}
686		}
687	
688		// Check if we have a name
689		if user.Name == "" && !forceOverride {
690			user.Name = theUser.Name
691		}
692	
693		// Check if the email is already used
694		if user.Email == "" {
695			user.Email = theUser.Email
696		} else {
697			uu, err := getUser(s, &User{
698				Email:   user.Email,
699				Issuer:  user.Issuer,
700				Subject: user.Subject,
701			}, true)
702			if err != nil && !IsErrUserDoesNotExist(err) {
703				return nil, err
704			}
705			if uu.ID != 0 && uu.ID != user.ID {
706				return nil, &ErrUserEmailExists{Email: user.Email, UserID: uu.ID}
707			}
708		}
709	
710		// Validate the avatar type
711		if user.AvatarProvider != "" {
712			if user.AvatarProvider != "default" &&
713				user.AvatarProvider != "gravatar" &&
714				user.AvatarProvider != "initials" &&
715				user.AvatarProvider != "upload" &&
716				user.AvatarProvider != "marble" &&
717				user.AvatarProvider != "ldap" &&
718				user.AvatarProvider != "openid" {
719				return updatedUser, &ErrInvalidAvatarProvider{AvatarProvider: user.AvatarProvider}
720			}
721		}
722	
723		// Check if we have a valid time zone
724		if user.Timezone == "" {
725			user.Timezone = config.GetTimeZone().String()
726		}
727	
728		_, err = time.LoadLocation(user.Timezone)
729		if err != nil {
730			return nil, &ErrInvalidTimezone{Name: user.Timezone, LoadError: err}
731		}
732	
733		updateCols, err := userUpdateColumns(s, user, theUser, forceOverride)
734		if err != nil {
735			return nil, err
736		}
737	
738		_, err = s.
739			ID(user.ID).
740			Cols(updateCols...).
741			Update(user)
742		if err != nil {
743			return &User{}, err
744		}
745	
746		updatedUser, err = GetUserByID(s, user.ID)
747		if err != nil && !IsErrUserStatusError(err) {
748			return &User{}, err
749		}
750	
751		return updatedUser, err
752	}
753	
754	func SetUserStatus(s *xorm.Session, user *User, status Status) (err error) {
755		_, err = s.Where("id = ?", user.ID).
756			Cols("status").
757			Update(&User{Status: status})
758		return
759	}
760	
761	// GuardLastAdmin refuses demoting or deleting the last reachable admin; only active, non-deletion-scheduled admins count since the rest cannot log in.
762	// SELECT ... FOR UPDATE closes the TOCTOU race between concurrent demotions on MySQL (xorm only emits it for MySQL; SQLite serializes writes, postgres relies on serializable isolation).
763	func GuardLastAdmin(s *xorm.Session, target *User) error {
764		if !target.IsAdmin {
765			return nil
766		}
767		// target is not in the counted "reachable admin" set — removing them
768		// doesn't change the invariant, so the guard is a no-op.
769		if target.Status != StatusActive || !target.DeletionScheduledAt.IsZero() {
770			return nil
771		}
772	
773		session := s.Where("is_admin = ?", true).
774			And("status = ?", StatusActive).
775			And("deletion_scheduled_at IS NULL")
776		if db.Type() == schemas.MYSQL {
777			session = session.ForUpdate()
778		}
779	
780		count, err := session.Count(&User{})
781		if err != nil {
782			return err
783		}
784		if count <= 1 {
785			return ErrLastAdmin{}
786		}
787		return nil
788	}
789	
790	// UpdateUserPassword updates the password of a user
791	func UpdateUserPassword(s *xorm.Session, user *User, newPassword string) (err error) {
792	
793		if newPassword == "" {
794			return ErrEmptyNewPassword{}
795		}
796	
797		// Get all user details
798		theUser, err := GetUserByID(s, user.ID)
799		if err != nil && !IsErrUserStatusError(err) {
800			return err
801		}
802	
803		// Hash the new password and set it
804		hashed, err := HashPassword(newPassword)
805		if err != nil {
806			return err
807		}
808		theUser.Password = hashed
809	
810		// Update it
811		_, err = s.
812			Where("id = ?", user.ID).
813			Update(&User{Password: hashed})
814		if err != nil {
815			return err
816		}
817	
818		return err
819	}
820	
821	// SetStatus sets a users status in the database
822	func (u *User) SetStatus(s *xorm.Session, status Status) (err error) {
823		u.Status = status
824		_, err = s.
825			Where("id = ?", u.ID).
826			Cols("status").
827			Update(u)
828		return
829	}
830

