48		URL string `xorm:"text null" json:"url" readOnly:"true" doc:"The otpauth:// url, generated by the server, used to enroll the user in an authenticator app."`
49	}
50	
51	// TableName holds the table name for totp secrets
52	func (t *TOTP) TableName() string {
53		return "totp"
54	}
55	
56	// APICopy hides enabled secrets while GetTOTPForUser retains them for login validation.
57	func (t *TOTP) APICopy() *TOTP {
58		if !t.Enabled {
59			return t
60		}
61		return &TOTP{UserID: t.UserID, Enabled: true}
62	}
63	
64	// TOTPPasscode is used to validate a users totp passcode
65	type TOTPPasscode struct {
66		User     *User  `json:"-"`
67		Passcode string `json:"passcode"`
68	}
69	
70	// TOTPEnabledForUser checks if totp is enabled for a user - not if it is activated, use GetTOTPForUser to check that.
71	func TOTPEnabledForUser(s *xorm.Session, user *User) (bool, error) {
72		if !config.ServiceEnableTotp.GetBool() {
73			return false, nil
74		}
75		t := &TOTP{}
76		_, err := s.Where("user_id = ?", user.ID).Get(t)
77		return t.Enabled, err
78	}
79	
80	// GetTOTPForUser returns the current state of totp settings for the user.
81	func GetTOTPForUser(s *xorm.Session, user *User) (t *TOTP, err error) {
82		t = &TOTP{}
83		exists, err := s.Where("user_id = ?", user.ID).Get(t)
84		if err != nil {
85			return
86		}
87		if !exists {
88			return nil, ErrTOTPNotEnabled{}
89		}
90	
91		return
92	}
93	
94	// EnrollTOTP creates a new TOTP entry for the user - it does not enable it yet.
95	func EnrollTOTP(s *xorm.Session, user *User) (t *TOTP, err error) {
96		isEnrolled, err := s.Where("user_id = ?", user.ID).Exist(&TOTP{})
97		if err != nil {
98			return
99		}
100		if isEnrolled {
101			return nil, ErrTOTPAlreadyEnabled{}
102		}
103	
104		key, err := totp.Generate(totp.GenerateOpts{
105			Issuer:      "Vikunja",
106			AccountName: user.Username,
107		})
108		if err != nil {
109			return
110		}
111	
112		t = &TOTP{
113			UserID:  user.ID,
114			Secret:  key.Secret(),
115			Enabled: false,
116			URL:     key.URL(),
117		}
118		_, err = s.Insert(t)
119		return
120	}
121	
122	// EnableTOTP enables totp for a user. The provided passcode is used to verify the user has a working totp setup.
123	func EnableTOTP(s *xorm.Session, passcode *TOTPPasscode) (err error) {
124		t, err := ValidateTOTPPasscode(s, passcode)
125		if err != nil {
126			return
127		}
128	
129		_, err = s.
130			Where("id = ?", t.ID).
131			Cols("enabled").
132			Update(&TOTP{Enabled: true})
133		return
134	}
