139			Where("user_id = ?", user.ID).
140			Delete(&TOTP{})
141		return
142	}
143	
144	// ValidateTOTPPasscode validated totp codes of users.
145	func ValidateTOTPPasscode(s *xorm.Session, passcode *TOTPPasscode) (t *TOTP, err error) {
146		t, err = GetTOTPForUser(s, passcode.User)
147		if err != nil {
148			return
149		}
150	
151		if !totp.Validate(passcode.Passcode, t.Secret) {
152			return nil, ErrInvalidTOTPPasscode{Passcode: passcode.Passcode}
153		}
154	
155		// 90s = 30s TOTP window + clock skew
156		const totpUsedTTL = 90 * time.Second
157		usedKey := fmt.Sprintf("totp_used_%s_%s", strconv.FormatInt(passcode.User.ID, 10), passcode.Passcode)
158		_, exists, err := keyvalue.Get(usedKey)
159		if err != nil {
160			return nil, err
161		}
162		if exists {
163			return nil, ErrTOTPPasscodeUsed{}
164		}
165	
166		err = keyvalue.PutWithTTL(usedKey, true, totpUsedTTL)
167		if err != nil {
168			return nil, err
169		}
170	
171		return
172	}
173	
174	// GetTOTPQrCodeForUser returns a qrcode for a user's totp setting
175	func GetTOTPQrCodeForUser(s *xorm.Session, user *User) (qrcode image.Image, err error) {
176		t, err := GetTOTPForUser(s, user)
177		if err != nil {
178			return
179		}
180	
181		// The QR code carries the provisioning secret.
182		if t.Enabled {
183			return nil, ErrTOTPQrCodeNotAvailable{}
184		}
185	
186		key, err := otp.NewKeyFromURL(t.URL)
187		if err != nil {
188			return
189		}
190		return key.Image(300, 300)
191	}
192	
193	// GetTOTPQrCodeAsJpegForUser renders the user's totp qr code to jpeg bytes, the
194	// wire format both API versions serve.
195	func GetTOTPQrCodeAsJpegForUser(s *xorm.Session, user *User) ([]byte, error) {
196		qrcode, err := GetTOTPQrCodeForUser(s, user)
197		if err != nil {
198			return nil, err
199		}
200	
201		buff := &bytes.Buffer{}
202		if err := jpeg.Encode(buff, qrcode, nil); err != nil {
203			return nil, err
204		}
205		return buff.Bytes(), nil
206	}
207	
208	// HandleFailedTOTPAuth records a failed TOTP attempt and locks the account
209	// after 10 consecutive failures.
210	//
211	// Must not share the caller's session: the login handler rolls its session
212	// back on auth failure, which would discard the lockout write
213	// (GHSA-fgfv-pv97-6cmj). Opens its own session and commits independently.
214	func HandleFailedTOTPAuth(user *User) {
215		log.Errorf("Invalid TOTP credentials provided for user %d", user.ID)
216	
217		key := user.GetFailedTOTPAttemptsKey()
218		if err := keyvalue.IncrBy(key, 1); err != nil {
219			log.Errorf("Could not increase failed TOTP attempts for user %d: %s", user.ID, err)
220			return
221		}
222	
223		a, _, err := keyvalue.Get(key)
224		if err != nil {
225			log.Errorf("Could not get failed TOTP attempts for user %d: %s", user.ID, err)
226			return
227		}
228		// Redis backend returns the counter as a string; in-memory as int64.
229		attempts, ok := a.(int64)
230		if !ok {
231			attemptsStr, ok := a.(string)
232			if !ok {
233				log.Errorf("Unexpected type for failed TOTP attempts for user %d: %T", user.ID, a)
234				return
235			}
236			attempts, err = strconv.ParseInt(attemptsStr, 10, 64)
237			if err != nil {
238				log.Errorf("Could not convert failed TOTP attempts to int64 for user %d: %v, value: %s", user.ID, err, attemptsStr)
239				return
240			}
241		}
242	
243		if attempts == 3 {
244			s := db.NewSession()
245			defer s.Close()
246			if err := notifications.Notify(user, &InvalidTOTPNotification{User: user}, s); err != nil {
247				log.Errorf("Could not send failed TOTP notification to user %d: %s", user.ID, err)
248				_ = s.Rollback()
249				return
250			}
251			if err := s.Commit(); err != nil {
252				log.Errorf("Could not commit failed TOTP notification for user %d: %s", user.ID, err)
253			}
254			return
255		}
256	
257		if attempts < 10 {
258			return
259		}
260	
261		log.Infof("Blocking user account %d after 10 failed TOTP password attempts", user.ID)
262		s := db.NewSession()
263		defer s.Close()
264		defer events.CleanupPending(s)
265	
266		if err := RequestUserPasswordResetToken(s, user); err != nil {
267			log.Errorf("Could not issue password reset token for user %d after 10 failed TOTP attempts: %s", user.ID, err)
268			_ = s.Rollback()
269			return
270		}
271		if err := notifications.Notify(user, &PasswordAccountLockedAfterInvalidTOTPNotification{User: user}, s); err != nil {
272			log.Errorf("Could not send password information mail to user %d after 10 failed TOTP attempts: %s", user.ID, err)
273			_ = s.Rollback()
274			return
275		}
276		if err := user.SetStatus(s, StatusAccountLocked); err != nil {
277			log.Errorf("Could not lock user %d: %s", user.ID, err)
278			_ = s.Rollback()
279			return
280		}
281		events.DispatchOnCommit(s, &AccountLockedEvent{UserID: user.ID})
282		if err := s.Commit(); err != nil {
283			log.Errorf("Could not commit lockout for user %d: %s", user.ID, err)
284			return
285		}
286		events.DispatchPending(context.Background(), s)
287	}
