)

// TokenKind represents a user token kind
type TokenKind int

const (
	TokenUnknown TokenKind = iota
	TokenPasswordReset
	TokenEmailConfirm
	TokenAccountDeletion
	TokenCaldavAuth

	tokenSize = 64
)

// Token is a token a user can use to do things like verify their email or resetting their password
type Token struct {
	ID             int64     `xorm:"bigint autoincr not null unique pk" json:"id" readOnly:"true" doc:"The unique, numeric id of this token."`
	UserID         int64     `xorm:"not null" json:"-"`
	Token          string    `xorm:"varchar(450) not null index" json:"-"`
	ClearTextToken string    `xorm:"-" json:"token" readOnly:"true" doc:"The token in clear text. Only returned once when the token is created; never on subsequent reads."`
	Kind           TokenKind `xorm:"not null" json:"-"`
	Created        time.Time `xorm:"created not null" json:"created" readOnly:"true" doc:"A timestamp when this token was created. You cannot change this value."`
}

// TableName returns the real table name for user tokens
func (t *Token) TableName() string {
	return "user_tokens"
}

func genToken(u *User, kind TokenKind) (*Token, error) {
	tokenStr, err := utils.CryptoRandomString(tokenSize)
	if err != nil {
		return nil, err
	}
	return &Token{
		UserID: u.ID,
		Kind:   kind,
		Token:  tokenStr,
	}, nil
}

func generateToken(s *xorm.Session, u *User, kind TokenKind) (token *Token, err error) {
	token, err = genToken(u, kind)
	if err != nil {
		return nil, err
	}

	token.ClearTextToken = token.Token
	token.Token = utils.Sha256Hex(token.ClearTextToken)

	_, err = s.Insert(token)
	return
}

func generateHashedToken(s *xorm.Session, u *User, kind TokenKind) (token *Token, err error) {
	token, err = genToken(u, kind)
	if err != nil {
		return nil, err
	}
	token.ClearTextToken = token.Token
	token.Token, err = HashPassword(token.ClearTextToken)
	if err != nil {
		return nil, err
	}

	_, err = s.Insert(token)
	return
}

func getToken(s *xorm.Session, token string, kind TokenKind) (t *Token, err error) {
	t = &Token{}
	has, err := s.Where("kind = ? AND token = ?", kind, utils.Sha256Hex(token)).
		Get(t)
	if err != nil || !has {
		return nil, err
	}

	return
}

func getTokensForKind(s *xorm.Session, u *User, kind TokenKind) (tokens []*Token, err error) {
	tokens = []*Token{}

	err = s.Where("kind = ? AND user_id = ?", kind, u.ID).
		Find(&tokens)
	return
}

func removeTokens(s *xorm.Session, u *User, kind TokenKind) (err error) {
	_, err = s.Where("user_id = ? AND kind = ?", u.ID, kind).
		Delete(&Token{})
	return
}

func removeTokenByID(s *xorm.Session, u *User, kind TokenKind, id int64) (err error) {
	_, err = s.Where("id = ? AND user_id = ? AND kind = ?", id, u.ID, kind).
		Delete(&Token{})
	return
}

// CleanupOldTokens removes all password reset, account deletion and email change tokens older than 24 hours.
// Email confirm tokens are only swept for users with a pending email change, registration confirm links never expire.
func CleanupOldTokens(s *xorm.Session) (deleted int64, err error) {
	cutoff := time.Now().Add(time.Hour * 24 * -1)
	deleted, err = s.
		Where(builder.And(
			builder.Lt{"created": cutoff},
			builder.Or(
				builder.In("kind", TokenPasswordReset, TokenAccountDeletion),
				builder.And(
					builder.Eq{"kind": TokenEmailConfirm},
					builder.In("user_id",
						builder.Select("id").From("users").Where(builder.Neq{"pending_email": ""}),
					),
				),
			),
		)).
		Delete(&Token{})
	return
}

// RegisterTokenCleanupCron registers a cron function to clean up expired tokens every hour
func RegisterTokenCleanupCron() {
	const logPrefix = "[User Token Cleanup Cron] "

	err := cron.Schedule("0 * * * *", func() {
		s := db.NewSession()
		defer s.Close()

		deleted, err := CleanupOldTokens(s)
		if err != nil {
			log.Errorf(logPrefix+"Error removing old password reset tokens: %s", err)
			return
		}
		if deleted > 0 {
			log.Debugf(logPrefix+"Deleted %d old password reset tokens", deleted)
		}

		if err := s.Commit(); err != nil {
			log.Errorf(logPrefix+"Error committing token cleanup: %s", err)
		}
	})
	if err != nil {
		log.Fatalf("Could not register token cleanup cron: %s", err)
	}
}

