400	// CheckUserCredentials checks user credentials. The context carries request
401	// metadata for the audit trail of failed attempts.
402	func CheckUserCredentials(ctx context.Context, s *xorm.Session, u *Login) (*User, error) {
403		// Check if we have any credentials
404		if u.Password == "" || u.Username == "" {
405			return nil, ErrNoUsernamePassword{}
406		}
407	
408		// Check if the user exists
409		user, err := getUserByUsernameOrEmail(s, u.Username)
410		if err != nil {
411			// hashing the password takes a long time, so we hash something to not make it clear if the username was wrong
412			_, _ = bcrypt.GenerateFromPassword([]byte(u.Username), config.ServiceBcryptRounds.GetInt())
413			return nil, ErrWrongUsernameOrPassword{}
414		}
415	
416		if user.Issuer != IssuerLocal {
417			return user, &ErrAccountIsNotLocal{UserID: user.ID}
418		}
419	
420		// The user is invalid if they need to verify their email address
421		if user.Status == StatusEmailConfirmationRequired {
422			return &User{}, ErrEmailNotConfirmed{UserID: user.ID}
423		}
424	
425		// Check the users password
426		err = CheckUserPassword(user, u.Password)
427		if err != nil {
428			if IsErrWrongUsernameOrPassword(err) {
429				handleFailedPassword(ctx, user)
430			}
431			return user, err
432		}
433	
434		// After successful password verification, check if the account is disabled or locked
435		if user.Status == StatusDisabled {
436			return nil, &ErrAccountDisabled{UserID: user.ID}
437		}
438		if user.Status == StatusAccountLocked {
439			return nil, &ErrAccountLocked{UserID: user.ID}
440		}
441	
442		return user, nil
443	}
