522	// GetCurrentUser returns the current user based on its jwt token
523	func GetCurrentUser(c *echo.Context) (user *User, err error) {
524		if apiUser, ok := c.Get("api_user").(*User); ok {
525			return apiUser, nil
526		}
527	
528		jwtinf, is := c.Get("user").(*jwt.Token)
529		if jwtinf == nil {
530			log.Error("No user found in context")
531			return nil, ErrInvalidUserContext{Reason: "no user found in context"}
532		}
533	
534		if !is {
535			log.Errorf("User in context is not a JWT token, got type: %T", jwtinf)
536			return nil, ErrInvalidUserContext{Reason: "user in context is not a JWT token"}
537		}
538	
539		claims := jwtinf.Claims.(jwt.MapClaims)
540		return GetUserFromClaims(claims)
541	}
542	
543	// AuthTypeUser is the value of the `type` claim in a user JWT
544	const AuthTypeUser int = 1
545	
546	// GetUserFromClaims Returns a new user from jwt claims
547	func GetUserFromClaims(claims jwt.MapClaims) (user *User, err error) {
548		typ, ok := claims["type"].(float64)
549		if !ok || int64(typ) != int64(AuthTypeUser) {
550			return nil, ErrInvalidUserContext{Reason: "token is not a user token"}
551		}
552	
553		userID, err := getClaimAsInt(claims, "id")
554		if err != nil {
555			return nil, err
556		}
557		username, err := getClaimAsString(claims, "username")
558		if err != nil {
559			return nil, err
560		}
561	
562		isAdmin, _ := claims["is_admin"].(bool)
563	
564		return &User{
565			ID:       userID,
566			Username: username,
567			IsAdmin:  isAdmin,
568		}, nil
569	}
570	
571	func getClaimAsInt(claims jwt.MapClaims, field string) (int64, error) {
572		_, exists := claims[field]
573		if !exists {
574			return 0, &ErrInvalidClaimData{
575				Field: field,
576				Type:  "missing",
577			}
578		}
579	
580		value, ok := claims[field].(float64)
581		if !ok {
582			return 0, &ErrInvalidClaimData{
583				Field: field,
584				Type:  fmt.Sprintf("%T", claims[field]),
585			}
586		}
587		return int64(value), nil
588	}
589	
590	func getClaimAsString(claims jwt.MapClaims, field string) (string, error) {
591		_, exists := claims[field]
592		if !exists {
593			return "", &ErrInvalidClaimData{
594				Field: field,
595				Type:  "missing",
596			}
597		}
598	
599		value, ok := claims[field].(string)
600		if !ok {
601			return "", &ErrInvalidClaimData{
602				Field: field,
603				Type:  fmt.Sprintf("%T", claims[field]),
604			}
605		}
606		return value, nil
607	}
