665	// UpdateUser updates a user
666	func UpdateUser(s *xorm.Session, user *User, forceOverride bool) (updatedUser *User, err error) {
667	
668		// Check if it exists
669		theUser, err := GetUserWithEmail(s, &User{ID: user.ID})
670		if err != nil && !IsErrUserStatusError(err) {
671			return &User{}, err
672		}
673	
674		// Check if we have at least a username
675		if user.Username == "" {
676			user.Username = theUser.Username // Dont change the username if we dont have one
677		} else {
678			// Check if the new username already exists
679			uu, err := getUser(s, &User{Username: user.Username}, false)
680			if err != nil && !IsErrUserDoesNotExist(err) {
681				return nil, err
682			}
683			if uu.ID != 0 && uu.ID != user.ID {
684				return nil, &ErrUsernameExists{Username: user.Username, UserID: uu.ID}
685			}
686		}
687	
688		// Check if we have a name
689		if user.Name == "" && !forceOverride {
690			user.Name = theUser.Name
691		}
692	
693		// Check if the email is already used
694		if user.Email == "" {
695			user.Email = theUser.Email
696		} else {
697			uu, err := getUser(s, &User{
698				Email:   user.Email,
699				Issuer:  user.Issuer,
700				Subject: user.Subject,
701			}, true)
702			if err != nil && !IsErrUserDoesNotExist(err) {
703				return nil, err
704			}
705			if uu.ID != 0 && uu.ID != user.ID {
706				return nil, &ErrUserEmailExists{Email: user.Email, UserID: uu.ID}
707			}
708		}
709	
710		// Validate the avatar type
711		if user.AvatarProvider != "" {
712			if user.AvatarProvider != "default" &&
713				user.AvatarProvider != "gravatar" &&
714				user.AvatarProvider != "initials" &&
715				user.AvatarProvider != "upload" &&
716				user.AvatarProvider != "marble" &&
717				user.AvatarProvider != "ldap" &&
718				user.AvatarProvider != "openid" {
719				return updatedUser, &ErrInvalidAvatarProvider{AvatarProvider: user.AvatarProvider}
720			}
721		}
722	
723		// Check if we have a valid time zone
724		if user.Timezone == "" {
725			user.Timezone = config.GetTimeZone().String()
726		}
727	
728		_, err = time.LoadLocation(user.Timezone)
729		if err != nil {
730			return nil, &ErrInvalidTimezone{Name: user.Timezone, LoadError: err}
731		}
732	
733		updateCols, err := userUpdateColumns(s, user, theUser, forceOverride)
734		if err != nil {
735			return nil, err
736		}
737	
738		_, err = s.
739			ID(user.ID).
740			Cols(updateCols...).
741			Update(user)
742		if err != nil {
743			return &User{}, err
744		}
745	
746		updatedUser, err = GetUserByID(s, user.ID)
747		if err != nil && !IsErrUserStatusError(err) {
748			return &User{}, err
749		}
750	
751		return updatedUser, err
752	}
