761	// GuardLastAdmin refuses demoting or deleting the last reachable admin; only active, non-deletion-scheduled admins count since the rest cannot log in.
762	// SELECT ... FOR UPDATE closes the TOCTOU race between concurrent demotions on MySQL (xorm only emits it for MySQL; SQLite serializes writes, postgres relies on serializable isolation).
763	func GuardLastAdmin(s *xorm.Session, target *User) error {
764		if !target.IsAdmin {
765			return nil
766		}
767		// target is not in the counted "reachable admin" set — removing them
768		// doesn't change the invariant, so the guard is a no-op.
769		if target.Status != StatusActive || !target.DeletionScheduledAt.IsZero() {
770			return nil
771		}
772	
773		session := s.Where("is_admin = ?", true).
774			And("status = ?", StatusActive).
775			And("deletion_scheduled_at IS NULL")
776		if db.Type() == schemas.MYSQL {
777			session = session.ForUpdate()
778		}
779	
780		count, err := session.Count(&User{})
781		if err != nil {
782			return err
783		}
784		if count <= 1 {
785			return ErrLastAdmin{}
786		}
787		return nil
788	}
