790	// UpdateUserPassword updates the password of a user
791	func UpdateUserPassword(s *xorm.Session, user *User, newPassword string) (err error) {
792	
793		if newPassword == "" {
794			return ErrEmptyNewPassword{}
795		}
796	
797		// Get all user details
798		theUser, err := GetUserByID(s, user.ID)
799		if err != nil && !IsErrUserStatusError(err) {
800			return err
801		}
802	
803		// Hash the new password and set it
804		hashed, err := HashPassword(newPassword)
805		if err != nil {
806			return err
807		}
808		theUser.Password = hashed
809	
810		// Update it
811		_, err = s.
812			Where("id = ?", user.ID).
813			Update(&User{Password: hashed})
814		if err != nil {
815			return err
816		}
817	
818		return err
819	}
