40	// TOTP holds a user's totp setting in the database.
41	type TOTP struct {
42		ID     int64  `xorm:"bigint autoincr not null unique pk" json:"-"`
43		UserID int64  `xorm:"bigint not null" json:"-"`
44		Secret string `xorm:"text not null" json:"secret" readOnly:"true" doc:"The shared secret used to generate passcodes, generated by the server on enrollment."`
45		// The totp entry will only be enabled after the user verified they have a working totp setup.
46		Enabled bool `xorm:"null" json:"enabled" readOnly:"true" doc:"Whether totp is fully activated. Set to true only after the user confirms a passcode."`
47		// The totp url used to be able to enroll the user later
48		URL string `xorm:"text null" json:"url" readOnly:"true" doc:"The otpauth:// url, generated by the server, used to enroll the user in an authenticator app."`
49	}
