144	// ValidateTOTPPasscode validated totp codes of users.
145	func ValidateTOTPPasscode(s *xorm.Session, passcode *TOTPPasscode) (t *TOTP, err error) {
146		t, err = GetTOTPForUser(s, passcode.User)
147		if err != nil {
148			return
149		}
150	
151		if !totp.Validate(passcode.Passcode, t.Secret) {
152			return nil, ErrInvalidTOTPPasscode{Passcode: passcode.Passcode}
153		}
154	
155		// 90s = 30s TOTP window + clock skew
156		const totpUsedTTL = 90 * time.Second
157		usedKey := fmt.Sprintf("totp_used_%s_%s", strconv.FormatInt(passcode.User.ID, 10), passcode.Passcode)
158		_, exists, err := keyvalue.Get(usedKey)
159		if err != nil {
160			return nil, err
161		}
162		if exists {
163			return nil, ErrTOTPPasscodeUsed{}
164		}
165	
166		err = keyvalue.PutWithTTL(usedKey, true, totpUsedTTL)
167		if err != nil {
168			return nil, err
169		}
170	
171		return
172	}
