174	// GetTOTPQrCodeForUser returns a qrcode for a user's totp setting
175	func GetTOTPQrCodeForUser(s *xorm.Session, user *User) (qrcode image.Image, err error) {
176		t, err := GetTOTPForUser(s, user)
