   119	// CreateBotUser creates a bot user owned by the given owner.
   120	// Bots have no email or password and cannot authenticate interactively.
   121	// It intentionally bypasses checkIfUserIsValid / checkIfUserExists because
   122	// those enforce email+password and would flag duplicate empty emails.
   123	func CreateBotUser(s *xorm.Session, bot *User, owner *User) (*User, error) {
   124		if owner == nil || owner.ID == 0 {
   125			return nil, ErrNoUsernamePassword{}
   126		}
   127		if owner.IsBot() {
   128			return nil, &ErrBotNotOwned{UserID: owner.ID}
   129		}
   130	
   131		// Reuse the same username format rules as regular user creation
   132		if err := checkUsernameFormat(bot.Username); err != nil {
   133			return nil, err
   134		}
   135		if !strings.HasPrefix(bot.Username, "bot-") {
   136			return nil, &ErrBotUsernameMustHavePrefix{Username: bot.Username}
   137		}
   138	
   139		if _, err := GetUserByUsername(s, bot.Username); err == nil {
   140			return nil, ErrUsernameExists{Username: bot.Username}
   141		} else if !IsErrUserDoesNotExist(err) {
   142			return nil, err
   143		}
   144	
   145		bot.ID = 0
   146		bot.BotOwnerID = owner.ID
   147		bot.Status = StatusActive
   148		bot.Issuer = IssuerLocal
   149		bot.Password = ""
   150		bot.Email = ""
   151	
   152		if _, err := s.Insert(bot); err != nil {
   153			return nil, err
   154		}
   155	
   156		newBot, err := GetUserByID(s, bot.ID)
   157		if err != nil {
   158			return nil, err
   159		}
   160	
   161		events.DispatchOnCommit(s, &CreatedEvent{User: newBot})
   162		return newBot, nil
   163	}
