   165	// HashPassword hashes a password
   166	func HashPassword(password string) (string, error) {
   167		bytes, err := bcrypt.GenerateFromPassword([]byte(password), config.ServiceBcryptRounds.GetInt())
   168		return string(bytes), err
   169	}
   170	
   171	// checkUsernameFormat validates username format rules shared by regular and bot users.
   172	func checkUsernameFormat(username string) error {
   173		if username == "" {
   174			return ErrNoUsernamePassword{}
   175		}
   176	
   177		if strings.Contains(username, " ") {
   178			return &ErrUsernameMustNotContainSpaces{
   179				Username: username,
   180			}
   181		}
   182	
   183		// Check if username matches the reserved link-share pattern
   184		linkSharePattern := regexp.MustCompile(`^link-share-\d+$`)
   185		if linkSharePattern.MatchString(username) {
   186			return ErrUsernameReserved{
   187				Username: username,
   188			}
   189		}
   190	
   191		return nil
   192	}
   193	
   194	func checkIfUserIsValid(user *User) error {
   195		if user.Email == "" ||
   196			(user.Issuer != IssuerLocal && user.Subject == "") ||
   197			(user.Issuer == IssuerLocal && (user.Password == "" ||
   198				user.Username == "")) {
   199			return ErrNoUsernamePassword{}
   200		}
   201	
   202		if err := checkUsernameFormat(user.Username); err != nil {
   203			return err
   204		}
   205	
   206		// Reserve the bot- prefix for bot users (created via CreateBotUser)
   207		if strings.HasPrefix(user.Username, "bot-") {
   208			return ErrUsernameReserved{
   209				Username: user.Username,
   210			}
   211		}
   212	
   213		return nil
   214	}
   215	
   216	func checkIfUserExists(s *xorm.Session, user *User) (err error) {
   217		exists := true
   218		_, err = GetUserByUsername(s, user.Username)
   219		if err != nil {
   220			if IsErrUserDoesNotExist(err) {
   221				exists = false
   222			} else {
   223				return err
   224			}
   225		}
   226		if exists {
   227			return ErrUsernameExists{user.ID, user.Username}
   228		}
   229	
   230		// Check if the user already existst with that email
   231		exists = true
   232		userToCheck := &User{
   233			Email:   user.Email,
   234			Issuer:  user.Issuer,
   235			Subject: user.Subject,
   236		}
   237	
   238		if user.Issuer != IssuerLocal {
   239			userToCheck.Email = ""
   240		}
   241	
   242		_, err = getUser(s, userToCheck, false)
   243		if err != nil {
   244			if IsErrUserDoesNotExist(err) {
   245				exists = false
   246			} else {
   247				return err
   248			}
   249		}
   250		if exists && user.Issuer == IssuerLocal {
   251			return ErrUserEmailExists{user.ID, user.Email}
   252		}
   253	
   254		return nil
   255	}
