   123	func sendEmailConfirmation(s *xorm.Session, u *User) (err error) {
   124		// Kept outside the db so the cooldown survives cancelling the change or rotating tokens.
   125		cooldownKey := emailConfirmationCooldownKey(u.ID)
   126		lastSent, exists, err := keyvalue.Get(cooldownKey)
   127		if err != nil {
   128			return
   129		}
   130		if exists {
   131			var sentAt int64
   132			switch v := lastSent.(type) {
   133			case int64:
   134				sentAt = v
   135			case float64:
   136				sentAt = int64(v)
   137			}
   138			if time.Since(time.Unix(sentAt, 0)) < emailConfirmationResendCooldown {
   139				return ErrEmailConfirmationCooldown{UserID: u.ID}
   140			}
   141		}
   142	
   143		err = removeTokens(s, u, TokenEmailConfirm)
   144		if err != nil {
   145			return
   146		}
   147	
   148		token, err := generateToken(s, u, TokenEmailConfirm)
   149		if err != nil {
   150			return
   151		}
   152	
   153		// RouteForMail sends to User.Email; swap in the pending address on a copy.
   154		recipient := *u
   155		recipient.Email = u.PendingEmail
   156	
   157		n := &EmailConfirmNotification{
   158			User:         &recipient,
   159			IsNew:        false,
   160			ConfirmToken: token.ClearTextToken,
   161		}
   162	
   163		err = notifications.Notify(&recipient, n, s)
   164		if err != nil {
   165			return
   166		}
   167	
   168		return keyvalue.Put(cooldownKey, time.Now().Unix())
   169	}
