     9	// Confirm tokens are exempt from the cleanup cron so registration links never expire; change links must.
    10	const emailChangeTokenValidity = 24 * time.Hour
    11	
    12	// EmailConfirm holds the token to confirm a mail address
    13	type EmailConfirm struct {
    14		// The email confirm token sent via email.
    15		Token string `json:"token"`
    16	}
    17	
    18	// ConfirmEmail handles the confirmation of an email address
    19	func ConfirmEmail(s *xorm.Session, c *EmailConfirm) (err error) {
    20	
    21		// Check if we have an email confirm token
    22		if c.Token == "" {
    23			return ErrInvalidEmailConfirmToken{}
    24		}
    25	
    26		token, err := getToken(s, c.Token, TokenEmailConfirm)
    27		if err != nil {
    28			return
    29		}
    30		if token == nil {
    31			return ErrInvalidEmailConfirmToken{Token: c.Token}
    32		}
    33	
    34		if token.UserID < 1 {
    35			return ErrInvalidEmailConfirmToken{Token: c.Token}
    36		}
    37	
    38		user, err := GetUserWithEmail(s, &User{ID: token.UserID})
    39		if err != nil {
    40			// A locked account may still activate its registration, but not swap its login address.
    41			if !IsErrAccountLocked(err) || user.PendingEmail != "" {
    42				return err
    43			}
    44		}
    45	
    46		var cols []string
    47		if user.PendingEmail != "" {
    48			if time.Since(token.Created) > emailChangeTokenValidity {
    49				if err := removeTokenByID(s, user, TokenEmailConfirm, token.ID); err != nil {
    50					return err
    51				}
    52				return ErrInvalidEmailConfirmToken{Token: c.Token}
    53			}
    54	
    55			// Someone else may have claimed the address since the change was requested.
    56			if err := checkEmailNotTaken(s, user.PendingEmail); err != nil {
