     9	// PasswordReset holds the data to reset a password
    10	type PasswordReset struct {
    11		// The previously issued reset token.
    12		Token string `json:"token"`
    13		// The new password for this user.
    14		NewPassword string `json:"new_password" valid:"bcrypt_password" minLength:"8" maxLength:"72"`
    15	}
    16	
    17	// ResetPassword resets a users password. It returns the ID of the user whose
    18	// password was reset so callers can perform additional cleanup (e.g. session
    19	// invalidation).
    20	func ResetPassword(s *xorm.Session, reset *PasswordReset) (userID int64, err error) {
    21	
    22		// Check if the password is not empty
    23		if reset.NewPassword == "" {
    24			return 0, ErrNoUsernamePassword{}
    25		}
    26	
    27		if reset.Token == "" {
    28			return 0, ErrNoPasswordResetToken{}
    29		}
    30	
    31		// Check if we have a token
    32		token, err := getToken(s, reset.Token, TokenPasswordReset)
    33		if err != nil {
    34			return 0, err
    35		}
    36		if token == nil {
    37			return 0, ErrInvalidPasswordResetToken{Token: reset.Token}
    38		}
    39	
    40		user, err := GetUserByID(s, token.UserID)
    41		if err != nil && !IsErrAccountLocked(err) {
    42			return 0, err
    43		}
    44		userID = user.ID
    45	
    46		// Hash the password
    47		user.Password, err = HashPassword(reset.NewPassword)
    48		if err != nil {
    49			return
    50		}
    51	
    52		err = removeTokens(s, user, TokenPasswordReset)
    53		if err != nil {
    54			return
    55		}
    56	
    57		if user.Status == StatusAccountLocked || user.Status == StatusEmailConfirmationRequired {
    58			user.Status = StatusActive
    59		}
    60		_, err = s.
    61			Cols("password", "status").
    62			Where("id = ?", user.ID).
    63			Update(user)
    64		if err != nil {
    65			return
    66		}
    67	
    68		// Dont send a mail if no mailer is configured
    69		if !config.MailerEnabled.GetBool() {
    70			return
    71		}
    72	
    73		// Send a mail to the user to notify it his password was changed.
    74		n := &PasswordChangedNotification{
    75			User: user,
    76		}
    77	
    78		err = notifications.Notify(user, n, s)
    79		return
    80	}
