    87	// RequestUserPasswordResetTokenByEmail inserts a random token to reset a users password into the databsse
    88	func RequestUserPasswordResetTokenByEmail(s *xorm.Session, tr *PasswordTokenRequest) (err error) {
    89		if tr.Email == "" {
