   138			if time.Since(time.Unix(sentAt, 0)) < emailConfirmationResendCooldown {
   139				return ErrEmailConfirmationCooldown{UserID: u.ID}
   140			}
   141		}
   142	
   143		err = removeTokens(s, u, TokenEmailConfirm)
   144		if err != nil {
