    15	
    16	func RegisterDeletionNotificationCron() {
    17		err := cron.Schedule("0 * * * *", notifyUsersScheduledForDeletion)
    18		if err != nil {
    19			log.Errorf("Could not register deletion cron: %s", err.Error())
    20		}
    21	}
    22	
    23	func notifyUsersScheduledForDeletion() {
    24		s := db.NewSession()
    25		users := []*User{}
    26		err := s.Where(builder.NotNull{"deletion_scheduled_at"}).
    27			Find(&users)
    28		s.Close()
    29		if err != nil {
    30			log.Errorf("Could not get users scheduled for deletion: %s", err)
    31			return
    32		}
    33	
    34		if len(users) == 0 {
    35			return
    36		}
    37	
    38		log.Debugf("Found %d users scheduled for deletion to notify", len(users))
    39	
    40		for _, user := range users {
    41			if time.Since(user.DeletionLastReminderSent) < time.Hour*24 {
    42				continue
    43			}
    44	
    45			var number = 2
    46			if user.DeletionLastReminderSent.IsZero() {
    47				number = 3
    48			}
    49			if user.DeletionScheduledAt.Sub(user.DeletionLastReminderSent) < time.Hour*24 {
    50				number = 1
    51			}
    52	
    53			log.Debugf("Notifying user %d of the deletion of their account...", user.ID)
    54	
    55			if err := notifyUserOfDeletion(user, number); err != nil {
    56				log.Errorf("Could not process deletion notification for user %d: %s", user.ID, err)
    57			}
    58		}
    59	}
    60	
    61	func notifyUserOfDeletion(user *User, number int) error {
    62		s := db.NewSession()
    63		defer s.Close()
    64	
    65		err := notifications.Notify(user, &AccountDeletionNotification{
    66			User:               user,
    67			NotificationNumber: number,
    68		}, s)
    69		if err != nil {
    70			return fmt.Errorf("could not notify user: %w", err)
    71		}
    72	
    73		user.DeletionLastReminderSent = time.Now()
    74		_, err = s.Where("id = ?", user.ID).
    75			Cols("deletion_last_reminder_sent").
    76			Update(user)
    77		if err != nil {
    78			return fmt.Errorf("could not update last deletion reminder sent date: %w", err)
    79		}
    80	
    81		return s.Commit()
    82	}
