    84	// RequestDeletion creates a user deletion confirm token and sends a notification to the user
    85	func RequestDeletion(s *xorm.Session, user *User) (err error) {
    86		token, err := generateToken(s, user, TokenAccountDeletion)
    87		if err != nil {
    88			return err
    89		}
    90	
    91		return notifications.Notify(user, &AccountDeletionConfirmNotification{
    92			User:         user,
    93			ConfirmToken: token.ClearTextToken,
    94		}, s)
    95	}
