    97	// ConfirmDeletion ConformDeletion checks a token and schedules the user for deletion
    98	func ConfirmDeletion(s *xorm.Session, user *User, token string) (err error) {
    99		tk, err := getToken(s, token, TokenAccountDeletion)
   100		if err != nil {
   101			return err
   102		}
   103	
   104		if tk == nil {
   105			return ErrInvalidDeletionToken{
   106				Token: token,
   107			}
   108		}
   109	
   110		if tk.UserID != user.ID {
   111			return ErrTokenUserMismatch{
   112				TokenUserID: tk.UserID,
   113				UserID:      user.ID,
   114			}
   115		}
   116	
   117		err = removeTokens(s, user, TokenAccountDeletion)
   118		if err != nil {
   119			return err
   120		}
   121	
   122		return ScheduleDeletion(s, user)
   123	}
   124	
   125	func ScheduleDeletion(s *xorm.Session, user *User) (err error) {
   126		user.DeletionScheduledAt = time.Now().Add(3 * 24 * time.Hour)
   127		_, err = s.Where("id = ?", user.ID).
   128			Cols("deletion_scheduled_at").
   129			Update(user)
   130		return err
   131	}
   132	
   133	// CancelDeletion cancels the deletion of a user
   134	func CancelDeletion(s *xorm.Session, user *User) (err error) {
   135		user.DeletionScheduledAt = time.Time{}
   136		user.DeletionLastReminderSent = time.Time{}
   137		_, err = s.Where("id = ?", user.ID).
   138			Cols("deletion_scheduled_at", "deletion_last_reminder_sent").
   139			Update(user)
   140		return
   141	}
