    12	func init() {
    13		govalidator.TagMap["username"] = func(i string) bool {
    14			// To avoid making this overly complicated, we only check a few things:
    15			// 1. No Spaces
    16			// 2. Should not look like an url
    17			// 3. Should not contain , (because then it will be impossible to search for)
    18			// 4. Should not start with link-share-[NUMBER] (reserved for link sharing system)
    19			if govalidator.HasWhitespace(i) {
    20				return false
    21			}
    22	
    23			if govalidator.IsURL(i) {
    24				return false
    25			}
    26	
    27			if strings.Contains(i, ",") {
    28				return false
    29			}
    30	
    31			// Check if username matches the reserved link-share pattern
    32			linkSharePattern := regexp.MustCompile(`^link-share-\d+$`)
    33			return !linkSharePattern.MatchString(i)
    34		}
    35	
    36		govalidator.TagMap["bcrypt_password"] = func(str string) bool {
    37			if len(str) < 8 {
    38				return false
    39			}
    40	
    41			return len([]byte(str)) <= 72
    42		}
    43	
    44		govalidator.TagMap["language"] = i18n.HasLanguage
    45	
    46		// Custom type validator: TagMap validators see Status.String(), not the number.
    47		govalidator.CustomTypeTagMap.Set("bot_status", func(i, _ any) bool {
    48			switch s := i.(type) {
    49			case Status:
    50				return s == StatusActive || s == StatusDisabled
    51			case *Status:
    52				return s == nil || *s == StatusActive || *s == StatusDisabled
    53			}
