     3	import (
     4		"xorm.io/builder"
     5	)
     6	
     7	// IsBotOwnedBy reports whether u is a bot owned by owner.
     8	func (u *User) IsBotOwnedBy(owner *User) bool {
     9		return u.IsBot() && u.BotOwnerID == owner.ID
    10	}
    11	
    12	// SameBotIdentityCond matches a user ID column against users sharing u's root:
    13	// a bot's owner or a human themselves. It is symmetric across an owner's fleet.
    14	//
    15	// The root is resolved in SQL so the result never depends on how populated the
    16	// passed struct happens to be; callers routinely hold a User carrying only an ID.
    17	//
    18	// Resolving only one owner hop keeps accidental bot chains out of a human's identity set.
    19	//
    20	// column is interpolated as a raw SQL identifier and must be a trusted literal.
    21	func SameBotIdentityCond(u *User, column string) builder.Cond {
    22		if u == nil || u.ID <= 0 {
    23			// Humans are stored with bot_owner_id = 0, so an unguarded zero id would
    24			// match every one of them.
    25			return builder.In(column, []int64{})
    26		}
    27	
    28		root := builder.Select("bot_owner_id").From("users").
    29			Where(builder.And(builder.Eq{"id": u.ID}, builder.Gt{"bot_owner_id": 0}))
    30	
    31		return builder.In(column,
    32			builder.Select("id").From("users").Where(builder.Or(
    33				builder.Eq{"id": u.ID},
    34				builder.Eq{"bot_owner_id": u.ID},
    35				builder.In("id", root),
    36				builder.In("bot_owner_id", root),
    37			)),
    38		)
    39	}
