   111	type LogoutResponse struct {
   112		Message string `json:"message"`
   113		// RP-Initiated Logout URL the frontend redirects to. Empty for non-OIDC sessions.
   114		OIDCLogoutURL string `json:"oidc_logout_url,omitempty"`
   115	}
   116	
   117	// Logout deletes the current session from the server.
   118	func Logout(c *echo.Context) (err error) {
   119		auth.ClearRefreshTokenCookie(c)
   120	
   121		var sid string
   122		var userID int64
   123		if raw := c.Get("user"); raw != nil {
   124			if jwtinf, ok := raw.(*jwt.Token); ok {
   125				if claims, ok := jwtinf.Claims.(jwt.MapClaims); ok {
   126					sid, _ = claims["sid"].(string)
   127					// Only user tokens carry a sid, but check the type explicitly
   128					// so a link share id can never be logged as a user id.
   129					if typ, ok := claims["type"].(float64); ok && int(typ) == auth.AuthTypeUser {
   130						if id, ok := claims["id"].(float64); ok {
   131							userID = int64(id)
   132						}
   133					}
   134				}
   135			}
   136		}
   137	
   138		oidcLogoutURL, err := shared.LogoutSession(sid)
   139		if err != nil {
   140			return err
   141		}
   142	
   143		if userID != 0 {
   144			if err := events.DispatchWithContext(c.Request().Context(), &user2.LogoutEvent{UserID: userID}); err != nil {
   145				log.Errorf("Could not dispatch logout event: %s", err)
   146			}
   147		}
   148	
   149		return c.JSON(http.StatusOK, LogoutResponse{
   150			Message:       "Successfully logged out.",
   151			OIDCLogoutURL: oidcLogoutURL,
   152		})
   153	}
