    19	// Login is the login handler
    20	func Login(c *echo.Context) (err error) {
    21		u := user2.Login{}
    22		if err := c.Bind(&u); err != nil {
    23			return c.JSON(http.StatusBadRequest, models.Message{Message: "Please provide a username and password."})
    24		}
    25	
