    34	
    35	// RenewToken renews a link share token only. User tokens must use
    36	// POST /user/token/refresh with a refresh token instead.
    37	func RenewToken(c *echo.Context) (err error) {
    38		jwtinf := c.Get("user").(*jwt.Token)
    39		claims := jwtinf.Claims.(jwt.MapClaims)
    40		typFloat, is := claims["type"].(float64)
    41		if !is {
    42			return echo.NewHTTPError(http.StatusBadRequest, "Invalid JWT token.")
    43		}
    44		typ := int(typFloat)
    45	
    46		if typ == auth.AuthTypeUser {
    47			return echo.NewHTTPError(
    48				http.StatusBadRequest,
    49				"User tokens cannot be renewed via this endpoint. Use POST /user/token/refresh with a refresh token.",
    50			)
    51		}
    52	
    53		if typ != auth.AuthTypeLinkShare {
    54			return echo.NewHTTPError(http.StatusBadRequest, "Invalid token type.")
    55		}
    56	
    57		s := db.NewSession()
    58		defer s.Close()
    59	
    60		share := &models.LinkSharing{}
    61		idFloat, is := claims["id"].(float64)
    62		if !is {
    63			return echo.NewHTTPError(http.StatusBadRequest, "Invalid JWT token.")
    64		}
    65		share.ID = int64(idFloat)
    66		err = share.ReadOne(s, share)
    67		if err != nil {
    68			_ = s.Rollback()
    69			return err
    70		}
    71		t, err := auth.NewLinkShareJWTAuthtoken(share)
    72		if err != nil {
    73			_ = s.Rollback()
    74			return err
    75		}
    76	
    77		if err := s.Commit(); err != nil {
    78			_ = s.Rollback()
    79			return err
    80		}
    81	
    82		return c.JSON(http.StatusOK, auth.Token{Token: t})
    83	}
    84	
    85	// RefreshToken exchanges a valid refresh token (sent as an HttpOnly cookie) for
    86	// a new short-lived JWT. The refresh token is rotated on every call.
    87	func RefreshToken(c *echo.Context) (err error) {
    88		cookie, err := c.Cookie(auth.RefreshTokenCookieName)
    89		if err != nil || cookie.Value == "" {
    90			return &models.ErrNoRefreshToken{}
    91		}
    92	
    93		result, err := auth.RefreshSession(cookie.Value)
    94		if err != nil {
    95			if auth.IsUnusableRefreshToken(err) {
    96				auth.ClearRefreshTokenCookie(c)
    97			}
    98			return err
    99		}
   100	
   101		cookieMaxAge := int(config.ServiceJWTTTL.GetInt64())
   102		if result.IsLongSession {
   103			cookieMaxAge = int(config.ServiceJWTTTLLong.GetInt64())
   104		}
   105		auth.SetRefreshTokenCookie(c, result.NewRefreshToken, cookieMaxAge)
   106	
   107		c.Response().Header().Set("Cache-Control", "no-store")
   108		return c.JSON(http.StatusOK, auth.Token{Token: result.AccessToken})
   109	}
