=== routes/api/shared/auth.go
     1	package shared
     2	
     3	import (
     4		"context"
     5	
     6		"code.vikunja.io/api/pkg/config"
     7		"code.vikunja.io/api/pkg/db"
     8		"code.vikunja.io/api/pkg/events"
     9		"code.vikunja.io/api/pkg/log"
    10		"code.vikunja.io/api/pkg/metrics"
    11		"code.vikunja.io/api/pkg/models"
    12		"code.vikunja.io/api/pkg/modules/auth"
    13		"code.vikunja.io/api/pkg/modules/auth/ldap"
    14		"code.vikunja.io/api/pkg/modules/auth/openid"
    15		"code.vikunja.io/api/pkg/modules/keyvalue"
    16		"code.vikunja.io/api/pkg/user"
    17	
    18		"xorm.io/xorm"
    19	)
    20	
    21	// UserRegister carries the fields accepted by the public registration endpoint:
    22	// username, password and email (from APIUserPassword) plus the new user's
    23	// preferred language.
    24	type UserRegister struct {
    25		// The language of the new user. Must be a valid IETF BCP 47 language code and exist in Vikunja.
    26		Language string `json:"language" valid:"language" doc:"The language of the new user as an IETF BCP 47 code (e.g. en, de-DE)."`
    27		user.APIUserPassword
    28	}
    29	
    30	// RegisterUser creates a new local user account from the registration input and
    31	// busts the cached user-count metric so the registration shows up immediately.
    32	// The caller is responsible for the registration-enabled gate and input
    33	// validation; both v1 and v2 share this body.
    34	func RegisterUser(ctx context.Context, in *UserRegister) (*user.User, error) {
    35		s := db.NewSession()
    36		defer s.Close()
    37		// Discards events queued during a rolled-back transaction; a no-op once
    38		// DispatchPending has run.
    39		defer events.CleanupPending(s)
    40	
    41		newUser, err := models.RegisterUser(s, &user.User{
    42			Username: in.Username,
    43			Password: in.Password,
    44			Email:    in.Email,
    45			Language: in.Language,
    46		})
    47		if err != nil {
    48			_ = s.Rollback()
    49			return nil, err
    50		}
    51	
    52		if err := CommitRegistration(ctx, s); err != nil {
    53			return nil, err
    54		}
    55		return newUser, nil
    56	}
    57	
    58	func CommitRegistration(ctx context.Context, s *xorm.Session) error {
    59		if err := s.Commit(); err != nil {
    60			_ = s.Rollback()
    61			return err
    62		}
    63	
    64		events.DispatchPending(ctx, s)
    65	
    66		// Bust the cached user count so the new registration shows up in metrics
    67		// immediately instead of after the regular cache expiry.
    68		if config.MetricsEnabled.GetBool() {
    69			if err := metrics.InvalidateCount(metrics.UserCountKey); err != nil {
    70				log.Errorf("Could not invalidate user count metric: %s", err)
    71			}
    72		}
    73	
    74		return nil
    75	}
    76	
    77	// AuthenticateUserCredentials verifies a login against local (and, if configured,
    78	// LDAP) credentials and enforces the account-status and TOTP gates, returning the
    79	// authenticated user on success. It is the transport-agnostic core of the login
    80	// flow shared by v1 and v2; the caller issues the token and sets the cookie. The
    81	// returned errors carry their own HTTP semantics (wrong credentials, disabled
    82	// account, missing/invalid TOTP) so both APIs surface them identically.
    83	func AuthenticateUserCredentials(ctx context.Context, login *user.Login) (*user.User, error) {
    84		s := db.NewSession()
    85		defer s.Close()
    86		// Discards events queued during a rolled-back transaction (e.g. LDAP user
    87		// creation); a no-op once DispatchPending has run.
    88		defer events.CleanupPending(s)
    89	
    90		u, err := resolveLoginUser(ctx, s, login)
    91		if err != nil {
    92			_ = s.Rollback()
    93			return nil, err
    94		}
    95	
    96		if u.Status == user.StatusDisabled {
    97			_ = s.Rollback()
    98			return nil, &user.ErrAccountDisabled{UserID: u.ID}
    99		}
   100		if u.Status == user.StatusAccountLocked {
   101			_ = s.Rollback()
   102			return nil, &user.ErrAccountLocked{UserID: u.ID}
   103		}
   104	
   105		if err := enforceLoginTOTP(s, u, login.TOTPPasscode); err != nil {
   106			return nil, err
   107		}
   108	
   109		if err := keyvalue.Del(u.GetFailedTOTPAttemptsKey()); err != nil {
   110			return nil, err
   111		}
   112		if err := keyvalue.Del(u.GetFailedPasswordAttemptsKey()); err != nil {
   113			return nil, err
   114		}
   115	
   116		if err := s.Commit(); err != nil {
   117			_ = s.Rollback()
   118			return nil, err
   119		}
   120	
   121		events.DispatchPending(ctx, s)
   122	
   123		return u, nil
   124	}
   125	
   126	// resolveLoginUser authenticates the credentials against LDAP (when enabled) and
   127	// then against local accounts, mirroring v1's order so local users keep working
   128	// alongside LDAP. Bots are rejected before bcrypt runs because they have no
   129	// password hash.
   130	func resolveLoginUser(ctx context.Context, s *xorm.Session, login *user.Login) (*user.User, error) {
   131		if config.AuthLdapEnabled.GetBool() {
   132			u, err := ldap.AuthenticateUserInLDAP(s, login.Username, login.Password, config.AuthLdapGroupSyncEnabled.GetBool(), config.AuthLdapAvatarSyncAttribute.GetString())
   133			if err != nil && !user.IsErrWrongUsernameOrPassword(err) {
   134				return nil, err
   135			}
   136			if u != nil {
   137				return u, nil
   138			}
   139		}
   140	
   141		existingUser, lookupErr := user.GetUserByUsername(s, login.Username)
   142		if lookupErr == nil && existingUser.IsBot() {
   143			return nil, &user.ErrAccountIsBot{UserID: existingUser.ID}
   144		}
   145	
   146		return user.CheckUserCredentials(ctx, s, login)
   147	}
   148	
   149	// enforceLoginTOTP runs the TOTP gate for users who have it enabled, mirroring
   150	// v1: a missing passcode is rejected, and a wrong one trips the failed-attempt
   151	// lockout via HandleFailedTOTPAuth. The session is rolled back before
   152	// HandleFailedTOTPAuth so its dedicated session can acquire a write lock on
   153	// SQLite shared-cache (the lockout write is decoupled from this transaction —
   154	// see GHSA-fgfv-pv97-6cmj).
   155	func enforceLoginTOTP(s *xorm.Session, u *user.User, passcode string) error {
   156		totpEnabled, err := user.TOTPEnabledForUser(s, u)
   157		if err != nil {
   158			_ = s.Rollback()
   159			return err
   160		}
   161		if !totpEnabled {
   162			return nil
   163		}
   164	
   165		if passcode == "" {
   166			_ = s.Rollback()
   167			return user.ErrInvalidTOTPPasscode{}
   168		}
   169	
   170		_, err = user.ValidateTOTPPasscode(s, &user.TOTPPasscode{User: u, Passcode: passcode})
   171		if err != nil {
   172			_ = s.Rollback()
   173			if user.IsErrInvalidTOTPPasscode(err) {
   174				user.HandleFailedTOTPAuth(u)
   175			}
   176			return err
   177		}
   178	
   179		return nil
   180	}
   181	
   182	// DeleteSession removes the session with the given id, logging the user out
   183	// server-side. An empty sid is a no-op (the token carried no session, e.g. an
   184	// API token or a link share), matching v1. Shared by v1 and v2; the caller is
   185	// responsible for clearing the refresh cookie.
   186	func DeleteSession(sid string) error {
   187		_, err := LogoutSession(sid)
   188		return err
   189	}
   190	
   191	// LogoutSession deletes the session and returns its OIDC RP-Initiated Logout URL
   192	// for the frontend to redirect to (empty for non-OIDC sessions or when no logout
   193	// endpoint is configured). An empty sid is a no-op. The caller clears the refresh
   194	// cookie.
   195	func LogoutSession(sid string) (endSessionURL string, err error) {
   196		if sid == "" {
   197			return "", nil
   198		}
   199	
   200		s := db.NewSession()
   201		defer s.Close()
   202		defer events.CleanupPending(s)
   203	
   204		// A missing session just means there is nothing to log out.
   205		session, err := models.DeleteSessionByID(s, sid)
   206		if models.IsErrSessionNotFound(err) {
   207			return "", nil
   208		}
   209		if err != nil {
   210			_ = s.Rollback()
   211			return "", err
   212		}
   213		if session.OIDCProviderKey != "" {
   214			url, buildErr := openid.BuildEndSessionURL(session.OIDCProviderKey, &models.SessionOIDCData{
   215				IDToken:     session.OIDCIDToken,
   216				ProviderKey: session.OIDCProviderKey,
   217			})
   218			if buildErr != nil {
   219				// A failed URL build must not block logout.
   220				log.Errorf("Could not build OIDC end-session URL for session %s: %v", sid, buildErr)
   221			} else {
   222				endSessionURL = url
   223			}
   224		}
   225	
   226		if err := s.Commit(); err != nil {
   227			_ = s.Rollback()
   228			return "", err
   229		}
