   301	// AuthenticateLinkShare resolves a link share by its public hash, verifies the
   302	// password for password-protected shares, and issues a JWT auth token for it.
   303	// The returned token's embedded share has its password blanked. Shared by v1
   304	// and v2.
   305	func AuthenticateLinkShare(hash, password string) (*LinkShareToken, error) {
   306		s := db.NewSession()
   307		defer s.Close()
   308	
   309		share, err := models.GetLinkShareByHash(s, hash)
   310		if err != nil {
   311			_ = s.Rollback()
   312			return nil, err
   313		}
   314	
   315		if share.SharingType == models.SharingTypeWithPassword {
   316			if err := models.VerifyLinkSharePassword(share, password); err != nil {
   317				_ = s.Rollback()
   318				return nil, err
   319			}
   320		}
