   192	// RotateRefreshToken atomically replaces the session's refresh token hash.
   193	// The WHERE clause includes the old hash so that concurrent refreshes with the
   194	// same token cannot both succeed — only the first UPDATE matches a row; the
   195	// second sees 0 affected rows and returns ErrSessionNotFound.
   196	func RotateRefreshToken(s *xorm.Session, session *Session) (newRawToken string, err error) {
   197		newRawToken, newHash, err := generateHashedToken()
   198		if err != nil {
   199			return "", err
   200		}
   201	
   202		affected, err := s.Where("id = ? AND token_hash = ?", session.ID, session.TokenHash).
   203			Cols("token_hash").
   204			Update(&Session{TokenHash: newHash})
   205		if err != nil {
   206			return "", err
   207		}
   208		if affected == 0 {
   209			// Another request already rotated this token — reject the replay.
   210			return "", &ErrSessionNotFound{}
   211		}
   212		return newRawToken, nil
   213	}
