    64		events.DispatchPending(ctx, s)
    65	
    66		// Bust the cached user count so the new registration shows up in metrics
    67		// immediately instead of after the regular cache expiry.
    68		if config.MetricsEnabled.GetBool() {
    69			if err := metrics.InvalidateCount(metrics.UserCountKey); err != nil {
