   235	// ResetPassword resets a user's password from a previously issued reset token
   236	// and invalidates all of that user's sessions, so a leaked password cannot be
   237	// used after a reset. Shared by v1 and v2.
   238	func ResetPassword(reset *user.PasswordReset) error {
   239		s := db.NewSession()
   240		defer s.Close()
   241		defer events.CleanupPending(s)
   242	
   243		userID, err := user.ResetPassword(s, reset)
   244		if err != nil {
   245			_ = s.Rollback()
   246			return err
   247		}
   248	
   249		if err := models.DeleteAllUserSessions(s, userID); err != nil {
   250			_ = s.Rollback()
   251			return err
   252		}
   253	
   254		if err := s.Commit(); err != nil {
   255			return err
   256		}
   257		events.DispatchPending(context.Background(), s)
   258		return nil
   259	}
