   289	// LinkShareToken is the response for the link-share auth endpoint. It embeds the
   290	// authenticated share alongside the issued JWT and re-exposes the project id
   291	// (which LinkSharing hides with json:"-"). The embedded share's write-only
   292	// Password is blanked by AuthenticateLinkShare before this is returned.
   293	type LinkShareToken struct {
   294		auth.Token
   295		// Embedded by value: a pointer embed's method set is never empty, which
   296		// breaks Huma's $schema wrapper (go#15924).
   297		models.LinkSharing
   298		ProjectID int64 `json:"project_id" readOnly:"true" doc:"The id of the project this share grants access to."`
   299	}
   300	
   301	// AuthenticateLinkShare resolves a link share by its public hash, verifies the
   302	// password for password-protected shares, and issues a JWT auth token for it.
   303	// The returned token's embedded share has its password blanked. Shared by v1
   304	// and v2.
   305	func AuthenticateLinkShare(hash, password string) (*LinkShareToken, error) {
   306		s := db.NewSession()
   307		defer s.Close()
   308	
   309		share, err := models.GetLinkShareByHash(s, hash)
   310		if err != nil {
   311			_ = s.Rollback()
   312			return nil, err
   313		}
   314	
   315		if share.SharingType == models.SharingTypeWithPassword {
   316			if err := models.VerifyLinkSharePassword(share, password); err != nil {
   317				_ = s.Rollback()
   318				return nil, err
   319			}
   320		}
   321	
   322		t, err := auth.NewLinkShareJWTAuthtoken(share)
   323		if err != nil {
   324			_ = s.Rollback()
   325			return nil, err
   326		}
   327	
   328		if err := s.Commit(); err != nil {
   329			_ = s.Rollback()
   330			return nil, err
   331		}
   332	
   333		share.Password = ""
   334	
   335		return &LinkShareToken{
   336			Token:       auth.Token{Token: t},
   337			LinkSharing: *share,
   338			ProjectID:   share.ProjectID,
   339		}, nil
   340	}
