    53	// HashSessionToken returns the hex-encoded SHA-256 hash of a token string.
    54	// No salt needed because refresh tokens are high-entropy random strings,
    55	// not human passwords — rainbow tables and dictionary attacks don't apply.
    56	func HashSessionToken(token string) string {
    57		return utils.Sha256Hex(token)
    58	}
    59	
    60	// generateHashedToken creates a cryptographically random token and returns both
    61	// the raw hex-encoded token (to give to the client) and its SHA-256 hash (to store).
    62	func generateHashedToken() (rawToken, hash string, err error) {
    63		tokenBytes, err := utils.CryptoRandomBytes(128)
    64		if err != nil {
    65			return "", "", err
    66		}
    67		rawToken = hex.EncodeToString(tokenBytes)
    68		return rawToken, HashSessionToken(rawToken), nil
    69	}
