    71	// SessionOIDCData carries the OIDC metadata persisted on a session so an
    72	// RP-Initiated Logout request can be built later. Nil for non-OIDC logins.
    73	type SessionOIDCData struct {
    74		IDToken     string
    75		ProviderKey string
    76	}
