    78	// CreateSession creates a new session record and generates a refresh token.
    79	// Returns the session with RefreshToken populated (cleartext, shown only once).
    80	// Pass oidc for OpenID Connect logins to persist the logout data; nil otherwise.
    81	func CreateSession(s *xorm.Session, userID int64, deviceInfo, ipAddress string, isLongSession bool, oidc *SessionOIDCData) (*Session, error) {
    82		rawToken, hash, err := generateHashedToken()
    83		if err != nil {
    84			return nil, err
    85		}
    86	
    87		session := &Session{
    88			ID:            uuid.New().String(),
    89			UserID:        userID,
    90			TokenHash:     hash,
    91			DeviceInfo:    deviceInfo,
    92			IPAddress:     ipAddress,
    93			IsLongSession: isLongSession,
    94			LastActive:    time.Now(),
    95		}
    96		if oidc != nil {
    97			session.OIDCIDToken = oidc.IDToken
    98			session.OIDCProviderKey = oidc.ProviderKey
    99		}
   100	
   101		_, err = s.Insert(session)
   102		if err != nil {
   103			return nil, err
   104		}
   105	
   106		session.RefreshToken = rawToken
   107		return session, nil
   108	}
