   137	// ReadAll returns all sessions for the authenticated user.
   138	func (sess *Session) ReadAll(s *xorm.Session, a web.Auth, _ string, page int, perPage int) (result interface{}, resultCount int, numberOfTotalItems int64, err error) {
   139		// Link share tokens must not be able to list user sessions.
   140		if _, is := a.(*LinkSharing); is {
   141			return nil, 0, 0, ErrGenericForbidden{}
   142		}
   143	
   144		sessions := []*Session{}
   145	
   146		var where builder.Cond = builder.Eq{"user_id": a.GetID()}
   147	
   148		err = s.
   149			Where(where).
   150			OrderBy("last_active DESC, id DESC").
   151			Limit(getLimitFromPageIndex(page, perPage)).
   152			Find(&sessions)
   153		if err != nil {
   154			return nil, 0, 0, err
   155		}
   156	
   157		totalCount, err := s.Where(where).Count(&Session{})
   158		return sessions, len(sessions), totalCount, err
   159	}
