   225	// RegisterSessionCleanupCron registers a cron to delete sessions whose refresh
   226	// tokens have expired. Uses is_long_session to pick the right cutoff so short
   227	// sessions don't linger for the full long TTL. Runs hourly.
   228	func RegisterSessionCleanupCron() {
   229		const logPrefix = "[Session Cleanup Cron] "
   230	
   231		err := cron.Schedule("0 * * * *", func() {
   232			s := db.NewSession()
   233			defer s.Close()
   234	
   235			now := time.Now()
   236			shortMaxAge := time.Duration(config.ServiceJWTTTL.GetInt64()) * time.Second
   237			longMaxAge := time.Duration(config.ServiceJWTTTLLong.GetInt64()) * time.Second
   238	
   239			// Delete short sessions older than ServiceJWTTTL
   240			// and long sessions older than ServiceJWTTTLLong
   241			deleted, err := s.
   242				Where("(is_long_session = ? AND last_active < ?) OR (is_long_session = ? AND last_active < ?)",
   243					false, now.Add(-shortMaxAge),
   244					true, now.Add(-longMaxAge)).
   245				Delete(&Session{})
   246			if err != nil {
   247				log.Errorf(logPrefix+"Error removing stale sessions: %s", err)
   248				return
   249			}
   250			if deleted > 0 {
   251				log.Debugf(logPrefix+"Deleted %d stale sessions", deleted)
   252			}
   253	
   254			if err := s.Commit(); err != nil {
   255				log.Errorf(logPrefix+"Could not commit: %s", err)
   256			}
   257		})
   258		if err != nil {
   259			log.Fatalf("Could not register session cleanup cron: %s", err)
   260		}
   261	}
