 19		"code.vikunja.io/api/pkg/web"
 20	
 21		petname "github.com/dustinkirkland/golang-petname"
 22		"github.com/golang-jwt/jwt/v5"
 23		"github.com/google/uuid"
 24		"github.com/labstack/echo/v5"
 25		"xorm.io/xorm"
 26	)
 27	
 28	// All valid auth types; AuthTypeUser lives in pkg/user since
 29	// that package parses claims and can't import this one.
 30	const (
 31		AuthTypeUnknown   int = 0
 32		AuthTypeUser          = user.AuthTypeUser
 33		AuthTypeLinkShare int = 2
 34	)
 35	
 36	// Token represents an authentication token
 37	type Token struct {
 38		Token string `json:"token" example:"eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJzdWIiOiIxMjM0NTY3ODkwIiwibmFtZSI6IkpvaG4gRG9lIiwiaWF0IjoxNTE2MjM5MDIyfQ.SflKxwRJSMeKKF2QT4fwpMeJf36POk6yJV_adQssw5c"`
 39	}
 40	
 41	const RefreshTokenCookieName = "vikunja_refresh_token" //nolint:gosec // not a credential
 42	
 43	const (
 44		RefreshTokenPathV1 = "/api/v1/user/token/refresh" //nolint:gosec // a route path, not a credential
 45		RefreshTokenPathV2 = "/api/v2/user/token/refresh" //nolint:gosec // a route path, not a credential
 46	)
 47	
 48	// getRefreshTokenCookiePaths prefixes each refresh endpoint with the base
 49	// path from service.publicurl.
 50	func getRefreshTokenCookiePaths() []string {
 51		basePath := ""
 52		if u, err := url.Parse(config.ServicePublicURL.GetString()); err == nil {
 53			basePath = strings.TrimRight(u.Path, "/")
 54		}
 55	
 56		refreshTokenPaths := []string{RefreshTokenPathV1, RefreshTokenPathV2}
 57		paths := make([]string, len(refreshTokenPaths))
 58		for i, p := range refreshTokenPaths {
 59			paths[i] = basePath + p
 60		}
 61		return paths
 62	}
 63	
 64	// SetRefreshTokenCookie sets one HttpOnly cookie per refresh endpoint (v1, v2),
 65	// path-scoped so the browser only sends it on refresh requests. A single
 66	// cookie at Path=/api would ship the long-lived token on every API request.
 67	// Browsers match cookie paths by prefix, so each endpoint needs its own.
 68	//
 69	// SameSite=Lax, not None: CORS allows localhost origins by default.
 70	func SetRefreshTokenCookie(c *echo.Context, token string, maxAge int) {
 71		secure := strings.HasPrefix(config.ServicePublicURL.GetString(), "https")
 72		for _, path := range getRefreshTokenCookiePaths() {
 73			c.SetCookie(&http.Cookie{ //nolint:gosec // G124: plain-http instances need the cookie too.
 74				Name:     RefreshTokenCookieName,
 75				Value:    token,
 76				Path:     path,
 77				MaxAge:   maxAge,
 78				HttpOnly: true,
 79				Secure:   secure,
 80				SameSite: http.SameSiteLaxMode,
 81			})
 82		}
 83	}
 84	
 85	// ClearRefreshTokenCookie removes the refresh token cookie.
 86	func ClearRefreshTokenCookie(c *echo.Context) {
 87		SetRefreshTokenCookie(c, "", -1)
 88	}
 89	
 90	// IssuedUserToken bundles a freshly minted access token with the matching
 91	// refresh token and the cookie max-age both v1 and v2 use to set the
 92	// HttpOnly refresh cookie.
 93	type IssuedUserToken struct {
 94		AccessToken  string
 95		RefreshToken string
 96		CookieMaxAge int
 97	}
 98	
 99	// IssueUserToken creates a session for the user and mints a JWT access token plus
100	// a refresh token for it. It is the transport-agnostic core both v1 (which writes
101	// the echo response) and v2 (Huma) call; callers set the refresh cookie and the
102	// Cache-Control header themselves via WriteUserAuthCookies. Pass oidc for
103	// OpenID Connect logins to store the logout data; nil otherwise.
104	func IssueUserToken(ctx context.Context, u *user.User, deviceInfo, ipAddress string, long bool, oidc *models.SessionOIDCData) (*IssuedUserToken, error) {
105		s := db.NewSession()
106		defer s.Close()
107	
108		session, err := models.CreateSession(s, u.ID, deviceInfo, ipAddress, long, oidc)
109		if err != nil {
110			_ = s.Rollback()
111			return nil, err
112		}
113	
114		t, err := NewUserJWTAuthtoken(u, session.ID)
115		if err != nil {
116			_ = s.Rollback()
117			return nil, err
118		}
119	
120		if err := s.Commit(); err != nil {
121			_ = s.Rollback()
122			return nil, err
123		}
124	
125		if err := events.DispatchWithContext(ctx, &user.LoginSucceededEvent{User: u}); err != nil {
126			log.Errorf("Could not dispatch login succeeded event: %s", err)
127		}
128	
129		cookieMaxAge := int(config.ServiceJWTTTL.GetInt64())
130		if long {
131			cookieMaxAge = int(config.ServiceJWTTTLLong.GetInt64())
132		}
133	
134		return &IssuedUserToken{
135			AccessToken:  t,
136			RefreshToken: session.RefreshToken,
137			CookieMaxAge: cookieMaxAge,
138		}, nil
139	}
140	
141	// WriteUserAuthCookies sets the HttpOnly refresh-token cookie and the
142	// Cache-Control: no-store header on a response. The cookie is path-scoped to the
143	// refresh endpoint, so the browser only sends it there; JavaScript never sees the
144	// refresh token, which protects it from XSS. Shared by the v1 echo handlers and
145	// the v2 Huma handlers (which reach the echo context via the humabridge
146	// EchoContextKey stash on their request context).
147	func WriteUserAuthCookies(c *echo.Context, token *IssuedUserToken) {
148		SetRefreshTokenCookie(c, token.RefreshToken, token.CookieMaxAge)
149		c.Response().Header().Set("Cache-Control", "no-store")
150	}
151	
152	// NewUserAuthTokenResponse creates a new user auth token response from a user object.
153	// Pass oidc for OpenID Connect logins to store the logout data; nil otherwise.
154	func NewUserAuthTokenResponse(u *user.User, c *echo.Context, long bool, oidc *models.SessionOIDCData) error {
155		token, err := IssueUserToken(c.Request().Context(), u, c.Request().UserAgent(), c.RealIP(), long, oidc)
156		if err != nil {
157			return err
158		}
159	
160		WriteUserAuthCookies(c, token)
161		return c.JSON(http.StatusOK, Token{Token: token.AccessToken})
162	}
163	
164	// NewUserJWTAuthtoken generates and signs a new short-lived jwt token for a user.
165	// The token includes the session UUID as the `sid` claim. This is a global
166	// function to be able to call it from web tests.
167	func NewUserJWTAuthtoken(u *user.User, sessionID string) (token string, err error) {
168		t := jwt.New(jwt.SigningMethodHS256)
169	
170		var ttl = time.Duration(config.ServiceJWTTTLShort.GetInt64())
171		now := time.Now()
172	
173		claims := t.Claims.(jwt.MapClaims)
174		claims["type"] = AuthTypeUser
175		claims["id"] = u.ID
176		claims["username"] = u.Username
177		claims["is_admin"] = u.IsAdmin
178		// The frontend derives its clock offset from iat, so exp is judged by server time.
179		claims["iat"] = now.Unix()
180		claims["exp"] = now.Add(time.Second * ttl).Unix()
181		claims["sid"] = sessionID
182		claims["jti"] = uuid.New().String()
183	
184		return t.SignedString([]byte(config.ServiceSecret.GetString()))
185	}
186	
187	// NewLinkShareJWTAuthtoken creates a new jwt token from a link share
188	func NewLinkShareJWTAuthtoken(share *models.LinkSharing) (token string, err error) {
189		t := jwt.New(jwt.SigningMethodHS256)
190	
191		var ttl = time.Duration(config.ServiceJWTTTL.GetInt64())
192		now := time.Now()
193	
194		// Set claims
195		claims := t.Claims.(jwt.MapClaims)
196		claims["type"] = AuthTypeLinkShare
197		claims["id"] = share.ID
198		claims["hash"] = share.Hash
199		claims["project_id"] = share.ProjectID
200		claims["permission"] = share.Permission
201		claims["sharedByID"] = share.SharedByID
202		claims["iat"] = now.Unix()
203		claims["exp"] = now.Add(time.Second * ttl).Unix()
204	
205		// Generate encoded token and send it as response.
206		return t.SignedString([]byte(config.ServiceSecret.GetString()))
207	}
208	
209	// HasAuthInContext reports whether the request carries credentials at all.
210	func HasAuthInContext(c *echo.Context) bool {
211		if c.Get("api_token") != nil {
212			return true
213		}
214		_, is := c.Get("user").(*jwt.Token)
215		return is
216	}
217	
218	// GetAuthFromClaims returns a web.Auth object from jwt claims
219	func GetAuthFromClaims(c *echo.Context) (a web.Auth, err error) {
220		// The token middleware already loaded the owner; a lookup per call showed up as two extra transactions per request.
221		if u, ok := c.Get("api_user").(*user.User); ok {
222			return u, nil
223		}
224		// check if we have a token in context and use it if that's the case
225		if c.Get("api_token") != nil {
226			apiToken := c.Get("api_token").(*models.APIToken)
227			s := db.NewSession()
228			defer s.Close()
229			u, err := user.GetUserByID(s, apiToken.OwnerID)
230			if err != nil {
231				return nil, err
232			}
233			return u, nil
234		}
235	
236		jwtinf, is := c.Get("user").(*jwt.Token)
237		if !is {
238			return nil, fmt.Errorf("user in context is not jwt token")
239		}
240		claims := jwtinf.Claims.(jwt.MapClaims)
241		typFloat, is := claims["type"].(float64)
242		if !is {
243			return nil, echo.NewHTTPError(http.StatusBadRequest, "Invalid JWT token.")
244		}
245		typ := int(typFloat)
246		if typ == AuthTypeLinkShare && config.ServiceEnableLinkSharing.GetBool() {
247			s := db.NewSession()
248			defer s.Close()
249			return models.GetLinkShareFromClaims(s, claims)
250		}
251		if typ == AuthTypeUser {
252			return user.GetUserFromClaims(claims)
253		}
254		return nil, echo.NewHTTPError(http.StatusBadRequest, "Invalid JWT token.")
255	}
256	
257	// ValidateAPITokenString looks up an API token by its raw string, checks expiry,
258	// and returns the token and its owner. This is the shared validation logic used
259	// by both the HTTP middleware and WebSocket auth.
260	func ValidateAPITokenString(tokenString string) (*models.APIToken, *user.User, error) {
261		s := db.NewReadSession()
262		defer s.Close()
263	
264		token, err := models.GetTokenFromTokenString(s, tokenString)
265		if err != nil {
266			return nil, nil, err
267		}
268	
269		if time.Now().After(token.ExpiresAt) {
270			return nil, nil, fmt.Errorf("API token %d expired on %s", token.ID, token.ExpiresAt.String())
271		}
272	
273		u, err := user.GetUserByID(s, token.OwnerID)
274		if err != nil {
275			if user.IsErrUserStatusError(err) {
276				return nil, nil, fmt.Errorf("API token %d owner account is disabled or locked", token.ID)
277			}
278			return nil, nil, err
279		}
280	
281		return token, u, nil
282	}
283	
284	type UserTokenClaims struct {
285		UserID    int64
286		SessionID string
287		ExpiresAt time.Time
288	}
289	
290	// ErrUserTokenRejected marks errors that retrying cannot fix.
291	var ErrUserTokenRejected = errors.New("user token rejected")
292	
293	// ParseUserToken skips the session check: a valid result may belong to a revoked session.
294	func ParseUserToken(tokenString string) (*UserTokenClaims, error) {
295		token, err := jwt.Parse(tokenString, func(_ *jwt.Token) (any, error) {
296			return []byte(config.ServiceSecret.GetString()), nil
297		})
298		if err != nil {
299			return nil, fmt.Errorf("%w: %w", ErrUserTokenRejected, err)
300		}
301	
302		claims, ok := token.Claims.(jwt.MapClaims)
303		if !ok || !token.Valid {
304			return nil, fmt.Errorf("%w: %w", ErrUserTokenRejected, jwt.ErrTokenInvalidClaims)
305		}
306	
307		typ, ok := claims["type"].(float64)
308		if !ok || int(typ) != AuthTypeUser {
309			return nil, fmt.Errorf("%w: %w", ErrUserTokenRejected, jwt.ErrTokenInvalidClaims)
310		}
311	
312		userID, ok := claims["id"].(float64)
313		if !ok {
314			return nil, fmt.Errorf("%w: %w", ErrUserTokenRejected, jwt.ErrTokenInvalidClaims)
315		}
316	
317		sid, _ := claims["sid"].(string)
318		exp, err := claims.GetExpirationTime()
319		if err != nil || exp == nil || sid == "" {
320			return nil, fmt.Errorf("%w: %w", ErrUserTokenRejected, jwt.ErrTokenInvalidClaims)
321		}
322	
323		return &UserTokenClaims{
324			UserID:    int64(userID),
325			SessionID: sid,
326			ExpiresAt: exp.Time,
327		}, nil
328	}
329	
330	func CheckUserTokenSession(claims *UserTokenClaims) error {
331		s := db.NewSession()
332		defer s.Close()
333	
334		session, err := models.GetSessionByID(s, claims.SessionID)
335		if err == nil && session.UserID != claims.UserID {
336			err = &models.ErrSessionNotFound{}
337		}
338		if models.IsErrSessionNotFound(err) {
339			return fmt.Errorf("%w: %w", ErrUserTokenRejected, err)
340		}
341		if err != nil {
342			return err
343		}
344	
345		_, err = user.GetUserByID(s, claims.UserID)
346		if user.IsErrUserDoesNotExist(err) || user.IsErrUserStatusError(err) {
347			return fmt.Errorf("%w: %w", ErrUserTokenRejected, err)
348		}
349		return err
350	}
351	
352	func CreateUserWithRandomUsername(s *xorm.Session, uu *user.User) (u *user.User, err error) {
353		// Check if we actually have a preferred username and generate a random one right away if we don't
354		for {
355			if uu.Username == "" {
356				uu.Username = petname.Generate(3, "-")
357			}
358	
359			u, err = user.CreateUser(s, uu)
360			if err == nil {
361				break
362			}
363	
364			if !user.IsErrUsernameExists(err) {
365				return nil, err
366			}
367	
368			// If their preferred username is already taken, generate a new one
369			uu.Username = petname.Generate(3, "-")
370		}
371	
372		// And create their project
373		err = models.CreateNewProjectForUser(s, u)
374		return
375	}
376	
377	// RefreshResult holds the result of a successful session refresh.
378	type RefreshResult struct {
379		AccessToken     string
380		NewRefreshToken string
381		ExpiresIn       int64
382		IsLongSession   bool
383		SessionID       string
384	}
385	
386	// RefreshSession looks up a session by its raw refresh token, validates it,
387	// rotates the refresh token, fetches the user, and generates a new JWT.
388	// It handles its own DB session (open/commit/rollback).
389	//
390	// On user status errors (disabled/locked), the session is deleted before
391	// returning the error so the caller can handle cleanup (e.g. clearing cookies).
392	func RefreshSession(rawRefreshToken string) (*RefreshResult, error) {
393		s := db.NewSession()
394		defer s.Close()
395	
396		session, err := models.GetSessionByRefreshToken(s, rawRefreshToken)
397		if err != nil {
398			_ = s.Rollback()
399			if models.IsErrSessionNotFound(err) {
400				return nil, &models.ErrInvalidRefreshToken{}
401			}
402			return nil, err
403		}
404	
405		maxAge := time.Duration(config.ServiceJWTTTL.GetInt64()) * time.Second
406		if session.IsLongSession {
407			maxAge = time.Duration(config.ServiceJWTTTLLong.GetInt64()) * time.Second
408		}
409		if time.Since(session.LastActive) > maxAge {
410			if _, err := s.Where("id = ?", session.ID).Delete(&models.Session{}); err != nil {
411				_ = s.Rollback()
412				return nil, err
413			}
414			if err := s.Commit(); err != nil {
415				return nil, err
416			}
417			return nil, &models.ErrSessionExpired{}
418		}
419	
420		if err := models.UpdateSessionLastActive(s, session.ID); err != nil {
421			_ = s.Rollback()
422			return nil, err
423		}
424	
425		newRawToken, err := models.RotateRefreshToken(s, session)
426		if err != nil {
427			_ = s.Rollback()
428			if models.IsErrSessionNotFound(err) {
429				return nil, &models.ErrRefreshTokenAlreadyUsed{}
430			}
431			return nil, err
432		}
433	
434		u, err := user.GetUserByID(s, session.UserID)
435		if err != nil {
436			if user.IsErrUserStatusError(err) {
437				if _, delErr := s.Where("id = ?", session.ID).Delete(&models.Session{}); delErr != nil {
438					_ = s.Rollback()
439					return nil, delErr
440				}
441				if commitErr := s.Commit(); commitErr != nil {
442					return nil, commitErr
443				}
444				return nil, err
445			}
446			_ = s.Rollback()
447			return nil, err
448		}
449	
450		accessToken, err := NewUserJWTAuthtoken(u, session.ID)
451		if err != nil {
452			_ = s.Rollback()
453			return nil, err
454		}
455	
456		if err := s.Commit(); err != nil {
457			return nil, err
458		}
459	
460		return &RefreshResult{
461			AccessToken:     accessToken,
462			NewRefreshToken: newRawToken,
463			ExpiresIn:       config.ServiceJWTTTLShort.GetInt64(),
464			IsLongSession:   session.IsLongSession,
465			SessionID:       session.ID,
466		}, nil
467	}
468	
469	// IsUnusableRefreshToken reports whether the caller should clear the refresh
470	// cookie. Transient errors must not clear it, nor a token rotated away by a
471	// concurrent refresh: that would delete the cookie the winning refresh just set.
472	func IsUnusableRefreshToken(err error) bool {
473		var expired *models.ErrSessionExpired
474		return errors.As(err, &expired) || user.IsErrUserStatusError(err)
475	}
476	
477	// SessionIDFromContext reads the session id (the `sid` claim) off the user JWT
478	// in the echo context. It returns "" when there is no user JWT or no sid claim
479	// (API tokens and link shares carry no session), which callers treat as a no-op.
480	func SessionIDFromContext(c *echo.Context) string {
481		raw := c.Get("user")
482		if raw == nil {
483			return ""
484		}
485		jwtinf, ok := raw.(*jwt.Token)
486		if !ok {
487			return ""
488		}
489		claims, ok := jwtinf.Claims.(jwt.MapClaims)
490		if !ok {
491			return ""
492		}
493		sid, _ := claims["sid"].(string)
494		return sid
495	}
496	
497	// SessionUserIDFromContext returns the user id of a user JWT, or 0 for link
498	// shares, API tokens and unauthenticated requests.
499	func SessionUserIDFromContext(c *echo.Context) int64 {
500		jwtinf, ok := c.Get("user").(*jwt.Token)
501		if !ok {
502			return 0
503		}
504		claims, ok := jwtinf.Claims.(jwt.MapClaims)
505		if !ok {
506			return 0
507		}
508		if typ, ok := claims["type"].(float64); !ok || int(typ) != AuthTypeUser {
509			return 0
510		}
511		id, _ := claims["id"].(float64)
512		return int64(id)
513	}
514	
515	// GetAuthFromContext retrieves the authenticated web.Auth from a plain
516	// context.Context, bridging Huma handlers to Vikunja's echo JWT flow. The
517	// humabridge group middleware stashes the *echo.Context under EchoContextKey
518	// first.
