515	// GetAuthFromContext retrieves the authenticated web.Auth from a plain
516	// context.Context, bridging Huma handlers to Vikunja's echo JWT flow. The
517	// humabridge group middleware stashes the *echo.Context under EchoContextKey
518	// first.
519	func GetAuthFromContext(ctx context.Context) (web.Auth, error) {
520		ec := humabridge.EchoContextFrom(ctx)
521		if ec == nil {
522			return nil, fmt.Errorf("no echo.Context on request context; are you calling GetAuthFromContext from a Huma handler mounted via humabridge?")
523		}
524		return GetAuthFromClaims(ec)
525	}

