    17	// RegisterRefreshTokenRoutes wires the refresh-token endpoint. It authenticates
    18	// via the HttpOnly refresh cookie rather than a JWT, so it is a public operation.
    19	func RegisterRefreshTokenRoutes(api huma.API) {
    20		Register(api, huma.Operation{
    21			OperationID:   "auth-refresh-token",
    22			Summary:       "Refresh user token",
    23			Description:   "Exchanges the refresh-token cookie for a new short-lived JWT. The refresh token is rotated on every call, so the previous one stops working. A new HttpOnly refresh cookie is set on the response.",
    24			Method:        http.MethodPost,
    25			Path:          "/user/token/refresh",
    26			DefaultStatus: http.StatusOK,
    27			Tags:          []string{"auth"},
    28			Security:      publicSecurity,
    29		}, authRefreshToken)
    30	}
    31	
    32	func authRefreshToken(ctx context.Context, _ *struct{}) (*authTokenBody, error) {
    33		ec := humabridge.EchoContextFrom(ctx)
    34		if ec == nil {
    35			return nil, translateDomainError(&models.ErrNoRefreshToken{})
    36		}
    37	
    38		cookie, err := ec.Cookie(auth.RefreshTokenCookieName)
    39		if err != nil || cookie.Value == "" {
    40			return nil, translateDomainError(&models.ErrNoRefreshToken{})
    41		}
    42	
    43		result, err := auth.RefreshSession(cookie.Value)
    44		if err != nil {
    45			if auth.IsUnusableRefreshToken(err) {
    46				auth.ClearRefreshTokenCookie(ec)
    47			}
    48			return nil, translateDomainError(err)
    49		}
    50	
    51		cookieMaxAge := int(config.ServiceJWTTTL.GetInt64())
    52		if result.IsLongSession {
    53			cookieMaxAge = int(config.ServiceJWTTTLLong.GetInt64())
    54		}
    55		auth.SetRefreshTokenCookie(ec, result.NewRefreshToken, cookieMaxAge)
    56	
    57		out := &authTokenBody{CacheControl: "no-store"}
    58		out.Body.Token = result.AccessToken
    59		return out, nil
    60	}
