    21	// RegisterUserDeletionCron registers the cron job that actually removes users who are scheduled to delete.
    22	func RegisterUserDeletionCron() {
    23		err := cron.Schedule("0 * * * *", deleteUsers)
    24		if err != nil {
    25			log.Errorf("Could not register deletion cron: %s", err.Error())
    26		}
    27	}
