    29	func deleteUsers() {
    30		s := db.NewSession()
    31		users := []*user.User{}
    32		err := s.Where(builder.Lt{"deletion_scheduled_at": time.Now()}).
    33			Find(&users)
    34		s.Close()
    35		if err != nil {
    36			log.Errorf("Could not get users scheduled for deletion: %s", err)
    37			return
    38		}
    39	
    40		if len(users) == 0 {
    41			return
    42		}
    43	
    44		log.Debugf("Found %d users scheduled for deletion", len(users))
    45	
    46		now := time.Now()
    47	
    48		for _, u := range users {
    49			if !u.DeletionScheduledAt.Before(now) {
    50				log.Debugf("User %d is not yet scheduled for deletion. Scheduled at %s, now is %s", u.ID, u.DeletionScheduledAt, now)
    51				continue
    52			}
    53	
    54			func() {
    55				us := db.NewSession()
    56				defer us.Close()
    57				defer events.CleanupPending(us)
    58	
    59				err = DeleteUser(us, u)
    60				if err != nil {
    61					_ = us.Rollback()
    62					log.Errorf("Could not delete u %d: %s", u.ID, err)
    63					return
    64				}
    65	
    66				log.Debugf("Deleted user %d", u.ID)
    67	
    68				err = us.Commit()
    69				if err != nil {
    70					log.Errorf("Could not commit transaction: %s", err)
    71					return
    72				}
    73				events.DispatchPending(context.Background(), us)
    74			}()
    75		}
    76	}
