   116	// DeleteUser completely removes a user and all their associated projects and tasks.
   117	// This action is irrevocable.
   118	// Public to allow deletion from the CLI.
   119	func DeleteUser(s *xorm.Session, u *user.User) (err error) {
   120		// Delete any bot users owned by this user first (cascades their data too).
   121		var ownedBots []*user.User
   122		if err = s.Where("bot_owner_id = ?", u.ID).Find(&ownedBots); err != nil {
   123			return err
   124		}
   125		for _, bot := range ownedBots {
   126			if err = DeleteUser(s, bot); err != nil {
   127				return err
   128			}
   129		}
   130	
   131		projectsToDelete, err := getProjectsToDelete(s, u)
   132		if err != nil {
   133			return err
   134		}
   135	
   136		for _, p := range projectsToDelete {
   137			if p.parentID() != 0 {
   138				// Child projects are deleted by p.Delete
   139				continue
   140			}
   141			err = p.Delete(s, u)
   142			// If the user is the owner of the default project it will be deleted, if they are not the owner
   143			// we can ignore the error as the project was shared in that case.
   144			if err != nil && !IsErrCannotDeleteDefaultProject(err) {
   145				return err
   146			}
   147		}
   148	
   149		// Delete all related entities
   150		relatedEntities := []struct {
   151			column string
   152			model  any
   153		}{
   154			{"user_id", &TaskAssginee{}},
   155			{"user_id", &Subscription{}},
   156			{"user_id", &TeamMember{}},
   157			{"owner_id", &SavedFilter{}},
   158			{"user_id", &Reaction{}},
   159			{"user_id", &Favorite{}},
   160			{"owner_id", &APIToken{}},
   161			{"created_by_id", &Webhook{}},
   162		}
   163	
   164		for _, entity := range relatedEntities {
   165			_, err = s.Where(entity.column+" = ?", u.ID).Delete(entity.model)
   166			if err != nil {
   167				return err
   168			}
   169		}
   170	
   171		err = DeleteAllUserSessions(s, u.ID)
