   173			return err
   174		}
   175	
   176		// Notify before deleting the user row, because ShouldNotify will try to
   177		// look up the user and fail if the row is already gone.
   178		err = notifications.Notify(u, &user.AccountDeletedNotification{
   179			User: u,
   180		}, s)
   181		if err != nil {
   182			return err
   183		}
   184	
   185		_, err = s.Where("id = ?", u.ID).Delete(&user.User{})
   186		return err
   187	}
