 45					log.Errorf("IPRateLimit - rateLimiter.Get - err: %v, %s on %s", err, rateLimitKey, c.Request().URL)
 46					return echo.NewHTTPError(http.StatusInternalServerError, "Internal server error").Wrap(err)
 47				}
 48	
 49				h := c.Response().Header()
 50				h.Set("X-RateLimit-Limit", strconv.FormatInt(limiterCtx.Limit, 10))
 51				h.Set("X-RateLimit-Remaining", strconv.FormatInt(limiterCtx.Remaining, 10))
 52				h.Set("X-RateLimit-Reset", strconv.FormatInt(limiterCtx.Reset, 10))
 53	
 54				if limiterCtx.Reached {
 55					log.Infof("Too Many Requests from %s on %s", rateLimitKey, c.Request().URL)
 56					return tooManyRequests(c, limiterCtx.Reset, time.Now())
 57				}
 58	
 59				// log.Printf("%s request continue", c.RealIP())
 60				return next(c)
 61			}
 62		}
 63	}
 64	
 65	func tooManyRequests(c *echo.Context, reset int64, now time.Time) error {
 66		// reset is a truncated unix second; +1 keeps a client from retrying just before the window ends.
 67		retryAfter := max(reset-now.Unix()+1, 1)
 68		c.Response().Header().Set(echo.HeaderRetryAfter, strconv.FormatInt(retryAfter, 10))
 69		return echo.NewHTTPError(http.StatusTooManyRequests, "Too Many Requests")
 70	}
 71	
 72	// createRateLimiter builds a limiter with its own counters. The prefix keeps
 73	// those counters apart in a shared backend: the redis store namespaces keys with
 74	// it, so without a distinct one every limiter would decrement the same budget.
 75	func createRateLimiter(prefix string, rate limiter.Rate) *limiter.Limiter {
 76		options := limiter.StoreOptions{
 77			Prefix:          limiter.DefaultPrefix + ":" + prefix,
 78			CleanUpInterval: limiter.DefaultCleanUpInterval,
 79			MaxRetry:        limiter.DefaultMaxRetry,
 80		}
 81	
 82		var store limiter.Store
 83		var err error
 84		switch config.RateLimitStore.GetString() {
 85		case "memory":
 86			store = memory.NewStoreWithOptions(options)
 87		case "redis":
 88			if !config.RedisEnabled.GetBool() {
 89				log.Fatal("Redis is configured for rate limiting, but not enabled!")
 90			}
 91			store, err = redis.NewStoreWithOptions(red.GetRedis(), options)
 92			if err != nil {
 93				log.Fatalf("Error while creating rate limit redis store: %s", err)
 94			}
 95		default:
 96			log.Fatalf("Unknown Rate limit store \"%s\"", config.RateLimitStore.GetString())
 97		}
 98		return limiter.New(store, rate)
 99	}
100	
101	// perMinuteIPRateLimit ignores RateLimitEnabled on purpose: pre-auth routes need
102	// a floor even with the global limiter off, which is the default.
103	func perMinuteIPRateLimit(prefix string, limit int64) echo.MiddlewareFunc {
104		rate := limiter.Rate{
105			Period: 60 * time.Second,
106			Limit:  limit,
107		}
108		return RateLimit(createRateLimiter(prefix, rate), "ip")
109	}
110	
111	func unauthRateLimit() echo.MiddlewareFunc {
112		return perMinuteIPRateLimit("noauth", config.RateLimitNoAuthRoutesLimit.GetInt64())
113	}
114	
115	// Renewal is routine traffic - sharing the credential-guessing floor let it starve /login.
116	func tokenRefreshRateLimit() echo.MiddlewareFunc {
117		return perMinuteIPRateLimit("tokenrefresh", config.RateLimitTokenRefreshLimit.GetInt64())
118	}
119	
120	// Limit failed bcrypt checks without throttling successful CalDAV syncs (GHSA-m469-88xx-8rx2).
121	func basicAuthRateLimit() echo.MiddlewareFunc {
122		rate := limiter.Rate{
123			Period: 60 * time.Second,
124			Limit:  config.RateLimitBasicAuthLimit.GetInt64(),
125		}
126		return basicAuthRateLimitWithLimiter(createRateLimiter("basicauth", rate))
127	}
128	
129	func basicAuthRateLimitWithLimiter(rateLimiter *limiter.Limiter) echo.MiddlewareFunc {
130		return basicAuthRateLimitWithClock(rateLimiter, time.Now)
131	}
132	
133	func basicAuthRateLimitWithClock(rateLimiter *limiter.Limiter, now func() time.Time) echo.MiddlewareFunc {
134		return func(next echo.HandlerFunc) echo.HandlerFunc {
135			return func(c *echo.Context) (err error) {
136				// A request without credentials is the normal 401 challenge, not a guess.
137				if _, _, ok := c.Request().BasicAuth(); !ok {
138					return next(c)
139				}
140	
141				requestTime := now()
142				period := rateLimiter.Rate.Period
143				bucket := requestTime.UnixNano() / period.Nanoseconds()
144				key := basicAuthRateLimitKey(c.RealIP(), bucket)
145				// Reserve before authentication so concurrent guesses cannot bypass the limit.
146				limiterCtx, err := rateLimiter.Increment(c.Request().Context(), key, 1)
147				if err != nil {
148					log.Errorf("basicAuthRateLimit - rateLimiter.Increment - err: %v, %s on %s", err, key, c.Request().URL)
149					return echo.NewHTTPError(http.StatusInternalServerError, "Internal server error").Wrap(err)
150				}
151				if limiterCtx.Reached {
152					if ierr := refundBasicAuthReservation(rateLimiter, key, limiterCtx.Reset, now()); ierr != nil {
153						log.Errorf("basicAuthRateLimit - rateLimiter.Increment refund - err: %v", ierr)
154						return echo.NewHTTPError(http.StatusInternalServerError, "Internal server error").Wrap(ierr)
155					}
156					log.Infof("Too many failed basic auth attempts from %s on %s", key, c.Request().URL)
157					// Reset is a period past the first hit, but the key's bucket ends at the aligned boundary.
158					bucketEnd := (requestTime.UnixNano()/rateLimiter.Rate.Period.Nanoseconds() + 1) * rateLimiter.Rate.Period.Nanoseconds()
159					return tooManyRequests(c, bucketEnd/int64(time.Second), now())
160				}
161	
162				err = next(c)
163	
164				// A 401 may be returned or already written by BasicAuth middleware.
165				failed := echo.StatusCode(err) == http.StatusUnauthorized
166				if !failed {
167					if res, ok := c.Response().(*echo.Response); ok && res.Committed && res.Status == http.StatusUnauthorized {
168						failed = true
169					}
170				}
171				if !failed {
172					if ierr := refundBasicAuthReservation(rateLimiter, key, limiterCtx.Reset, now()); ierr != nil {
173						log.Errorf("basicAuthRateLimit - rateLimiter.Increment refund - err: %v", ierr)
174						return echo.NewHTTPError(http.StatusInternalServerError, "Internal server error").Wrap(ierr)
175					}
176				}
177	
178				return err
179			}
180		}
181	}
182	
183	func refundBasicAuthReservation(rateLimiter *limiter.Limiter, key string, reset int64, now time.Time) error {
184		if now.Unix() > reset {
185			return nil
186		}
187	
188		ctx, cancel := context.WithTimeout(context.Background(), time.Second)
189		defer cancel()
190	
191		_, err := rateLimiter.Increment(ctx, key, -1)
192		return err
193	}
194	
195	func basicAuthRateLimitKey(ip string, bucket int64) string {
196		// A late refund must never decrement a newer window.
197		return ip + ":" + strconv.FormatInt(bucket, 10)
198	}
199	
200	func setupRateLimit(a *echo.Group, rateLimitKind string) {
201		if config.RateLimitEnabled.GetBool() {
202			rate := limiter.Rate{
203				Period: config.RateLimitPeriod.GetDuration() * time.Second,
204				Limit:  config.RateLimitLimit.GetInt64(),
205			}
206			rateLimiter := createRateLimiter("global", rate)
207			log.Debugf("Rate limit configured with %s and %v requests per %v", config.RateLimitStore.GetString(), rate.Limit, rate.Period)
208			a.Use(RateLimit(rateLimiter, rateLimitKind))
209		}
210	}
