 19	// ErrCodeInvalidToken is the error code returned when the JWT is missing,
 20	// malformed, or expired. The frontend uses this to distinguish "token expired,
 21	// try refreshing" from other 401s (disabled account, wrong API token, etc.).
 22	const ErrCodeInvalidToken = 11
 23	
 24	func SetupTokenMiddleware() echo.MiddlewareFunc {
 25		return echojwt.WithConfig(echojwt.Config{
 26			SigningKey: []byte(config.ServiceSecret.GetString()),
 27			Skipper: func(c *echo.Context) bool {
 28				// Public routes (docs, spec, info, etc.) never need JWT even
 29				// when their parent group has the middleware applied.
 30				if unauthenticatedAPIPaths[c.Path()] {
 31					return true
 32				}
 33	
 34				authHeader, ok := models.APITokenAuthorization(c.Request().Header)
 35				if !ok {
 36					return false // let the jwt middleware handle other or invalid headers
 37				}
 38	
 39				return checkAPITokenAndPutItInContext(authHeader, c, shouldSkipRouteCheck(c)) == nil
 40			},
 41			ErrorHandler: func(c *echo.Context, err error) error {
 42				if err != nil {
 43					return c.JSON(http.StatusUnauthorized, web.HTTPError{
 44						HTTPCode: http.StatusUnauthorized,
 45						Code:     ErrCodeInvalidToken,
 46						Message:  "missing, malformed, expired or otherwise invalid token provided",
 47					})
 48				}
 49	
 50				return nil
 51			},
 52		})
 53	}
 54	
 55	// An autopatch leg inherits the client PATCH's authorisation only as long as it
 56	// resolves to the very route that PATCH was authorised against.
 57	func shouldSkipRouteCheck(c *echo.Context) bool {
 58		if c.Path() == "/api/v1/token/test" || c.Path() == "/api/v2/token/test" {
 59			return true
 60		}
 61	
 62		// Routes under the MCP prefix reject API tokens themselves; loopback routes still get checked here.
 63		if c.Path() == mcp.RoutePrefix || strings.HasPrefix(c.Path(), mcp.RoutePrefix+"/") {
 64			return true
 65		}
 66	
 67		// Autopatch re-dispatches a bare GET on the authorised route; a query string
 68		// or any other method means the client smuggled it in through the path.
 69		if c.Request().Method != http.MethodGet || c.Request().URL.RawQuery != "" {
 70			return false
 71		}
 72	
 73		route, ok := humabridge.InternalDispatchRoute(c.Request().Context())
 74		return ok && route != "" && route == c.Path()
 75	}
 76	
 77	func checkAPITokenAndPutItInContext(tokenHeaderValue string, c *echo.Context, skipRouteCheck bool) error {
 78		token, u, err := auth.ValidateAPITokenString(strings.TrimPrefix(tokenHeaderValue, "Bearer "))
 79		if err != nil {
 80			log.Debugf("[auth] API token validation failed: %v", err)
 81			return echo.NewHTTPError(http.StatusUnauthorized, "Unauthorized")
 82		}
 83	
 84		if !skipRouteCheck && !models.CanDoAPIRoute(c, token) {
 85			log.Debugf("[auth] Tried authenticating with token %d but it does not have permission to do this route", token.ID)
 86			return echo.NewHTTPError(http.StatusUnauthorized, "Unauthorized")
 87		}
 88	
 89		c.Set("api_token", token)
 90		c.Set("api_user", u)
 91	
 92		// Autopatch's internal legs are not requests the client made.
 93		if _, internalDispatch := humabridge.InternalDispatchRoute(c.Request().Context()); !internalDispatch {
 94			if err := models.RecordAPITokenUse(c.Request().Context(), token); err != nil {
 95				log.Errorf("Could not dispatch api token used event: %s", err)
 96			}
 97		}
 98	
 99		return nil
100	}

