// CollectRoutesForAPITokenUsage records a route for token authorisation.
// v1 and v2 share group/permission keys derived from the prefix-stripped
// path; v2 entries land in apiTokenRoutesV2 so the v1-only frontend UI is
// unchanged while CanDoAPIRoute consults both tables.
func CollectRoutesForAPITokenUsage(route echo.RouteInfo, requiresJWT bool) {

	if route.Method == "echo_route_not_found" {
		return
	}

	if !requiresJWT {
		return
	}

	routeGroupName, routeParts := getRouteGroupName(route.Path)

	if routeGroupName == "token_test" ||
		routeGroupName == "subscriptions" ||
		routeGroupName == "tokens" ||
		routeGroupName == "*" ||
		routeGroupName == "oauth_authorize" ||
		routeGroupName == "mcp" ||
		strings.HasPrefix(routeGroupName, "mcp_") ||
		strings.HasPrefix(routeGroupName, "user_") {
		return
	}

	target := apiTokenRoutes
	if isV2Path(route.Path) {
		target = apiTokenRoutesV2
		// AutoPatch's synthesised PATCH and the original PUT both derive the
		// "update" permission and would clobber each other on the map. Store
		// only PUT; CanDoAPIRoute accepts PATCH as its alias on the same path.
		if route.Method == http.MethodPatch {
			return
		}
	}

	// Check if this is a standard CRUD route using path-based heuristics
	// In Echo v5, we can no longer rely on route.Name containing "(*WebHandler)"
	isCRUD := isStandardCRUDRoute(routeGroupName, routeParts, route.Method)

	// Special case for task attachments which use custom handlers
	isAttachmentRoute := routeGroupName == "tasks_attachments"

	if !isCRUD && !isAttachmentRoute {
		routeDetail := &RouteDetail{
			Path:   route.Path,
			Method: route.Method,
		}
		// We're trying to add routes to the routes of a matching "parent" - for
		// example, projects_background should show up under "projects".
		// To do this, we check if the route is a sub route of some other route
		// and if that's the case, add it to its parent instead.
		// Otherwise, we add it to the "other" key.
		if len(routeParts) == 1 {
			if routeGroupName == "notifications" && route.Method == http.MethodPost {
				ensureAPITokenRoutesGroup(target, "notifications")

				target["notifications"]["mark_all_as_read"] = routeDetail
				return
			}

			ensureAPITokenRoutesGroup(target, "other")

			_, exists := target["other"][routeGroupName]
			if exists {
				routeGroupName += "_" + strings.ToLower(route.Method)
			}
			target["other"][routeGroupName] = routeDetail
			return
		}

		subkey := strings.Join(routeParts[1:], "_")

		if _, has := target[routeParts[0]]; !has {
			target[routeParts[0]] = make(APITokenRoute)
		}

		if _, has := target[routeParts[0]][subkey]; has {
			subkey += "_" + strings.ToLower(route.Method)
		}

		target[routeParts[0]][subkey] = routeDetail

		return
	}

	if !has {
		return nil, user.ErrUserDoesNotExist{UserID: id}
	}
	return target, nil
}

// SetUserAdminFlag sets a user's instance-admin flag. Demoting the last
// reachable admin is refused via GuardLastAdmin. It does not commit; the caller
// owns the transaction.
func SetUserAdminFlag(s *xorm.Session, doer *user.User, id int64, isAdmin bool) (*user.User, error) {
	target, err := loadAdminTargetUser(s, id)
	if err != nil {
		return nil, err
	}

	if !isAdmin {
		if err := user.GuardLastAdmin(s, target); err != nil {
			return nil, err
		}
	}

	target.IsAdmin = isAdmin
	if _, err := s.ID(target.ID).Cols("is_admin").Update(target); err != nil {
		return nil, err
	}

	if isAdmin {
		events.DispatchOnCommit(s, &AdminUserAdminGrantedEvent{User: target, Doer: doer})
	} else {
		events.DispatchOnCommit(s, &AdminUserAdminRevokedEvent{User: target, Doer: doer})
	}
	return target, nil
}

// SetUserStatusAsAdmin sets a user's account status. Moving the last reachable
// admin out of Active is refused via GuardLastAdmin (any non-Active status
// blocks login, so it is equivalent to demotion). It does not commit; the caller
// owns the transaction.
func SetUserStatusAsAdmin(s *xorm.Session, doer *user.User, id int64, status user.Status) (*user.User, error) {
	target, err := loadAdminTargetUser(s, id)
	if err != nil {
		return nil, err
	}

	if target.IsAdmin && status != user.StatusActive {
		if err := user.GuardLastAdmin(s, target); err != nil {
			return nil, err
		}
	}

	if err := ChangeUserStatus(s, doer, target, status); err != nil {
		return nil, err
	}
	return target, nil
}

// ChangeUserStatus skips the last-admin guard.
func ChangeUserStatus(s *xorm.Session, doer *user.User, target *user.User, status user.Status) error {
	oldStatus := target.Status
	if err := user.SetUserStatus(s, target, status); err != nil {
		return err
	}
	// Reflect the change on the caller's struct; GetUserByID refuses disabled accounts.
	target.Status = status

	if status != user.StatusActive {
		if err := DeleteAllUserSessions(s, target.ID); err != nil {
			return err
		}
	}

	events.DispatchOnCommit(s, &AdminUserStatusChangedEvent{
		User:      target,
		Doer:      doer,
		OldStatus: oldStatus,
		NewStatus: status,
	})
	return nil
}

// SetUserPasswordAsAdmin sets a new password for a local account and
// invalidates all of the user's sessions, mirroring the self-service flows.
// Non-local accounts are refused explicitly: unlike self-service, no
// old-password verification runs here to catch them. It does not commit; the
// caller owns the transaction.
func SetUserPasswordAsAdmin(s *xorm.Session, doer *user.User, id int64, newPassword string) (*user.User, error) {
	target, err := loadAdminTargetUser(s, id)
	if err != nil {
		return nil, err
	}

	if !target.IsLocalUser() {
		return nil, &user.ErrAccountIsNotLocal{UserID: target.ID}
	}

	if err := setUserPasswordAndInvalidateSessions(s, target, newPassword); err != nil {
		return nil, err
	}

	if config.MailerEnabled.GetBool() {
		if err := notifications.Notify(target, &user.PasswordChangedNotification{User: target}, s); err != nil {
			return nil, err
		}
	}

	events.DispatchOnCommit(s, &AdminUserPasswordSetEvent{User: target, Doer: doer})
	return target, nil
}

// RequestPasswordResetAsAdmin triggers the self-service password-reset email
// for a local account. The caller must ensure the mailer is enabled —
// RequestUserPasswordResetToken silently skips the email otherwise. It does
// not commit; the caller owns the transaction.
func RequestPasswordResetAsAdmin(s *xorm.Session, doer *user.User, id int64) error {
	target, err := loadAdminTargetUser(s, id)
	if err != nil {
		return err
	}

	if !target.IsLocalUser() {
		return &user.ErrAccountIsNotLocal{UserID: target.ID}
	}

	// notifications.Notify silently drops emails for accounts ShouldNotify
	// refuses (bots, disabled or locked accounts); surface that instead of
	// reporting a sent email.
	if target.IsBot() {
		return ErrInvalidData{Message: "bot accounts cannot receive password-reset emails"}
	}
	if _, err := user.GetUserByID(s, id); err != nil {
		return err
	}

	if err := user.RequestUserPasswordResetToken(s, target); err != nil {
		return err
	}

	events.DispatchOnCommit(s, &AdminUserPasswordResetSentEvent{User: target, Doer: doer})
	return nil
}

// DeleteUserAsAdmin removes a user. mode "now" deletes immediately; any other
// value triggers the email-confirmation self-deletion flow. Deleting the last
// reachable admin is refused via GuardLastAdmin. It does not commit; the caller
// owns the transaction.
func DeleteUserAsAdmin(s *xorm.Session, doer *user.User, id int64, mode string) error {
	target, err := loadAdminTargetUser(s, id)
	if err != nil {
		return err
	}

	if err := user.GuardLastAdmin(s, target); err != nil {
		return err
	}

	if mode == "now" {
		err = DeleteUser(s, target)
	} else {
		err = user.RequestDeletion(s, target)
	}
	if err != nil {
		return err
	}

	events.DispatchOnCommit(s, &AdminUserDeletedEvent{User: target, Doer: doer, Mode: mode})
	return nil
}

