const behindTheBackTitle = "behind the back"

// Writes through a second session; the caller must have committed, or the shared-cache lock blocks this.
func updateTitleBehindTheBack(t *testing.T, id int64, bean any) {
	s2 := db.NewSession()
	defer s2.Close()

	_, err := s2.ID(id).Cols("title").Update(bean)
	require.NoError(t, err)
	require.NoError(t, s2.Commit())
}

func insertTestProject(t testing.TB, s *xorm.Session, project *Project) {
	t.Helper()
	_, err := s.Insert(project)
	require.NoError(t, err)
	require.NoError(t, insertProjectAncestors(s, project.ID, project.parentID()))
}

func setupTime() {
	var err error
	loc, err := time.LoadLocation("GMT")
	if err != nil {
		fmt.Printf("Error setting up time: %s", err)
		os.Exit(1)
	}
	testCreatedTime, err = time.ParseInLocation(time.RFC3339Nano, "2018-12-01T15:13:12.0+00:00", loc)
	if err != nil {
		fmt.Printf("Error setting up time: %s", err)
		os.Exit(1)
	}
	testCreatedTime = testCreatedTime.In(loc)
	testUpdatedTime, err = time.ParseInLocation(time.RFC3339Nano, "2018-12-02T15:13:12.0+00:00", loc)
	if err != nil {
		fmt.Printf("Error setting up time: %s", err)
		os.Exit(1)
	}
	testUpdatedTime = testUpdatedTime.In(loc)
}

func TestMain(m *testing.M) {

	setupTime()

	// Initialize logger for tests
	log.InitLogger()

	// Set default config
	config.InitDefaultConfig()

	i18n.Init()

	// Some tests use the file engine, so we'll need to initialize that
	files.InitTests()
