package models

// TEMPORARY audit probes - not part of the codebase, removed after the run.
// They build small scenarios through the real model methods, run the real
// account deletion flow (RequestDeletion -> ConfirmDeletion -> deletion cron
// body -> DeleteUser) and log what is left. They assert nothing about outcomes.

import (
	"bytes"
	"fmt"
	"regexp"
	"sort"
	"strings"
	"testing"
	"time"

	"code.vikunja.io/api/pkg/db"
	"code.vikunja.io/api/pkg/files"
	"code.vikunja.io/api/pkg/notifications"
	"code.vikunja.io/api/pkg/user"
	"code.vikunja.io/api/pkg/utils"

	"github.com/stretchr/testify/require"
	"xorm.io/xorm"
)

func probeSetup(t *testing.T) {
	db.LoadAndAssertFixtures(t)
	files.InitTestFileFixtures(t)
	notifications.Fake()
	t.Cleanup(notifications.Unfake)
}

func probeTx(t *testing.T, fn func(s *xorm.Session)) {
	t.Helper()
	s := db.NewSession()
	defer s.Close()
	fn(s)
	require.NoError(t, s.Commit())
}

func probeUser(t *testing.T, name string) *user.User {
	t.Helper()
	var u *user.User
	probeTx(t, func(s *xorm.Session) {
		var err error
		u, err = RegisterUser(s, &user.User{Username: name, Email: name + "@probe.test", Password: "12345678"})
		require.NoError(t, err)
	})
	probeTx(t, func(s *xorm.Session) {
		full := &user.User{}
		_, err := s.ID(u.ID).Get(full)
		require.NoError(t, err)
		u = full
	})
	return u
}

func probeProject(t *testing.T, owner *user.User, title string, parent int64) *Project {
	t.Helper()
	p := &Project{Title: title}
	if parent != 0 {
		p.ParentProjectID = &parent
	}
	probeTx(t, func(s *xorm.Session) { require.NoError(t, p.Create(s, owner)) })
	return p
}

func probeShare(t *testing.T, p *Project, by, with *user.User, perm Permission) {
	t.Helper()
	probeTx(t, func(s *xorm.Session) {
		require.NoError(t, (&ProjectUser{ProjectID: p.ID, Username: with.Username, Permission: perm}).Create(s, by))
	})
}

func probeTask(t *testing.T, p *Project, by *user.User, title string) *Task {
	t.Helper()
	task := &Task{Title: title, ProjectID: p.ID}
	probeTx(t, func(s *xorm.Session) { require.NoError(t, task.Create(s, by)) })
	return task
}

func probeAttachment(t *testing.T, task *Task, by *user.User, name string) *TaskAttachment {
	t.Helper()
	ta := &TaskAttachment{TaskID: task.ID}
	data := []byte("probe attachment " + name)
	probeTx(t, func(s *xorm.Session) {
		require.NoError(t, ta.NewAttachment(s, bytes.NewReader(data), name, uint64(len(data)), by))
	})
	return ta
}

// probeDeleteAccount runs the self-service flow. Two shortcuts: the clear-text
// confirm token only exists in the (faked) email, so one with a known value is
// planted next to the real one; and the three day wait is skipped by backdating.
func probeDeleteAccount(t *testing.T, u *user.User) {
	t.Helper()
	const clear = "probe-deletion-token"
	probeTx(t, func(s *xorm.Session) {
		full, err := user.GetUserByID(s, u.ID)
		require.NoError(t, err)
		require.NoError(t, user.RequestDeletion(s, full))
		_, err = s.Insert(&user.Token{UserID: u.ID, Kind: user.TokenAccountDeletion, Token: utils.Sha256Hex(clear)})
		require.NoError(t, err)
		require.NoError(t, user.ConfirmDeletion(s, full, clear))
	})
	probeTx(t, func(s *xorm.Session) {
		_, err := s.Where("id = ?", u.ID).Cols("deletion_scheduled_at").
			Update(&user.User{DeletionScheduledAt: time.Now().Add(-time.Hour)})
		require.NoError(t, err)
	})

	deleteUsers() // the hourly cron body

	s := db.NewSession()
	exists, err := s.Where("id = ?", u.ID).Exist(&user.User{})
	require.NoError(t, err)
	s.Close()
	if !exists {
		t.Logf("PROBE   deletion cron: user %q (id %d) deleted", u.Username, u.ID)
		return
	}
	// The cron only logs failures, so surface the error by calling DeleteUser directly.
	s2 := db.NewSession()
	defer s2.Close()
	full := &user.User{}
	_, _ = s2.ID(u.ID).Get(full)
	derr := DeleteUser(s2, full)
	_ = s2.Rollback()
	t.Logf("PROBE   deletion cron: user %q (id %d) STILL EXISTS after cron; DeleteUser error: %v", u.Username, u.ID, derr)
}

func probeName(s *xorm.Session, id int64) string {
	u := &user.User{}
	has, _ := s.ID(id).Get(u)
	if !has {
		return fmt.Sprintf("<no such user %d>", id)
	}
	return u.Username
}

var probePerm = map[Permission]string{PermissionRead: "read", PermissionWrite: "write", PermissionAdmin: "admin"}

func probeProjectState(t *testing.T, label string, id int64) {
	t.Helper()
	s := db.NewSession()
	defer s.Close()
	p := &Project{}
	has, err := s.ID(id).Get(p)
	require.NoError(t, err)
	if !has {
		t.Logf("PROBE   %s: project %d is GONE", label, id)
		return
	}
	shares := []*ProjectUser{}
	require.NoError(t, s.Where("project_id = ?", id).OrderBy("id").Find(&shares))
	var sh []string
	for _, pu := range shares {
		sh = append(sh, probeName(s, pu.UserID)+"="+probePerm[pu.Permission])
	}
	teams := []*TeamProject{}
	require.NoError(t, s.Where("project_id = ?", id).OrderBy("id").Find(&teams))
	var th []string
	for _, tp := range teams {
		th = append(th, fmt.Sprintf("team%d=%s", tp.TeamID, probePerm[tp.Permission]))
	}
	tasks, _ := s.Where("project_id = ?", id).Count(&Task{})
	t.Logf("PROBE   %s: project %d %q owner=%s user-shares=%v team-shares=%v tasks=%d", label, id, p.Title, probeName(s, p.OwnerID), sh, th, tasks)
}

func probeAccess(t *testing.T, label string, projectID int64, u *user.User) {
	t.Helper()
	s := db.NewSession()
	defer s.Close()
	canRead, _, rerr := (&Project{ID: projectID}).CanRead(s, u)
	canWrite, werr := (&Project{ID: projectID}).CanWrite(s, u)
	isAdmin, aerr := (&Project{ID: projectID}).IsAdmin(s, u)
	t.Logf("PROBE   %s: %s on project %d -> read=%v(%v) write=%v(%v) admin=%v(%v)", label, u.Username, projectID, canRead, rerr, canWrite, werr, isAdmin, aerr)
}

func probeRead(t *testing.T, label string, fn func(s *xorm.Session) (string, error)) {
	t.Helper()
	s := db.NewSession()
	defer s.Close()
	out, err := fn(s)
	t.Logf("PROBE   %s: %s err=%v", label, out, err)
}

func probeFile(t *testing.T, label string, id int64) {
	t.Helper()
	s := db.NewSession()
	defer s.Close()
	rowExists, err := s.Where("id = ?", id).Exist(&files.File{})
	require.NoError(t, err)
	_, statErr := files.FileStat(&files.File{ID: id})
	t.Logf("PROBE   %s: file %d db-row-exists=%v blob-exists=%v", label, id, rowExists, statErr == nil)
}

var probeRefCol = regexp.MustCompile(`(^|_)(user_id|owner_id|created_by_id|author_id|shared_by_id|doer_id|notifiable_id|subject_id|assignee_id|bot_owner_id|member_id)$`)

// probeLeftovers lists every table/column that still holds the deleted user's id.
func probeLeftovers(t *testing.T, label string, userID int64) {
	t.Helper()
	s := db.NewSession()
	defer s.Close()
	tables, err := s.QueryString("SELECT name FROM sqlite_master WHERE type='table'")
	require.NoError(t, err)
	var found []string
	for _, tb := range tables {
		cols, err := s.QueryString("PRAGMA table_info(`" + tb["name"] + "`)")
		require.NoError(t, err)
		for _, c := range cols {
			if !probeRefCol.MatchString(c["name"]) {
				continue
			}
			n, err := s.SQL("SELECT count(*) FROM `"+tb["name"]+"` WHERE `"+c["name"]+"` = ?", userID).Count()
			require.NoError(t, err)
			if n > 0 {
				found = append(found, fmt.Sprintf("%s.%s=%d", tb["name"], c["name"], n))
			}
		}
	}
	sort.Strings(found)
	t.Logf("PROBE   %s: rows still pointing at deleted user id %d: %s", label, userID, strings.Join(found, ", "))
}

func probeReadProjectAs(t *testing.T, label string, id int64, u *user.User) {
	t.Helper()
	probeRead(t, label+": Project.ReadOne as "+u.Username, func(s *xorm.Session) (string, error) {
		p := &Project{ID: id}
		err := p.ReadOne(s, u)
		owner := "<nil>"
		if p.Owner != nil {
			owner = fmt.Sprintf("%q(id %d)", p.Owner.Username, p.Owner.ID)
		}
		return "owner=" + owner, err
	})
	probeRead(t, label+": project list as "+u.Username, func(s *xorm.Session) (string, error) {
		res, _, _, err := (&Project{}).ReadAll(s, u, "", 1, 50)
		var titles []string
		if ps, ok := res.([]*Project); ok {
			for _, p := range ps {
				titles = append(titles, p.Title)
			}
		}
		return fmt.Sprintf("projects=%v", titles), err
	})
	probeRead(t, label+": task list as "+u.Username, func(s *xorm.Session) (string, error) {
		res, _, _, err := (&TaskCollection{ProjectID: id}).ReadAll(s, u, "", 1, 50)
		var out []string
		if ts, ok := res.([]*Task); ok {
			for _, tk := range ts {
				cb := "<nil>"
				if tk.CreatedBy != nil {
					cb = tk.CreatedBy.Username
				}
				out = append(out, tk.Title+"(by "+cb+")")
			}
		}
		return fmt.Sprintf("tasks=%v", out), err
	})
}

// ---------------------------------------------------------------------------
// A: projects that OTHER people own and shared with the user who deletes their account
// ---------------------------------------------------------------------------

func TestAuditProbeDelA_SharedIntoDeletedUser(t *testing.T) {
	for _, perm := range []Permission{PermissionRead, PermissionWrite, PermissionAdmin} {
		t.Run("A1 owner shares project with leaver only, "+probePerm[perm], func(t *testing.T) {
			probeSetup(t)
			owner, leaver := probeUser(t, "owner"), probeUser(t, "leaver")
			p := probeProject(t, owner, "owners project", 0)
			probeTask(t, p, owner, "owners task")
			probeShare(t, p, owner, leaver, perm)
			probeProjectState(t, "before", p.ID)
			probeAccess(t, "before", p.ID, owner)
			probeDeleteAccount(t, leaver)
			probeProjectState(t, "after ", p.ID)
			probeAccess(t, "after ", p.ID, owner)
			probeReadProjectAs(t, "after ", p.ID, owner)
			probeLeftovers(t, "after ", leaver.ID)
		})
	}

	t.Run("A2 shared read with bystander first, then leaver", func(t *testing.T) {
		probeSetup(t)
		owner, leaver, by := probeUser(t, "owner"), probeUser(t, "leaver"), probeUser(t, "bystander")
		p := probeProject(t, owner, "owners project", 0)
		probeTask(t, p, owner, "owners task")
		probeShare(t, p, owner, by, PermissionRead)
		probeShare(t, p, owner, leaver, PermissionRead)
		probeProjectState(t, "before", p.ID)
		probeDeleteAccount(t, leaver)
		probeProjectState(t, "after ", p.ID)
		probeAccess(t, "after ", p.ID, owner)
		probeAccess(t, "after ", p.ID, by)
		probeReadProjectAs(t, "after ", p.ID, owner)
	})

	t.Run("A3 owners default (inbox) project shared read with leaver", func(t *testing.T) {
		probeSetup(t)
		owner, leaver := probeUser(t, "owner"), probeUser(t, "leaver")
		inbox := &Project{ID: owner.DefaultProjectID}
		t.Logf("PROBE   owner default project id=%d", inbox.ID)
		probeShare(t, inbox, owner, leaver, PermissionRead)
		probeProjectState(t, "before", inbox.ID)
		probeDeleteAccount(t, leaver)
		probeProjectState(t, "after ", inbox.ID)
		probeAccess(t, "after ", inbox.ID, owner)
	})

	t.Run("A4 shared with leaver through a team (read)", func(t *testing.T) {
		probeSetup(t)
		owner, leaver, mate := probeUser(t, "owner"), probeUser(t, "leaver"), probeUser(t, "teammate")
		p := probeProject(t, owner, "owners project", 0)
		team := &Team{Name: "readers"}
		probeTx(t, func(s *xorm.Session) {
			require.NoError(t, team.Create(s, owner))
			require.NoError(t, (&TeamMember{TeamID: team.ID, Username: leaver.Username}).Create(s, owner))
			require.NoError(t, (&TeamMember{TeamID: team.ID, Username: mate.Username}).Create(s, owner))
			require.NoError(t, (&TeamProject{TeamID: team.ID, ProjectID: p.ID, Permission: PermissionRead}).Create(s, owner))
		})
		probeProjectState(t, "before", p.ID)
		probeAccess(t, "before", p.ID, mate)
		probeDeleteAccount(t, leaver)
		probeProjectState(t, "after ", p.ID)
		probeAccess(t, "after ", p.ID, mate)
		probeAccess(t, "after ", p.ID, owner)
	})

	t.Run("A5 leaver has inherited access only (parent shared read, child untouched)", func(t *testing.T) {
		probeSetup(t)
		owner, leaver := probeUser(t, "owner"), probeUser(t, "leaver")
		parent := probeProject(t, owner, "owners parent", 0)
		child := probeProject(t, owner, "owners child", parent.ID)
		probeTask(t, child, owner, "task in child")
		probeShare(t, parent, owner, leaver, PermissionRead)
		probeDeleteAccount(t, leaver)
		probeProjectState(t, "after ", parent.ID)
		probeProjectState(t, "after ", child.ID)
		probeAccess(t, "after ", parent.ID, owner)
		probeAccess(t, "after ", child.ID, owner)
	})
}

// ---------------------------------------------------------------------------
// B: projects the deleted user OWNS that other people use
// ---------------------------------------------------------------------------

func TestAuditProbeDelB_OwnedByDeletedUser(t *testing.T) {
	for _, perm := range []Permission{PermissionRead, PermissionWrite, PermissionAdmin} {
		t.Run("B1 leaver owns project shared with collaborator, "+probePerm[perm], func(t *testing.T) {
			probeSetup(t)
			leaver, collab := probeUser(t, "leaver"), probeUser(t, "collab")
			p := probeProject(t, leaver, "leavers project", 0)
			lt := probeTask(t, p, leaver, "leavers task")
			probeTask(t, p, collab, "collabs task")
