				return fmt.Sprintf("created_by=%v", tk.CreatedBy), err
			})
			probeRead(t, "after : comments on leavers task as collab", func(s *xorm.Session) (string, error) {
				res, n, _, err := (&TaskComment{TaskID: lt.ID}).ReadAll(s, collab, "", 1, 50)
				out := ""
				if cs, ok := res.([]*TaskComment); ok {
					for _, c := range cs {
						out += fmt.Sprintf("[%q author=%v]", c.Comment, c.Author)
					}
				}
				return fmt.Sprintf("count=%d %s", n, out), err
			})
			probeRead(t, "after : attachment list on leavers task as collab", func(s *xorm.Session) (string, error) {
				res, n, _, err := (&TaskAttachment{TaskID: lt.ID}).ReadAll(s, collab, "", 1, 50)
				out := ""
				if as, ok := res.([]*TaskAttachment); ok {
					for _, a := range as {
						out += fmt.Sprintf("[file=%d created_by=%v]", a.FileID, a.CreatedBy)
					}
				}
				return fmt.Sprintf("count=%d %s", n, out), err
			})
			probeFile(t, "after : leavers attachment", att.FileID)
			probeLeftovers(t, "after ", leaver.ID)
		})
	}

	t.Run("B2 leaver owns unshared project with an attachment", func(t *testing.T) {
		probeSetup(t)
		leaver := probeUser(t, "leaver")
		p := probeProject(t, leaver, "leavers private project", 0)
		lt := probeTask(t, p, leaver, "leavers task")
		att := probeAttachment(t, lt, leaver, "private.txt")
		probeDeleteAccount(t, leaver)
		probeProjectState(t, "after ", p.ID)
		probeProjectState(t, "after  (inbox)", leaver.DefaultProjectID)
		probeFile(t, "after : attachment in deleted project", att.FileID)
		probeLeftovers(t, "after ", leaver.ID)
	})

	t.Run("B3 leaver owns project shared only with a team (read)", func(t *testing.T) {
		probeSetup(t)
		leaver, mate := probeUser(t, "leaver"), probeUser(t, "teammate")
		p := probeProject(t, leaver, "leavers team project", 0)
		probeTask(t, p, leaver, "leavers task")
		team := &Team{Name: "the team"}
		probeTx(t, func(s *xorm.Session) {
			require.NoError(t, team.Create(s, mate))
			require.NoError(t, (&TeamProject{TeamID: team.ID, ProjectID: p.ID, Permission: PermissionRead}).Create(s, leaver))
		})
		probeProjectState(t, "before", p.ID)
		probeDeleteAccount(t, leaver)
		probeProjectState(t, "after ", p.ID)
		probeAccess(t, "after ", p.ID, mate)
		probeReadProjectAs(t, "after ", p.ID, mate)
	})

	t.Run("B4 leaver owns parent (no shares); someone else owns a child under it", func(t *testing.T) {
		probeSetup(t)
		leaver, other := probeUser(t, "leaver"), probeUser(t, "other")
		parent := probeProject(t, leaver, "leavers parent", 0)
		child := probeProject(t, other, "others child", parent.ID)
		ct := probeTask(t, child, other, "others task in child")
		att := probeAttachment(t, ct, other, "others-file.txt")
		probeProjectState(t, "before", parent.ID)
		probeProjectState(t, "before", child.ID)
		probeAccess(t, "before", child.ID, other)
		probeDeleteAccount(t, leaver)
		probeProjectState(t, "after ", parent.ID)
		probeProjectState(t, "after ", child.ID)
		probeFile(t, "after : others attachment in child", att.FileID)
	})

	t.Run("B5 leaver owns a child under someone elses parent (leaver has write on parent)", func(t *testing.T) {
		probeSetup(t)
		owner, leaver := probeUser(t, "owner"), probeUser(t, "leaver")
		parent := probeProject(t, owner, "owners parent", 0)
