		child := probeProject(t, leaver, "leavers child", parent.ID)
		probeTask(t, child, owner, "owners task in leavers child")
		probeDeleteAccount(t, leaver)
		probeProjectState(t, "after ", parent.ID)
		probeProjectState(t, "after ", child.ID)
		probeAccess(t, "after ", child.ID, owner)
		probeReadProjectAs(t, "after ", child.ID, owner)
	})
}

