	}
	ms := []*TeamMember{}
	require.NoError(t, s.Where("team_id = ?", id).OrderBy("id").Find(&ms))
	var out []string
	for _, m := range ms {
		role := "member"
		if m.Admin {
			role = "ADMIN"
		}
		out = append(out, probeName(s, m.UserID)+"="+role)
	}
