func probeTeamState(t *testing.T, label string, id int64) {
	t.Helper()
	s := db.NewSession()
	defer s.Close()
	team := &Team{}
	has, err := s.ID(id).Get(team)
	require.NoError(t, err)
	if !has {
		t.Logf("PROBE   %s: team %d is GONE", label, id)
		return
	}
	ms := []*TeamMember{}
	require.NoError(t, s.Where("team_id = ?", id).OrderBy("id").Find(&ms))
	var out []string
	for _, m := range ms {
		role := "member"
		if m.Admin {
			role = "ADMIN"
		}
		out = append(out, probeName(s, m.UserID)+"="+role)
	}
	tps, _ := s.Where("team_id = ?", id).Count(&TeamProject{})
	t.Logf("PROBE   %s: team %d %q created_by=%s members=%v attached-to-projects=%d", label, id, team.Name, probeName(s, team.CreatedByID), out, tps)
}

