// ---------------------------------------------------------------------------
// F: follow-ups
// ---------------------------------------------------------------------------

func TestAuditProbeDelF_FollowUps(t *testing.T) {
	t.Run("F1 child created through permission-checked path, parent later unshared", func(t *testing.T) {
		probeSetup(t)
		leaver, other := probeUser(t, "leaver"), probeUser(t, "other")
		parent := probeProject(t, leaver, "leavers parent", 0)
		probeShare(t, parent, leaver, other, PermissionWrite)
		pid := parent.ID
		child := &Project{Title: "others child", ParentProjectID: &pid}
		probeTx(t, func(s *xorm.Session) {
			can, err := child.CanCreate(s, other)
			t.Logf("PROBE   other CanCreate child under leavers parent: %v err=%v", can, err)
			require.NoError(t, child.Create(s, other))
		})
		ct := probeTask(t, child, other, "others task in child")
		att := probeAttachment(t, ct, other, "others-file.txt")
		probeTx(t, func(s *xorm.Session) {
			require.NoError(t, (&ProjectUser{ProjectID: parent.ID, Username: other.Username}).Delete(s, leaver))
		})
		probeProjectState(t, "before", parent.ID)
		probeProjectState(t, "before", child.ID)
		probeAccess(t, "before", child.ID, other)
		probeDeleteAccount(t, leaver)
		probeProjectState(t, "after ", parent.ID)
		probeProjectState(t, "after ", child.ID)
		probeFile(t, "after : others attachment in child", att.FileID)
	})

	t.Run("F2 owner shares write with bystander and read with leaver", func(t *testing.T) {
		probeSetup(t)
		owner, leaver, by := probeUser(t, "owner"), probeUser(t, "leaver"), probeUser(t, "bystander")
		p := probeProject(t, owner, "owners project", 0)
		probeShare(t, p, owner, by, PermissionWrite)
		probeShare(t, p, owner, leaver, PermissionRead)
		probeProjectState(t, "before", p.ID)
		probeAccess(t, "before", p.ID, by)
		probeDeleteAccount(t, leaver)
		probeProjectState(t, "after ", p.ID)
		probeAccess(t, "after ", p.ID, by)
		probeAccess(t, "after ", p.ID, owner)
	})

	t.Run("F3 where the leftover buckets come from", func(t *testing.T) {
		probeSetup(t)
		leaver := probeUser(t, "leaver")
		probeDeleteAccount(t, leaver)
		s := db.NewSession()
		defer s.Close()
		rows, err := s.QueryString("SELECT b.id AS bucket, b.project_view_id AS view, v.project_id AS view_project, v.title AS view_title FROM buckets b LEFT JOIN project_views v ON v.id = b.project_view_id WHERE b.created_by_id = ?", leaver.ID)
		require.NoError(t, err)
		for _, r := range rows {
			t.Logf("PROBE   leftover bucket %s -> view %s (%q) of project_id %s", r["bucket"], r["view"], r["view_title"], r["view_project"])
		}
		n, _ := s.Where("owner_id = ?", leaver.ID).Count(&SavedFilter{})
		t.Logf("PROBE   saved_filters rows owned by deleted user: %d", n)
	})

	t.Run("F4 admin-less team: can the remaining member do anything with it", func(t *testing.T) {
		probeSetup(t)
		leaver, mate := probeUser(t, "leaver"), probeUser(t, "teammate")
		team := &Team{Name: "leavers team"}
		probeTx(t, func(s *xorm.Session) {
			require.NoError(t, team.Create(s, leaver))
			require.NoError(t, (&TeamMember{TeamID: team.ID, Username: mate.Username}).Create(s, leaver))
		})
		probeDeleteAccount(t, leaver)
		probeTeamState(t, "after ", team.ID)
		probeRead(t, "after : teammate permissions on the team", func(s *xorm.Session) (string, error) {
			upd, e1 := (&Team{ID: team.ID}).CanUpdate(s, mate)
			del, e2 := (&Team{ID: team.ID}).CanDelete(s, mate)
			add, e3 := (&TeamMember{TeamID: team.ID, Username: "user1"}).CanCreate(s, mate)
			return fmt.Sprintf("CanUpdate=%v(%v) CanDelete=%v(%v) can-add-member=%v(%v)", upd, e1, del, e2, add, e3), nil
		})
	})
}
EOF
