package webtests

// TEMPORARY audit probes - not part of the codebase, removed after the run.
// Every request goes through the real router (routes.NewEcho + RegisterRoutes)
// with a session obtained from the real login endpoint. Outcomes are logged,
// not asserted.

import (
	"context"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"net/http"
	"net/http/httptest"
	"sort"
	"strings"
	"testing"
	"time"

	"code.vikunja.io/api/pkg/config"
	"code.vikunja.io/api/pkg/db"
	"code.vikunja.io/api/pkg/events"
	"code.vikunja.io/api/pkg/files"
	"code.vikunja.io/api/pkg/log"
	"code.vikunja.io/api/pkg/models"
	"code.vikunja.io/api/pkg/modules/auth"
	"code.vikunja.io/api/pkg/modules/keyvalue"
	"code.vikunja.io/api/pkg/notifications"
	"code.vikunja.io/api/pkg/routes"
	"code.vikunja.io/api/pkg/user"
	"code.vikunja.io/api/pkg/utils"

	"github.com/labstack/echo/v5"
	"github.com/pquerna/otp/totp"
	"github.com/stretchr/testify/require"
)

const probePW = "12345678" // fixture password of user1/user2/...

type probeEnv struct {
	t *testing.T
	e *echo.Echo
}

// newProbeEnv mirrors setupTestEnv but lets the caller change config before
// the routes (and their rate limiters) are built.
func newProbeEnv(t *testing.T, tweak func()) *probeEnv {
	t.Helper()
	config.InitDefaultConfig()
	config.ServicePublicURL.Set("https://localhost")
	log.InitLogger()
	files.InitTests()
	user.InitTests()
	models.SetupTests()
	events.Fake()
	keyvalue.InitStorage()
	if tweak != nil {
		tweak()
	}
	require.NoError(t, db.LoadFixtures())
	notifications.Fake()
	t.Cleanup(notifications.Unfake)
	e := routes.NewEcho()
	routes.RegisterRoutes(e)
	return &probeEnv{t: t, e: e}
}

func (p *probeEnv) do(method, path, body, bearer string, cookies ...*http.Cookie) *httptest.ResponseRecorder {
	req := httptest.NewRequest(method, path, strings.NewReader(body))
	req.Header.Set("Content-Type", "application/json")
	if bearer != "" {
		req.Header.Set("Authorization", "Bearer "+bearer)
	}
	for _, c := range cookies {
		req.AddCookie(c)
	}
	rec := httptest.NewRecorder()
	p.e.ServeHTTP(rec, req)
	return rec
}

func brief(rec *httptest.ResponseRecorder) string {
	b := strings.Join(strings.Fields(rec.Body.String()), " ")
	if len(b) > 150 {
		b = b[:150] + "..."
	}
	return fmt.Sprintf("%d %s", rec.Code, b)
}

// login goes through the real login endpoint and returns the access JWT and refresh cookies.
func (p *probeEnv) login(username, password, totpCode string) (string, []*http.Cookie, *httptest.ResponseRecorder) {
	body := fmt.Sprintf(`{"username":%q,"password":%q,"totp_passcode":%q}`, username, password, totpCode)
	rec := p.do(http.MethodPost, "/api/v2/login", body, "")
	var out struct {
		Token string `json:"token"`
	}
	_ = json.Unmarshal(rec.Body.Bytes(), &out)
	return out.Token, refreshCookies(rec), rec
}

func probeFailedCounter(userID int64) string {
	v, ok, _ := keyvalue.Get((&user.User{ID: userID}).GetFailedPasswordAttemptsKey())
	if !ok {
		return "-"
	}
	return fmt.Sprint(v)
}

func probeUserRow(t *testing.T, id int64) *user.User {
	s := db.NewSession()
	defer s.Close()
	u := &user.User{}
	has, err := s.Where("id = ?", id).Get(u)
	require.NoError(t, err)
	if !has {
		return &user.User{}
	}
	return u
}

type probeAction struct {
	name          string
	method, path  string
	body          func(pw string) string // pw == "" means "leave the password out"
	passwordCheck bool
}

func pwBody(extra string) func(string) string {
	return func(pw string) string {
		if pw == "" {
			if extra == "" {
				return `{}`
			}
			return `{` + extra + `}`
		}
		if extra == "" {
			return fmt.Sprintf(`{"password":%q}`, pw)
		}
		return fmt.Sprintf(`{"password":%q,%s}`, pw, extra)
	}
}

func oldPwBody(pw string) string {
	if pw == "" {
		return `{"new_password":"BrandNewPassw0rd"}`
	}
	return fmt.Sprintf(`{"old_password":%q,"new_password":"BrandNewPassw0rd"}`, pw)
}

var probePasswordActions = []probeAction{
	{"change password v1", http.MethodPost, "/api/v1/user/password", oldPwBody, true},
	{"change password v2", http.MethodPost, "/api/v2/user/password", oldPwBody, true},
	{"change email v1", http.MethodPost, "/api/v1/user/settings/email", pwBody(`"new_email":"moved@example.com"`), true},
	{"change email v2", http.MethodPut, "/api/v2/user/settings/email", pwBody(`"new_email":"moved@example.com"`), true},
	{"disable 2fa v1", http.MethodPost, "/api/v1/user/settings/totp/disable", pwBody(""), true},
	{"disable 2fa v2", http.MethodPost, "/api/v2/user/settings/totp/disable", pwBody(""), true},
	{"request export v1", http.MethodPost, "/api/v1/user/export/request", pwBody(""), true},
	{"request export v2", http.MethodPost, "/api/v2/user/export/request", pwBody(""), true},
	{"download export v1", http.MethodPost, "/api/v1/user/export/download", pwBody(""), true},
	{"download export v2", http.MethodPost, "/api/v2/user/export/download", pwBody(""), true},
	{"request deletion v1", http.MethodPost, "/api/v1/user/deletion/request", pwBody(""), true},
	{"request deletion v2", http.MethodPost, "/api/v2/user/deletion/request", pwBody(""), true},
	{"cancel deletion v1", http.MethodPost, "/api/v1/user/deletion/cancel", pwBody(""), true},
	{"cancel deletion v2", http.MethodPost, "/api/v2/user/deletion/cancel", pwBody(""), true},
}

// ---------------------------------------------------------------------------
// 1: what each action demands
// ---------------------------------------------------------------------------

func TestAuditProbeSens1_Demands(t *testing.T) {
	for _, a := range probePasswordActions {
		t.Run(a.name, func(t *testing.T) {
			p := newProbeEnv(t, nil)
			jwt, _, lrec := p.login("user2", probePW, "")
			require.NotEmpty(t, jwt, lrec.Body.String())
			t.Logf("PROBE %-20s no session        -> %s", a.name, brief(p.do(a.method, a.path, a.body(probePW), "")))
			t.Logf("PROBE %-20s session, no pw    -> %s", a.name, brief(p.do(a.method, a.path, a.body(""), jwt)))
			t.Logf("PROBE %-20s session, wrong pw -> %s", a.name, brief(p.do(a.method, a.path, a.body("not-the-password"), jwt)))
			t.Logf("PROBE %-20s session, right pw -> %s", a.name, brief(p.do(a.method, a.path, a.body(probePW), jwt)))
			u := probeUserRow(t, 2)
			s := db.NewSession()
			sessions, _ := s.Where("user_id = ?", 2).Count(&models.Session{})
			s.Close()
			t.Logf("PROBE %-20s afterwards: email=%q pending=%q sessions-left=%d old-jwt-still-accepted=%d",
				a.name, u.Email, u.PendingEmail, sessions, p.do(http.MethodGet, "/api/v2/user", "", jwt).Code)
		})
	}

	t.Run("actions that take no password at all", func(t *testing.T) {
		p := newProbeEnv(t, nil)
		jwt, _, _ := p.login("user2", probePW, "")
		for _, a := range []struct{ name, method, path, body string }{
			{"2fa enroll v1", http.MethodPost, "/api/v1/user/settings/totp/enroll", ""},
			{"2fa status v1 (shows secret until enabled)", http.MethodGet, "/api/v1/user/settings/totp", ""},
			{"2fa enable v1 (bad code)", http.MethodPost, "/api/v1/user/settings/totp/enable", `{"passcode":"000000"}`},
			{"new CalDAV token v1", http.MethodPut, "/api/v1/user/settings/token/caldav", ""},
			{"new CalDAV token v2", http.MethodPost, "/api/v2/user/settings/token/caldav", ""},
			{"new API token v1", http.MethodPut, "/api/v1/tokens", `{"title":"x","permissions":{"tasks":["read_all"]},"expires_at":"2099-01-01T00:00:00Z"}`},
			{"new API token v2", http.MethodPost, "/api/v2/tokens", `{"title":"x","permissions":{"tasks":["read_all"]},"expires_at":"2099-01-01T00:00:00Z"}`},
			{"confirm deletion v1 (bad token)", http.MethodPost, "/api/v1/user/deletion/confirm", `{"token":"nope"}`},
			{"confirm deletion v2 (bad token)", http.MethodPost, "/api/v2/user/deletion/confirm", `{"token":"nope"}`},
			{"list sessions v2", http.MethodGet, "/api/v2/user/sessions", ""},
		} {
			t.Logf("PROBE %-44s -> %s", a.name, brief(p.do(a.method, a.path, a.body, jwt)))
		}
	})
}

// ---------------------------------------------------------------------------
// 2: guessing the password with a stolen session
// ---------------------------------------------------------------------------

func probeGuess(t *testing.T, p *probeEnv, a probeAction, jwt string, guesses int) {
	codes := map[int]int{}
	mails := 0
	first429 := 0
	for i := 1; i <= guesses; i++ {
		before := probeFailedCounter(2)
		rec := p.do(a.method, a.path, a.body(fmt.Sprintf("guess-%04d", i)), jwt)
		codes[rec.Code]++
		if rec.Code == http.StatusTooManyRequests && first429 == 0 {
			first429 = i
		}
		// the warning mail goes out on the third counted failure, which also clears the counter
		if before == "2" && probeFailedCounter(2) == "-" {
			mails++
		}
	}
	var cs []string
	for c, n := range codes {
		cs = append(cs, fmt.Sprintf("%d x%d", c, n))
	}
	sort.Strings(cs)
	u := probeUserRow(t, 2)
	final := p.do(a.method, a.path, a.body(probePW), jwt)
	t.Logf("PROBE %-20s %d wrong guesses -> responses [%s] first-429-at=%d failed-login-counter-now=%s warning-mails=%d account-status=%s | then the right password -> %d",
		a.name, guesses, strings.Join(cs, ", "), first429, probeFailedCounter(2), mails, u.Status, final.Code)
}

func TestAuditProbeSens2_Guessing(t *testing.T) {
	for _, a := range probePasswordActions {
		t.Run("default config: "+a.name, func(t *testing.T) {
			p := newProbeEnv(t, nil)
			jwt, _, _ := p.login("user2", probePW, "")
			probeGuess(t, p, a, jwt, 40)
		})
	}
	for _, a := range []probeAction{probePasswordActions[0], probePasswordActions[1], probePasswordActions[4], probePasswordActions[5]} {
		t.Run("ratelimit.enabled=true: "+a.name, func(t *testing.T) {
			p := newProbeEnv(t, func() { config.RateLimitEnabled.Set(true) })
			jwt, _, _ := p.login("user2", probePW, "")
			probeGuess(t, p, a, jwt, 130)
		})
	}
}

// ---------------------------------------------------------------------------
// 3: whose password is checked
// ---------------------------------------------------------------------------

func TestAuditProbeSens3_WhosePassword(t *testing.T) {
	t.Run("another local user's password is not accepted", func(t *testing.T) {
		p := newProbeEnv(t, nil)
		// give user1 a distinct password so the two accounts differ
		s := db.NewSession()
		require.NoError(t, user.UpdateUserPassword(s, &user.User{ID: 1}, "user1-own-password"))
		require.NoError(t, s.Commit())
		s.Close()
		jwt, _, _ := p.login("user2", probePW, "")
		for _, a := range probePasswordActions {
			t.Logf("PROBE user2 session + user1's password on %-20s -> %d", a.name, p.do(a.method, a.path, a.body("user1-own-password"), jwt).Code)
		}
	})

	t.Run("caller whose username equals another account's email", func(t *testing.T) {
		p := newProbeEnv(t, nil)
		// An externally provisioned account (OIDC/LDAP style: issuer + subject, no local
		// password) whose username is the email address of local user1. CreateUser is
		// the function the OIDC and LDAP provisioning paths call.
		s := db.NewSession()
		shadow, err := user.CreateUser(s, &user.User{
			Username: "user1@example.com",
			Email:    "shadow@idp.test",
			Issuer:   "https://idp.test",
			Subject:  "shadow-1",
		})
		t.Logf("PROBE creating external account with username %q: err=%v", "user1@example.com", err)
		require.NoError(t, err)
		require.NoError(t, s.Commit())
		s.Close()

		// The OIDC callback issues the session with exactly this call after a successful login.
		tok, err := auth.IssueUserToken(context.Background(), shadow, "probe", "127.0.0.1", false, nil)
		require.NoError(t, err)
		jwt := tok.AccessToken

		before1, beforeS := probeUserRow(t, 1), probeUserRow(t, shadow.ID)

		rec := p.do(http.MethodPost, "/api/v2/user/password", oldPwBody("wrong-guess"), jwt)
		t.Logf("PROBE shadow session, change password, wrong guess     -> %s | failed-login counter: user1=%s shadow=%s",
			brief(rec), probeFailedCounter(1), probeFailedCounter(shadow.ID))

		rec = p.do(http.MethodPut, "/api/v2/user/settings/email", pwBody(`"new_email":"attacker@evil.test"`)(probePW), jwt)
		after1, afterS := probeUserRow(t, 1), probeUserRow(t, shadow.ID)
		t.Logf("PROBE shadow session, change email with USER1's password -> %s", brief(rec))
		t.Logf("PROBE   user1 email:  %q -> %q", before1.Email, after1.Email)
		t.Logf("PROBE   shadow email: %q -> %q", beforeS.Email, afterS.Email)

		rec = p.do(http.MethodPost, "/api/v2/user/password", oldPwBody(probePW), jwt)
		after1, afterS = probeUserRow(t, 1), probeUserRow(t, shadow.ID)
		t.Logf("PROBE shadow session, change password with USER1's password -> %s", brief(rec))
		t.Logf("PROBE   user1 password hash changed:  %v", before1.Password != after1.Password)
		t.Logf("PROBE   shadow password hash changed: %v (was empty: %v)", beforeS.Password != afterS.Password, beforeS.Password == "")
	})

	t.Run("externally authenticated caller: which actions skip the password", func(t *testing.T) {
		p := newProbeEnv(t, nil)
		s := db.NewSession()
		ext, err := user.CreateUser(s, &user.User{Username: "extuser", Email: "ext@idp.test", Issuer: "https://idp.test", Subject: "ext-1"})
		require.NoError(t, err)
		require.NoError(t, models.CreateNewProjectForUser(s, ext))
		require.NoError(t, s.Commit())
		s.Close()
		tok, err := auth.IssueUserToken(context.Background(), ext, "probe", "127.0.0.1", false, nil)
		require.NoError(t, err)
		// a finished export, made by the real export code, so download has something to return
		s = db.NewSession()
		full := &user.User{}
		_, _ = s.ID(ext.ID).Get(full)
		require.NoError(t, models.ExportUserData(s, full))
		require.NoError(t, s.Commit())
		s.Close()
		for _, a := range probePasswordActions {
			rec := p.do(a.method, a.path, a.body(""), tok.AccessToken)
			b := brief(rec)
			if strings.Contains(a.name, "download") && rec.Code == 200 {
				b = fmt.Sprintf("200 <%d bytes, %s>", rec.Body.Len(), rec.Header().Get("Content-Type"))
			}
			t.Logf("PROBE external user, session only, %-20s -> %s", a.name, b)
		}
		u := probeUserRow(t, ext.ID)
		t.Logf("PROBE external user afterwards: deletion_scheduled_at=%v", u.DeletionScheduledAt)
	})
}

// ---------------------------------------------------------------------------
// 4: what a stolen session can do without ever knowing the password
// ---------------------------------------------------------------------------

func TestAuditProbeSens4_StolenSession(t *testing.T) {
	t.Run("turn 2fa on for the victim", func(t *testing.T) {
		p := newProbeEnv(t, nil)
		stolen, _, _ := p.login("user2", probePW, "")

		rec := p.do(http.MethodPost, "/api/v2/user/settings/totp/enroll", "", stolen)
		var enroll struct {
			Secret string `json:"secret"`
		}
		_ = json.Unmarshal(rec.Body.Bytes(), &enroll)
		t.Logf("PROBE attacker: enroll 2fa with stolen session -> %d (secret returned: %v)", rec.Code, enroll.Secret != "")
		code, err := totp.GenerateCode(enroll.Secret, time.Now())
		require.NoError(t, err)
		rec = p.do(http.MethodPost, "/api/v2/user/settings/totp/enable", fmt.Sprintf(`{"passcode":%q}`, code), stolen)
		t.Logf("PROBE attacker: enable 2fa with a code from that secret -> %s", brief(rec))

		_, _, lrec := p.login("user2", probePW, "")
		t.Logf("PROBE victim: log in with the correct password -> %s", brief(lrec))

		// victim tries the only self-service recovery there is: password reset by email.
		// The clear-text token only exists in the email, so plant one with a known value.
		s := db.NewSession()
		_, err = s.Insert(&user.Token{UserID: 2, Kind: user.TokenPasswordReset, Token: utils.Sha256Hex("probe-reset-token")})
		require.NoError(t, err)
		require.NoError(t, s.Commit())
		s.Close()
		rec = p.do(http.MethodPost, "/api/v2/user/password/reset", `{"token":"probe-reset-token","new_password":"VictimNewPassw0rd"}`, "")
		t.Logf("PROBE victim: reset password via emailed token -> %s", brief(rec))
		_, _, lrec = p.login("user2", "VictimNewPassw0rd", "")
		t.Logf("PROBE victim: log in with the new password -> %s", brief(lrec))

		atk, _, arec := p.login("user2", "VictimNewPassw0rd", func() string { c, _ := totp.GenerateCode(enroll.Secret, time.Now().Add(31*time.Second)); return c }())
		t.Logf("PROBE (for reference) login with new password + attacker-held 2fa secret -> %d token=%v", arec.Code, atk != "")
	})

	t.Run("keep access after the victim changes the password", func(t *testing.T) {
		p := newProbeEnv(t, nil)
		stolen, stolenCookies, _ := p.login("user2", probePW, "")

		rec := p.do(http.MethodPost, "/api/v2/tokens", `{"title":"backdoor","permissions":{"tasks":["read_all"],"projects":["read_all"]},"expires_at":"2099-01-01T00:00:00Z"}`, stolen)
		var apiTok struct {
			Token string `json:"token"`
		}
		_ = json.Unmarshal(rec.Body.Bytes(), &apiTok)
		t.Logf("PROBE attacker: mint API token with stolen session (no password) -> %d token=%v", rec.Code, apiTok.Token != "")

		rec = p.do(http.MethodPut, "/api/v1/user/settings/token/caldav", "", stolen)
		var dav struct {
			Token string `json:"token"`
		}
		_ = json.Unmarshal(rec.Body.Bytes(), &dav)
		t.Logf("PROBE attacker: mint CalDAV token with stolen session (no password) -> %d token=%v", rec.Code, dav.Token != "")

		// victim notices and changes the password from their own, separate session
		victim, _, _ := p.login("user2", probePW, "")
		rec = p.do(http.MethodPost, "/api/v2/user/password", `{"old_password":"12345678","new_password":"VictimNewPassw0rd"}`, victim)
		t.Logf("PROBE victim: change password -> %s", brief(rec))
		s := db.NewSession()
		n, _ := s.Where("user_id = ?", 2).Count(&models.Session{})
		s.Close()
		t.Logf("PROBE   sessions left in the database for the victim: %d", n)

		t.Logf("PROBE attacker afterwards: stolen access JWT, GET /user            -> %d", p.do(http.MethodGet, "/api/v2/user", "", stolen).Code)
		t.Logf("PROBE attacker afterwards: stolen access JWT, list tasks           -> %d", p.do(http.MethodGet, "/api/v2/tasks", "", stolen).Code)
		rec = p.do(http.MethodPost, "/api/v2/tokens", `{"title":"backdoor2","permissions":{"tasks":["read_all"]},"expires_at":"2099-01-01T00:00:00Z"}`, stolen)
		t.Logf("PROBE attacker afterwards: stolen access JWT, mint another API token -> %d", rec.Code)
		t.Logf("PROBE attacker afterwards: stolen refresh cookie, refresh           -> %s", brief(p.do(http.MethodPost, "/api/v2/user/token/refresh", "", "", stolenCookies...)))
		t.Logf("PROBE attacker afterwards: API token minted earlier, list tasks     -> %d", p.do(http.MethodGet, "/api/v2/tasks", "", apiTok.Token).Code)

		req := httptest.NewRequest("PROPFIND", "/dav/principals/user2/", strings.NewReader(""))
		req.Header.Set("Authorization", "Basic "+base64.StdEncoding.EncodeToString([]byte("user2:"+dav.Token)))
		req.Header.Set("Depth", "0")
		drec := httptest.NewRecorder()
		p.e.ServeHTTP(drec, req)
		t.Logf("PROBE attacker afterwards: CalDAV token minted earlier, PROPFIND    -> %d", drec.Code)
		req = httptest.NewRequest("PROPFIND", "/dav/principals/user2/", strings.NewReader(""))
		req.Header.Set("Authorization", "Basic "+base64.StdEncoding.EncodeToString([]byte("user2:definitely-wrong")))
		req.Header.Set("Depth", "0")
		drec = httptest.NewRecorder()
		p.e.ServeHTTP(drec, req)
		t.Logf("PROBE   (control) CalDAV with a wrong token                         -> %d", drec.Code)
	})

	t.Run("API tokens and link shares on the sensitive routes", func(t *testing.T) {
		p := newProbeEnv(t, nil)
		jwt, _, _ := p.login("user2", probePW, "")
		// ask the server for every permission a token can hold, and request all of them
		rec := p.do(http.MethodGet, "/api/v1/routes", "", jwt)
		var groups map[string]map[string]json.RawMessage
		require.NoError(t, json.Unmarshal(rec.Body.Bytes(), &groups))
		perms := map[string][]string{}
		var names []string
		for g, rs := range groups {
			names = append(names, g)
			for r := range rs {
				perms[g] = append(perms[g], r)
			}
		}
		sort.Strings(names)
		t.Logf("PROBE permission groups a token can be granted: %v", names)
		pj, _ := json.Marshal(perms)
		rec = p.do(http.MethodPut, "/api/v1/tokens", fmt.Sprintf(`{"title":"everything","permissions":%s,"expires_at":"2099-01-01T00:00:00Z"}`, pj), jwt)
		var apiTok struct {
			Token string `json:"token"`
		}
		_ = json.Unmarshal(rec.Body.Bytes(), &apiTok)
		require.NotEmpty(t, apiTok.Token, rec.Body.String())
		t.Logf("PROBE   (control) all-permission API token, list tasks -> %d", p.do(http.MethodGet, "/api/v1/tasks", "", apiTok.Token).Code)
		for _, a := range probePasswordActions {
			t.Logf("PROBE all-permission API token + right password on %-20s -> %d", a.name, p.do(a.method, a.path, a.body(probePW), apiTok.Token).Code)
		}
		t.Logf("PROBE all-permission API token, mint another API token -> %d", p.do(http.MethodPut, "/api/v1/tokens", `{"title":"x","permissions":{"tasks":["read_all"]},"expires_at":"2099-01-01T00:00:00Z"}`, apiTok.Token).Code)
		t.Logf("PROBE all-permission API token, mint CalDAV token      -> %d", p.do(http.MethodPut, "/api/v1/user/settings/token/caldav", "", apiTok.Token).Code)
		t.Logf("PROBE all-permission API token, 2fa enroll             -> %d", p.do(http.MethodPost, "/api/v1/user/settings/totp/enroll", "", apiTok.Token).Code)
	})
}

