// RequireInstanceAdmin serves 404 to make admin routes indistinguishable from unregistered ones,
// and re-reads is_admin from the DB so demotion takes effect before the JWT expires.
func RequireInstanceAdmin() echo.MiddlewareFunc {
	return func(next echo.HandlerFunc) echo.HandlerFunc {
		return func(c *echo.Context) error {
			a, err := auth2.GetAuthFromClaims(c)
			if err != nil {
				return echo.ErrNotFound
			}
			u, ok := a.(*user.User)
			if !ok {
				return echo.ErrNotFound
			}

			// Close before next() — SQLite deadlocks when a read session is held across a write on users.
			s := db.NewSession()
			fresh, err := user.GetUserByID(s, u.ID)
			_ = s.Close()
			if err != nil {
				return echo.ErrNotFound
			}
			if !fresh.IsAdmin {
				// Privilege-probing signal for the audit log. Only dispatched
				// for a confirmed non-admin — the other refusals (no claims,
				// link share, failed user read) can't be attributed to a
				// verified account and would write misleading entries.
				dispatchErr := events.DispatchWithContext(c.Request().Context(), &models.AdminAccessDeniedEvent{
					Doer:   u,
					Method: c.Request().Method,
					Path:   c.Request().URL.Path,
				})
				if dispatchErr != nil {
					log.Errorf("Could not dispatch admin access denied event: %s", dispatchErr)
				}
				return echo.ErrNotFound
			}
			return next(c)
		}
	}
}
