package webtests

// TEMPORARY audit probes - not part of the codebase, removed after the run.
// Every credential is obtained through the real endpoints while the account is
// active, the account is then moved into a blocked state the way production
// does it, and every credential is tried again through the real router.
// Outcomes are logged, not asserted.

import (
	"context"
	"crypto/sha256"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
	"time"

	"code.vikunja.io/api/pkg/config"
	"code.vikunja.io/api/pkg/db"
	"code.vikunja.io/api/pkg/events"
	"code.vikunja.io/api/pkg/files"
	"code.vikunja.io/api/pkg/license"
	"code.vikunja.io/api/pkg/log"
	"code.vikunja.io/api/pkg/models"
	"code.vikunja.io/api/pkg/modules/keyvalue"
	"code.vikunja.io/api/pkg/notifications"
	"code.vikunja.io/api/pkg/routes"
	"code.vikunja.io/api/pkg/user"
	"code.vikunja.io/api/pkg/utils"

	"github.com/coder/websocket"
	"github.com/coder/websocket/wsjson"
	"github.com/labstack/echo/v5"
	"github.com/pquerna/otp/totp"
	"github.com/stretchr/testify/require"
)

type probeEnv struct {
	t *testing.T
	e *echo.Echo
}

func newProbeEnv(t *testing.T) *probeEnv {
	t.Helper()
	config.InitDefaultConfig()
	config.ServicePublicURL.Set("https://localhost")
	log.InitLogger()
	files.InitTests()
	user.InitTests()
	models.SetupTests()
	events.Fake()
	keyvalue.InitStorage()
	// Production-like for an instance with public signup: mail on.
	config.MailerEnabled.Set(true)
	// The probe sends far more auth requests from one address than the per-IP
	// floors allow; raise them so they do not mask the result under test.
	config.RateLimitNoAuthRoutesLimit.Set(100000)
	config.RateLimitTokenRefreshLimit.Set(100000)
	config.RateLimitBasicAuthLimit.Set(100000)
	require.NoError(t, db.LoadFixtures())
	notifications.Fake()
	t.Cleanup(notifications.Unfake)
	license.SetForTests([]license.Feature{license.FeatureAdminPanel})
	t.Cleanup(license.ResetForTests)
	e := routes.NewEcho()
	routes.RegisterRoutes(e)
	return &probeEnv{t: t, e: e}
}

func (p *probeEnv) req(method, path, body string, hdr map[string]string, cookies ...*http.Cookie) *httptest.ResponseRecorder {
	r := httptest.NewRequest(method, path, strings.NewReader(body))
	r.Header.Set("Content-Type", "application/json")
	for k, v := range hdr {
		r.Header.Set(k, v)
	}
	for _, c := range cookies {
		r.AddCookie(c)
	}
	rec := httptest.NewRecorder()
	p.e.ServeHTTP(rec, r)
	return rec
}

func bearer(tok string) map[string]string { return map[string]string{"Authorization": "Bearer " + tok} }
func basic(u, pw string) map[string]string {
	return map[string]string{"Authorization": "Basic " + base64.StdEncoding.EncodeToString([]byte(u+":"+pw)), "Depth": "0"}
}

func short(rec *httptest.ResponseRecorder) string {
	if rec.Code < 300 {
		return fmt.Sprint(rec.Code)
	}
	var b struct {
		Message string `json:"message"`
		Detail  string `json:"detail"`
	}
	_ = json.Unmarshal(rec.Body.Bytes(), &b)
	m := b.Message
	if m == "" {
		m = b.Detail
	}
	if len(m) > 70 {
		m = m[:70]
	}
	return fmt.Sprintf("%d %s", rec.Code, m)
}

func field(rec *httptest.ResponseRecorder, name string) string {
	var m map[string]any
	_ = json.Unmarshal(rec.Body.Bytes(), &m)
	switch v := m[name].(type) {
	case string:
		return v
	case float64:
		return fmt.Sprint(int64(v))
	}
	return ""
}

type target struct {
	id                        int64
	username, email, password string
	totpSecret                string
}

type creds struct {
	t  *testing.T
	p  *probeEnv
	tg target

	codeStep int

	jwt                string
	cookieV1, cookieV2 []*http.Cookie
	apiTok, davTok     string
	projectID          string
	shareHash          string
	shareJWT           string
	verifier           string
	oauthAccess        string
	oauthRefresh       string
	oauthCodeHeld      string
	botTok             string
	wsURL              string
	mintedAfter        string
}

// nextCode hands out a different still-valid passcode each time (a code cannot be reused).
func (c *creds) nextCode() string {
	if c.tg.totpSecret == "" {
		return ""
	}
	offsets := []time.Duration{0, 30 * time.Second, -30 * time.Second}
	code, _ := totp.GenerateCode(c.tg.totpSecret, time.Now().Add(offsets[c.codeStep%len(offsets)]))
	c.codeStep++
	return code
}

func (c *creds) login(path, name, password string) *httptest.ResponseRecorder {
	return c.p.req(http.MethodPost, path, fmt.Sprintf(`{"username":%q,"password":%q,"totp_passcode":%q}`, name, password, c.nextCode()), nil)
}

func (c *creds) challenge() string {
	sum := sha256.Sum256([]byte(c.verifier))
	return base64.RawURLEncoding.EncodeToString(sum[:])
}

func (c *creds) authorize(jwt string) *httptest.ResponseRecorder {
	return c.p.req(http.MethodPost, "/api/v1/oauth/authorize", fmt.Sprintf(
		`{"response_type":"code","client_id":"vikunja","redirect_uri":"vikunja-flutter://callback","code_challenge":%q,"code_challenge_method":"S256","state":"s"}`, c.challenge()), bearer(jwt))
}

func (c *creds) exchange(code string) *httptest.ResponseRecorder {
	return c.p.req(http.MethodPost, "/api/v1/oauth/token", fmt.Sprintf(
		`{"grant_type":"authorization_code","code":%q,"client_id":"vikunja","redirect_uri":"vikunja-flutter://callback","code_verifier":%q}`, code, c.verifier), nil)
}

const tokenBody = `{"title":"probe","permissions":%s,"expires_at":"2099-01-01T00:00:00Z"%s}`

// establish obtains one of every credential while the account is active.
func establish(t *testing.T, p *probeEnv, tg target) *creds {
	c := &creds{t: t, p: p, tg: tg, verifier: "probe-verifier-probe-verifier-probe-verifier-0123456789"}

	rec := c.login("/api/v2/login", tg.username, tg.password)
	require.Equal(t, 200, rec.Code, rec.Body.String())
	c.jwt, c.cookieV1 = field(rec, "token"), refreshCookies(rec)
	rec = c.login("/api/v2/login", tg.username, tg.password)
	require.Equal(t, 200, rec.Code, rec.Body.String())
	c.cookieV2 = refreshCookies(rec)

	rec = p.req(http.MethodPost, "/api/v2/projects", `{"title":"probe project"}`, bearer(c.jwt))
	require.Less(t, rec.Code, 300, rec.Body.String())
	c.projectID = field(rec, "id")
	rec = p.req(http.MethodPost, "/api/v2/projects/"+c.projectID+"/tasks", `{"title":"probe task"}`, bearer(c.jwt))
	require.Less(t, rec.Code, 300, rec.Body.String())

	// API token: tasks/projects read plus every permission of the caldav, feeds and mcp groups
	rec = p.req(http.MethodGet, "/api/v1/routes", "", bearer(c.jwt))
	var groups map[string]map[string]json.RawMessage
	require.NoError(t, json.Unmarshal(rec.Body.Bytes(), &groups))
	perms := map[string][]string{"tasks": {"read_all"}, "projects": {"read_all"}}
	for _, g := range []string{"caldav", "feeds", "mcp"} {
		for k := range groups[g] {
			perms[g] = append(perms[g], k)
		}
	}
	pj, _ := json.Marshal(perms)
	rec = p.req(http.MethodPost, "/api/v2/tokens", fmt.Sprintf(tokenBody, pj, ""), bearer(c.jwt))
	require.Less(t, rec.Code, 300, rec.Body.String())
	c.apiTok = field(rec, "token")

	rec = p.req(http.MethodPut, "/api/v1/user/settings/token/caldav", "", bearer(c.jwt))
	require.Less(t, rec.Code, 300, rec.Body.String())
	c.davTok = field(rec, "token")

	rec = p.req(http.MethodPost, "/api/v2/projects/"+c.projectID+"/shares", `{"permission":0}`, bearer(c.jwt))
	require.Less(t, rec.Code, 300, rec.Body.String())
	c.shareHash = field(rec, "hash")
	rec = p.req(http.MethodPost, "/api/v2/shares/"+c.shareHash+"/auth", "", nil)
	require.Less(t, rec.Code, 300, rec.Body.String())
	c.shareJWT = field(rec, "token")

	rec = c.exchange(field(c.authorize(c.jwt), "code"))
	require.Less(t, rec.Code, 300, rec.Body.String())
	c.oauthAccess, c.oauthRefresh = field(rec, "access_token"), field(rec, "refresh_token")
	rec = c.authorize(c.jwt)
	require.Less(t, rec.Code, 300, rec.Body.String())
	c.oauthCodeHeld = field(rec, "code")

	rec = p.req(http.MethodPost, "/api/v2/user/bots", fmt.Sprintf(`{"username":"bot-probe-%d"}`, tg.id), bearer(c.jwt))
	if rec.Code < 300 {
		botID := field(rec, "id")
		rec = p.req(http.MethodPost, "/api/v2/tokens", fmt.Sprintf(tokenBody, `{"projects":["read_all"],"tasks":["read_all"]}`, `,"owner_id":`+botID), bearer(c.jwt))
		if rec.Code < 300 {
			c.botTok = field(rec, "token")
		}
	}
	if c.botTok == "" {
		t.Logf("PROBE   (could not set up a bot token: %s)", short(rec))
	}

	// pending email change through the real endpoint; the clear-text confirm token only
	// exists in the email, so a second one with a known value is planted next to it
	rec = p.req(http.MethodPut, "/api/v2/user/settings/email", fmt.Sprintf(`{"new_email":"new-%d@example.com","password":%q}`, tg.id, tg.password), bearer(c.jwt))
	require.Less(t, rec.Code, 300, rec.Body.String())
	s := db.NewSession()
	_, err := s.Insert(&user.Token{UserID: tg.id, Kind: user.TokenEmailConfirm, Token: utils.Sha256Hex(fmt.Sprintf("probe-confirm-%d", tg.id))})
	require.NoError(t, err)
	_, err = s.Insert(&user.Token{UserID: tg.id, Kind: user.TokenPasswordReset, Token: utils.Sha256Hex(fmt.Sprintf("probe-reset-%d", tg.id))})
	require.NoError(t, err)
	require.NoError(t, s.Commit())
	s.Close()

	srv := httptest.NewServer(p.e)
	t.Cleanup(srv.Close)
	c.wsURL = "ws" + strings.TrimPrefix(srv.URL, "http") + "/api/v2/ws"
	return c
}

func (c *creds) wsAuth(tok string) string {
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	conn, resp, err := websocket.Dial(ctx, c.wsURL, nil)
	if err != nil {
		return "dial failed: " + err.Error()
	}
	if resp != nil && resp.Body != nil {
		_ = resp.Body.Close()
	}
	defer func() { _ = conn.CloseNow() }()
	if err := wsjson.Write(ctx, conn, map[string]string{"action": "auth", "token": tok}); err != nil {
		return "write failed: " + err.Error()
	}
	var reply map[string]any
	if err := wsjson.Read(ctx, conn, &reply); err != nil {
		return "closed: " + websocket.CloseStatus(err).String()
	}
	if reply["action"] == "auth.success" {
		return "200"
	}
	return fmt.Sprintf("refused %v", reply)
}

type check struct {
	name string
	run  func(after bool) string
}

func (c *creds) checks() []check {
	p, tg := c.p, c.tg
	get := func(path string, hdr map[string]string) func(bool) string {
		return func(bool) string { return short(p.req(http.MethodGet, path, "", hdr)) }
	}
	dav := func(pw func() string) func(bool) string {
		return func(bool) string {
			return short(p.req("PROPFIND", "/dav/principals/"+tg.username+"/", "", basic(tg.username, pw())))
		}
	}
	return []check{
		{"password: login v2 by username", func(bool) string { return short(c.login("/api/v2/login", tg.username, tg.password)) }},
		{"password: login v2 by email", func(after bool) string {
			if !after && tg.totpSecret != "" {
				return "(skipped)"
			}
			return short(c.login("/api/v2/login", tg.email, tg.password))
		}},
		{"password: login v1 by username", func(after bool) string {
			if !after && tg.totpSecret != "" {
				return "(skipped)"
			}
			return short(c.login("/api/v1/login", tg.username, tg.password))
		}},
		{"password: CalDAV basic auth", dav(func() string { return tg.password })},

		{"session access token: read own profile", get("/api/v2/user", bearer(c.jwt))},
		{"session access token: list projects", get("/api/v2/projects", bearer(c.jwt))},
		{"session access token: create a task", func(bool) string {
			return short(p.req(http.MethodPost, "/api/v2/projects/"+c.projectID+"/tasks", `{"title":"written while blocked?"}`, bearer(c.jwt)))
		}},
		{"session access token: mint an API token", func(after bool) string {
			rec := p.req(http.MethodPost, "/api/v2/tokens", fmt.Sprintf(tokenBody, `{"tasks":["read_all"]}`, ""), bearer(c.jwt))
			if after && rec.Code < 300 {
				c.mintedAfter = field(rec, "token")
			}
			return short(rec)
		}},
		{"session access token: mint a CalDAV token", func(bool) string {
			return short(p.req(http.MethodPut, "/api/v1/user/settings/token/caldav", "", bearer(c.jwt)))
		}},
		{"session access token: start OAuth authorization", func(bool) string { return short(c.authorize(c.jwt)) }},
		{"session access token: websocket auth", func(bool) string { return c.wsAuth(c.jwt) }},

		{"refresh cookie: v1 refresh", func(bool) string {
			rec := p.req(http.MethodPost, "/api/v1/user/token/refresh", "", nil, c.cookieV1...)
			if rec.Code < 300 {
				c.cookieV1 = refreshCookies(rec)
			}
			return short(rec)
		}},
		{"refresh cookie: v2 refresh", func(bool) string {
			rec := p.req(http.MethodPost, "/api/v2/user/token/refresh", "", nil, c.cookieV2...)
			if rec.Code < 300 {
				c.cookieV2 = refreshCookies(rec)
			}
			return short(rec)
		}},

		{"API token: REST v2 list tasks", get("/api/v2/tasks", bearer(c.apiTok))},
		{"API token: REST v1 list tasks", get("/api/v1/tasks", bearer(c.apiTok))},
		{"API token: CalDAV basic auth", dav(func() string { return c.apiTok })},
		{"API token: Atom feed /feeds", get("/feeds/notifications.atom", basic(tg.username, c.apiTok))},
		{"API token: Atom feed /api/v2", get("/api/v2/notifications.atom", basic(tg.username, c.apiTok))},
		{"API token: MCP endpoint", func(bool) string {
			h := bearer(c.apiTok)
			h["Accept"] = "application/json, text/event-stream"
			return short(p.req(http.MethodPost, "/api/v2/mcp", `{"jsonrpc":"2.0","id":1,"method":"initialize","params":{"protocolVersion":"2025-03-26","capabilities":{},"clientInfo":{"name":"probe","version":"1"}}}`, h))
		}},
		{"CalDAV token: CalDAV basic auth", dav(func() string { return c.davTok })},

		{"OAuth: access token reads profile", get("/api/v2/user", bearer(c.oauthAccess))},
		{"OAuth: refresh-token grant", func(bool) string {
			rec := p.req(http.MethodPost, "/api/v1/oauth/token", fmt.Sprintf(`{"grant_type":"refresh_token","refresh_token":%q}`, c.oauthRefresh), nil)
			if rec.Code < 300 {
				c.oauthRefresh = field(rec, "refresh_token")
			}
			return short(rec)
		}},
		{"OAuth: redeem an authorization code issued earlier", func(after bool) string {
			if !after {
				return short(c.exchange(field(c.authorize(c.jwt), "code")))
			}
			return short(c.exchange(c.oauthCodeHeld))
		}},

		{"link share made by the account: authenticate by hash", func(bool) string {
			return short(p.req(http.MethodPost, "/api/v2/shares/"+c.shareHash+"/auth", "", nil))
		}},
		{"link share made by the account: existing share token reads project", get("/api/v2/projects/"+c.projectID, bearer(c.shareJWT))},
		{"bot owned by the account: its API token lists projects", func(bool) string {
			if c.botTok == "" {
				return "(no bot)"
			}
			return short(p.req(http.MethodGet, "/api/v2/projects", "", bearer(c.botTok)))
		}},
	}
}

func probeStatus(t *testing.T, id int64) (string, string) {
	s := db.NewSession()
	defer s.Close()
	u := &user.User{}
	_, err := s.Where("id = ?", id).Get(u)
	require.NoError(t, err)
	return u.Status.String(), u.Email
}

// emailedTokens tries the credentials that arrive by email. They change the account, so they run last.
func (c *creds) emailedTokens(state string) {
	t, p, tg := c.t, c.p, c.tg
	if c.mintedAfter != "" {
		t.Logf("PROBE [%s] %-62s -> %s", state, "API token minted AFTER the block: REST v2 list tasks", short(p.req(http.MethodGet, "/api/v2/tasks", "", bearer(c.mintedAfter))))
	}
	t.Logf("PROBE [%s] %-62s -> %s", state, "ask for a password-reset email", short(p.req(http.MethodPost, "/api/v2/user/password/token", fmt.Sprintf(`{"email":%q}`, tg.email), nil)))

	st, em := probeStatus(t, tg.id)
	rec := p.req(http.MethodPost, "/api/v2/user/confirm", fmt.Sprintf(`{"token":"probe-confirm-%d"}`, tg.id), nil)
	st2, em2 := probeStatus(t, tg.id)
	t.Logf("PROBE [%s] %-62s -> %s (status %s -> %s, email %s -> %s)", state, "emailed link confirming a pending email change", short(rec), st, st2, em, em2)

	rec = p.req(http.MethodPost, "/api/v2/user/password/reset", fmt.Sprintf(`{"token":"probe-reset-%d","new_password":"AfterResetPassw0rd"}`, tg.id), nil)
	st3, _ := probeStatus(t, tg.id)
	t.Logf("PROBE [%s] %-62s -> %s (status %s -> %s)", state, "emailed password-reset link", short(rec), st2, st3)
	t.Logf("PROBE [%s] %-62s -> %s", state, "then: login with the new password", short(c.login("/api/v2/login", tg.username, "AfterResetPassw0rd")))
}

func runBlockedState(t *testing.T, state string, tg target, block func(p *probeEnv, c *creds)) {
	p := newProbeEnv(t)
	c := establish(t, p, tg)
	cs := c.checks()
	before := make([]string, len(cs))
	for i, ch := range cs {
		before[i] = ch.run(false)
	}
	block(p, c)
	st, _ := probeStatus(t, tg.id)
	s := db.NewSession()
	n, _ := s.Where("user_id = ?", tg.id).Count(&models.Session{})
	s.Close()
	t.Logf("PROBE [%s] account status is now %q; session rows left: %d", state, st, n)
	for i, ch := range cs {
		t.Logf("PROBE [%s] %-62s while active: %-12s now: %s", state, ch.name, before[i], ch.run(true))
	}
	c.emailedTokens(state)
}

func adminSetStatus(t *testing.T, p *probeEnv, id int64, status int) {
	promoteToAdmin(t, 1)
	rec := p.req(http.MethodPost, "/api/v2/login", `{"username":"user1","password":"12345678"}`, nil)
	require.Equal(t, 200, rec.Code, rec.Body.String())
	rec = p.req(http.MethodPatch, fmt.Sprintf("/api/v2/admin/users/%d/status", id), fmt.Sprintf(`{"status":%d}`, status), bearer(field(rec, "token")))
	t.Logf("PROBE   admin endpoint PATCH /admin/users/%d/status {status:%d} -> %s", id, status, short(rec))
	require.Less(t, rec.Code, 300, rec.Body.String())
}

func TestAuditProbeBlocked1_DisabledByAdmin(t *testing.T) {
	runBlockedState(t, "disabled", target{id: 2, username: "user2", email: "user2@example.com", password: "12345678"},
		func(p *probeEnv, _ *creds) { adminSetStatus(t, p, 2, int(user.StatusDisabled)) })
}

func TestAuditProbeBlocked2_LockedAfterFailed2FA(t *testing.T) {
	tg := target{id: 10, username: "user10", email: "user10@example.com", password: "12345678", totpSecret: "JBSWY3DPEHPK3PXP"}
	runBlockedState(t, "locked", tg, func(p *probeEnv, _ *creds) {
		last := ""
		for i := 0; i < 10; i++ {
			last = short(p.req(http.MethodPost, "/api/v2/login", `{"username":"user10","password":"12345678","totp_passcode":"000000"}`, nil))
		}
		t.Logf("PROBE   ten logins with the right password and a wrong 2fa code; last response: %s", last)
		// The lock fires an account-locked event whose listener revokes sessions. The
		// harness records events instead of delivering them, so run that listener the
		// way the event bus would.
		events.TestListener(t, &user.AccountLockedEvent{UserID: 10}, &models.RevokeSessionsOnAccountLock{})
	})
}

func TestAuditProbeBlocked3_SetBackToUnconfirmedByAdmin(t *testing.T) {
