			const s = "disabled, then re-enabled by admin"
			t.Logf("PROBE {%s} API token from before the block      -> %s", s, short(p.req(http.MethodGet, "/api/v2/tasks", "", bearer(c.apiTok))))
			t.Logf("PROBE {%s} API token minted DURING the block    -> %s", s, short(p.req(http.MethodGet, "/api/v2/tasks", "", bearer(minted))))
			t.Logf("PROBE {%s} CalDAV token from before the block   -> %s", s, short(p.req("PROPFIND", "/dav/principals/user2/", "", basic("user2", c.davTok))))
			t.Logf("PROBE {%s} session access token from before     -> %s", s, short(p.req(http.MethodGet, "/api/v2/user", "", bearer(c.jwt))))
			t.Logf("PROBE {%s} refresh cookie from before           -> %s", s, short(p.req(http.MethodPost, "/api/v2/user/token/refresh", "", nil, c.cookieV2...)))
			t.Logf("PROBE {%s} OAuth refresh token from before      -> %s", s, short(p.req(http.MethodPost, "/api/v1/oauth/token", fmt.Sprintf(`{"grant_type":"refresh_token","refresh_token":%q}`, c.oauthRefresh), nil)))
			t.Logf("PROBE {%s} OAuth authorization code from before -> %s", s, short(c.exchange(c.oauthCodeHeld)))
		})
}

func TestAuditProbeBlockedF2_Locked(t *testing.T) {
	tg := target{id: 10, username: "user10", email: "user10@example.com", password: "12345678", totpSecret: "JBSWY3DPEHPK3PXP"}
	followUp(t, "locked", tg,
		func(p *probeEnv) {
			for i := 0; i < 10; i++ {
				p.req(http.MethodPost, "/api/v2/login", `{"username":"user10","password":"12345678","totp_passcode":"000000"}`, nil)
			}
			events.TestListener(t, &user.AccountLockedEvent{UserID: 10}, &models.RevokeSessionsOnAccountLock{})
		},
		func(p *probeEnv, c *creds, minted string) {
			rec := p.req(http.MethodPost, "/api/v2/user/password/reset", `{"token":"probe-reset-10","new_password":"AfterResetPassw0rd"}`, nil)
			st, _ := probeStatus(t, 10)
			const s = "locked, then unlocked by password reset"
			t.Logf("PROBE {%s} emailed reset link -> %s, status now %q", s, short(rec), st)
			code, _ := totp.GenerateCode(tg.totpSecret, time.Now())
			_ = keyvalue.Del("totp_used_10_" + code) // the probe already spent this code; a real user would have a fresh one
			t.Logf("PROBE {%s} login with new password + 2fa code   -> %s", s, short(p.req(http.MethodPost, "/api/v2/login", fmt.Sprintf(`{"username":"user10","password":"AfterResetPassw0rd","totp_passcode":%q}`, code), nil)))
			t.Logf("PROBE {%s} API token from before the lock       -> %s", s, short(p.req(http.MethodGet, "/api/v2/tasks", "", bearer(c.apiTok))))
			t.Logf("PROBE {%s} API token minted DURING the lock     -> %s", s, short(p.req(http.MethodGet, "/api/v2/tasks", "", bearer(minted))))
			t.Logf("PROBE {%s} CalDAV token from before the lock    -> %s", s, short(p.req("PROPFIND", "/dav/principals/user10/", "", basic("user10", c.davTok))))
			t.Logf("PROBE {%s} session access token from before     -> %s", s, short(p.req(http.MethodGet, "/api/v2/user", "", bearer(c.jwt))))
			t.Logf("PROBE {%s} OAuth authorization code from before -> %s", s, short(c.exchange(c.oauthCodeHeld)))
		})
}

func TestAuditProbeBlockedF3_Unconfirmed(t *testing.T) {
	followUp(t, "unconfirmed (set by admin)", target{id: 2, username: "user2", email: "user2@example.com", password: "12345678"},
		func(p *probeEnv) { adminSetStatus(t, p, 2, int(user.StatusEmailConfirmationRequired)) },
		func(p *probeEnv, c *creds, _ string) {
			const s = "unconfirmed (set by admin)"
			rec := c.exchange(c.oauthCodeHeld)
			t.Logf("PROBE {%s} redeem OAuth code issued before the block -> %s (new refresh token issued: %v)", s, short(rec), field(rec, "refresh_token") != "")
			rec2 := p.req(http.MethodPost, "/api/v1/oauth/token", fmt.Sprintf(`{"grant_type":"refresh_token","refresh_token":%q}`, field(rec, "refresh_token")), nil)
			t.Logf("PROBE {%s} then use that refresh token              -> %s", s, short(rec2))
			t.Logf("PROBE {%s} then use the refreshed access token      -> %s", s, short(p.req(http.MethodGet, "/api/v2/user", "", bearer(field(rec2, "access_token")))))
			n := 0
			sdb := db.NewSession()
			cnt, _ := sdb.Where("user_id = ?", 2).Count(&models.Session{})
			sdb.Close()
			n = int(cnt)
			st, _ := probeStatus(t, 2)
			t.Logf("PROBE {%s} afterwards: status %q, live session rows: %d", s, st, n)
		})
}
