		t.Logf("PROBE {%s} old session access token: %-42s -> %s", state, e.name, short(rec))
	}
	t.Logf("PROBE {%s} websocket auth with the old session access token: while active: %s  now: %s", state, wsBefore, c.wsAuth(c.jwt))

	rec = p.req(http.MethodGet, "/api/v2/tasks", "", bearer(botTok))
	var tasks struct {
		Items []json.RawMessage `json:"items"`
	}
	_ = json.Unmarshal(rec.Body.Bytes(), &tasks)
	t.Logf("PROBE {%s} bot owned by the account: read tasks in the account's project -> %s (%d tasks visible)", state, short(rec), len(tasks.Items))
	t.Logf("PROBE {%s} bot owned by the account: create task in that project: while active: %s  now: %s", state, botBefore,
		short(p.req(http.MethodPost, "/api/v2/projects/"+c.projectID+"/tasks", `{"title":"bot task while owner is blocked"}`, bearer(botTok))))
	if mintedBot != "" {
		t.Logf("PROBE {%s} bot API token minted AFTER the block (via old session token): list tasks -> %s", state, short(p.req(http.MethodGet, "/api/v2/tasks", "", bearer(mintedBot))))
	}

	rec = p.req(http.MethodPost, "/api/v2/shares/"+c.shareHash+"/auth", "", nil)
	fresh := field(rec, "token")
	t.Logf("PROBE {%s} link share made by the account: fresh share token reads project -> %s", state, short(p.req(http.MethodGet, "/api/v2/projects/"+c.projectID, "", bearer(fresh))))

	after(p, c, minted)
}

