package webtests

// TEMPORARY audit probes - not part of the codebase, removed after the run.
// Requests go through the real router. Notifications are NOT faked: mails are
// rendered for real and captured by the mail package's test hook, so the links
// used below are the ones a user would receive. Outcomes are logged, not asserted.

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"os"
	"regexp"
	"sort"
	"strings"
	"sync"
	"testing"
	"time"

	"code.vikunja.io/api/pkg/config"
	"code.vikunja.io/api/pkg/db"
	"code.vikunja.io/api/pkg/events"
	"code.vikunja.io/api/pkg/files"
	"code.vikunja.io/api/pkg/license"
	"code.vikunja.io/api/pkg/log"
	"code.vikunja.io/api/pkg/mail"
	"code.vikunja.io/api/pkg/models"
	"code.vikunja.io/api/pkg/modules/keyvalue"
	"code.vikunja.io/api/pkg/notifications"
	"code.vikunja.io/api/pkg/routes"
	"code.vikunja.io/api/pkg/user"
	"code.vikunja.io/api/pkg/utils"

	"github.com/labstack/echo/v5"
	"github.com/pquerna/otp/totp"
	"github.com/stretchr/testify/require"
)

type probeEnv struct {
	t *testing.T
	e *echo.Echo
}

func newProbeEnv(t *testing.T) *probeEnv {
	t.Helper()
	config.InitDefaultConfig()
	config.ServicePublicURL.Set("https://localhost/")
	log.InitLogger()
	files.InitTests()
	user.InitTests()
	models.SetupTests()
	events.Fake()
	keyvalue.InitStorage()
	config.MailerEnabled.Set(true)
	config.RateLimitNoAuthRoutesLimit.Set(100000)
	config.RateLimitTokenRefreshLimit.Set(100000)
	require.NoError(t, db.LoadFixtures())
	notifications.Unfake()
	mail.Fake()
	license.SetForTests([]license.Feature{license.FeatureAdminPanel})
	t.Cleanup(license.ResetForTests)
	e := routes.NewEcho()
	routes.RegisterRoutes(e)
	return &probeEnv{t: t, e: e}
}

func (p *probeEnv) req(method, path, body, bearer string) *httptest.ResponseRecorder {
	r := httptest.NewRequest(method, path, strings.NewReader(body))
	r.Header.Set("Content-Type", "application/json")
	if bearer != "" {
		r.Header.Set("Authorization", "Bearer "+bearer)
	}
	rec := httptest.NewRecorder()
	p.e.ServeHTTP(rec, r)
	return rec
}

func short(rec *httptest.ResponseRecorder) string {
	if rec.Code < 300 {
		return fmt.Sprint(rec.Code)
	}
	var b struct {
		Message string `json:"message"`
		Detail  string `json:"detail"`
	}
	_ = json.Unmarshal(rec.Body.Bytes(), &b)
	m := b.Message
	if m == "" {
		m = b.Detail
	}
	if len(m) > 60 {
		m = m[:60]
	}
	return fmt.Sprintf("%d %s", rec.Code, m)
}

func field(rec *httptest.ResponseRecorder, name string) string {
	var m map[string]any
	_ = json.Unmarshal(rec.Body.Bytes(), &m)
	switch v := m[name].(type) {
	case string:
		return v
	case float64:
		return fmt.Sprint(int64(v))
	}
	return ""
}

func (p *probeEnv) login(name, pw, code string) string {
	rec := p.req(http.MethodPost, "/api/v2/login", fmt.Sprintf(`{"username":%q,"password":%q,"totp_passcode":%q}`, name, pw, code), "")
	return field(rec, "token")
}

var linkRe = regexp.MustCompile(`(userPasswordReset|userEmailConfirm|accountDeletionConfirm)=([A-Za-z0-9]+)`)

func mailToken(m *mail.Opts) (kind, tok string) {
	if g := linkRe.FindStringSubmatch(m.Message + " " + m.HTMLMessage); g != nil {
		return g[1], g[2]
	}
	return "", ""
}

// emailed returns the token from the newest captured mail of that kind sent to that address.
func emailed(t *testing.T, to, kind string) string {
	t.Helper()
	ms := mail.SentMails()
	for i := len(ms) - 1; i >= 0; i-- {
		if k, tok := mailToken(ms[i]); k == kind && strings.EqualFold(ms[i].To, to) {
			return tok
		}
	}
	t.Logf("PROBE   (no %s mail to %s captured)", kind, to)
	return "no-such-token"
}

func row(t *testing.T, id int64) *user.User {
	s := db.NewSession()
	defer s.Close()
	u := &user.User{}
	_, err := s.Where("id = ?", id).Get(u)
	require.NoError(t, err)
	return u
}

func backdate(t *testing.T, userID int64, kind user.TokenKind, age time.Duration) {
	s := db.NewSession()
	defer s.Close()
	_, err := s.NoAutoTime().Where("user_id = ? AND kind = ?", userID, kind).Cols("created").Update(&user.Token{Created: time.Now().Add(-age)})
	require.NoError(t, err)
	require.NoError(t, s.Commit())
}

func runCleanupCron(t *testing.T) int64 {
	s := db.NewSession()
	defer s.Close()
	n, err := user.CleanupOldTokens(s)
	require.NoError(t, err)
	require.NoError(t, s.Commit())
	return n
}

// The resend cooldown is a timestamp in the key-value store; rewriting it stands in for waiting a minute.
func waitOutCooldown(id int64) {
	_ = keyvalue.Put(fmt.Sprintf("email_confirm_sent_%d", id), time.Now().Add(-2*time.Minute).Unix())
}

func (p *probeEnv) reset(tok, pw string) string {
	return short(p.req(http.MethodPost, "/api/v2/user/password/reset", fmt.Sprintf(`{"token":%q,"new_password":%q}`, tok, pw), ""))
}
func (p *probeEnv) askReset(email string) string {
	return short(p.req(http.MethodPost, "/api/v2/user/password/token", fmt.Sprintf(`{"email":%q}`, email), ""))
}
func (p *probeEnv) confirm(tok string) string {
	return short(p.req(http.MethodPost, "/api/v2/user/confirm", fmt.Sprintf(`{"token":%q}`, tok), ""))
}
func (p *probeEnv) changeEmail(jwt, to, pw string) string {
	return short(p.req(http.MethodPut, "/api/v2/user/settings/email", fmt.Sprintf(`{"new_email":%q,"password":%q}`, to, pw), jwt))
}

func parallel(n int, fn func(i int) string) []string {
	out := make([]string, n)
	start := make(chan struct{})
	var wg sync.WaitGroup
	for i := 0; i < n; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			<-start
			out[i] = fn(i)
		}(i)
	}
	close(start)
	wg.Wait()
	return out
}

func tally(rs []string) string {
	m := map[string]int{}
	for _, r := range rs {
		m[r]++
	}
	var ks []string
	for k, n := range m {
		ks = append(ks, fmt.Sprintf("%s x%d", k, n))
	}
	sort.Strings(ks)
	return strings.Join(ks, " | ")
}

const pw2 = "12345678"

// ---------------------------------------------------------------------------
// 1: password-reset link
// ---------------------------------------------------------------------------

func TestAuditProbeSecret1_ResetLink(t *testing.T) {
	t.Run("reuse and sibling links", func(t *testing.T) {
		p := newProbeEnv(t)
		t.Logf("PROBE reset: ask twice -> %s, %s", p.askReset("user2@example.com"), p.askReset("user2@example.com"))
		ms := mail.SentMails()
		var toks []string
		for _, m := range ms {
			if k, tok := mailToken(m); k == "userPasswordReset" {
				toks = append(toks, tok)
				t.Logf("PROBE reset: mail to=%s subject=%q carries a reset link (token length %d)", m.To, m.Subject, len(tok))
			}
		}
		require.Len(t, toks, 2)
		t.Logf("PROBE reset: use link #1                       -> %s", p.reset(toks[0], "FirstNewPassw0rd"))
		t.Logf("PROBE reset: use link #1 a second time         -> %s", p.reset(toks[0], "SecondNewPassw0rd"))
		t.Logf("PROBE reset: use link #2 (never used, issued separately) -> %s", p.reset(toks[1], "ThirdNewPassw0rd"))
	})

	t.Run("things that might be expected to kill an outstanding link", func(t *testing.T) {
		for _, c := range []struct {
			name string
			do   func(p *probeEnv, jwt string) string
		}{
			{"user logs in normally afterwards", func(p *probeEnv, _ string) string {
				return short(p.req(http.MethodPost, "/api/v2/login", `{"username":"user2","password":"12345678"}`, ""))
			}},
			{"user changes password in settings", func(p *probeEnv, jwt string) string {
				return short(p.req(http.MethodPost, "/api/v2/user/password", `{"old_password":"12345678","new_password":"ChangedInSettings1"}`, jwt))
			}},
			{"user moves the account to a new email address (confirmed)", func(p *probeEnv, jwt string) string {
				r := p.changeEmail(jwt, "moved@example.com", pw2)
				return r + " then confirm " + p.confirm(emailed(t, "moved@example.com", "userEmailConfirm"))
			}},
			{"admin sets a new password for the user", func(p *probeEnv, _ string) string {
				promoteToAdmin(t, 1)
				adm := p.login("user1", "12345678", "")
				return short(p.req(http.MethodPatch, "/api/v2/admin/users/2/password", `{"new_password":"SetByTheAdmin123"}`, adm))
			}},
		} {
			p := newProbeEnv(t)
			jwt := p.login("user2", pw2, "")
			p.askReset("user2@example.com")
			tok := emailed(t, "user2@example.com", "userPasswordReset")
			did := c.do(p, jwt)
			res := p.reset(tok, "ViaOldResetLink1")
			after := p.login("user2", "ViaOldResetLink1", "") != ""
			t.Logf("PROBE reset: link issued, then %-58s (%s) -> old link: %s, login with the link's password works: %v (account email now %s)", c.name, did, res, after, row(t, 2).Email)
		}
	})

	t.Run("expiry", func(t *testing.T) {
		p := newProbeEnv(t)
		p.askReset("user2@example.com")
		tok := emailed(t, "user2@example.com", "userPasswordReset")
		backdate(t, 2, user.TokenPasswordReset, 30*time.Hour)
		t.Logf("PROBE reset: link is 30h old, cleanup cron has not run yet -> %s", p.reset(tok, "ThirtyHoursLater1"))

		p.askReset("user2@example.com")
		tok = emailed(t, "user2@example.com", "userPasswordReset")
		backdate(t, 2, user.TokenPasswordReset, 30*time.Hour)
		n := runCleanupCron(t)
		t.Logf("PROBE reset: link is 30h old, cleanup cron ran (removed %d)  -> %s", n, p.reset(tok, "ThirtyHoursLater2"))
	})

	t.Run("two simultaneous uses of one link", func(t *testing.T) {
		p := newProbeEnv(t)
		p.askReset("user2@example.com")
		tok := emailed(t, "user2@example.com", "userPasswordReset")
		rs := parallel(6, func(i int) string { return p.reset(tok, fmt.Sprintf("RacePassw0rd-%d", i)) })
		t.Logf("PROBE reset: 6 simultaneous uses of one link -> %s", tally(rs))
	})
}

// ---------------------------------------------------------------------------
// 2: registration confirmation link
// ---------------------------------------------------------------------------

func TestAuditProbeSecret2_RegistrationLink(t *testing.T) {
	p := newProbeEnv(t)
	rec := p.req(http.MethodPost, "/api/v2/register", `{"username":"newbie","password":"NewbiePassw0rd","email":"newbie@example.com"}`, "")
	require.Less(t, rec.Code, 300, rec.Body.String())
	var id int64
	_, _ = fmt.Sscan(field(rec, "id"), &id)
	tok := emailed(t, "newbie@example.com", "userEmailConfirm")
	backdate(t, id, user.TokenEmailConfirm, 400*24*time.Hour)
	n := runCleanupCron(t)
	t.Logf("PROBE signup: link is 400 days old and the cleanup cron ran (removed %d) -> %s (status now %s)", n, p.confirm(tok), row(t, id).Status)
	t.Logf("PROBE signup: same link a second time -> %s", p.confirm(tok))

	rec = p.req(http.MethodPost, "/api/v2/register", `{"username":"newbie2","password":"NewbiePassw0rd","email":"newbie2@example.com"}`, "")
	require.Less(t, rec.Code, 300, rec.Body.String())
	tok = emailed(t, "newbie2@example.com", "userEmailConfirm")
	rs := parallel(6, func(int) string { return p.confirm(tok) })
	t.Logf("PROBE signup: 6 simultaneous uses of one link -> %s", tally(rs))
}

// ---------------------------------------------------------------------------
// 3: email-change link
// ---------------------------------------------------------------------------

func TestAuditProbeSecret3_EmailChangeLink(t *testing.T) {
	state := func(t *testing.T) string {
		u := row(t, 2)
		return fmt.Sprintf("email=%s pending=%q", u.Email, u.PendingEmail)
	}

	t.Run("where the mails go, and reuse", func(t *testing.T) {
		p := newProbeEnv(t)
		jwt := p.login("user2", pw2, "")
		t.Logf("PROBE change: request change to a@new.test -> %s (%s)", p.changeEmail(jwt, "a@new.test", pw2), state(t))
		for _, m := range mail.SentMails() {
			k, _ := mailToken(m)
			t.Logf("PROBE change: mail to=%s subject=%q link=%q", m.To, m.Subject, k)
		}
		la := emailed(t, "a@new.test", "userEmailConfirm")
		t.Logf("PROBE change: use the link            -> %s (%s)", p.confirm(la), state(t))
		t.Logf("PROBE change: use the link again      -> %s (%s)", p.confirm(la), state(t))
	})

	t.Run("second change straight away (inside the one-minute cooldown)", func(t *testing.T) {
		p := newProbeEnv(t)
		jwt := p.login("user2", pw2, "")
		p.changeEmail(jwt, "a@new.test", pw2)
		la := emailed(t, "a@new.test", "userEmailConfirm")
		t.Logf("PROBE change: change to A, then to B at once -> %s (%s)", p.changeEmail(jwt, "b@new.test", pw2), state(t))
		t.Logf("PROBE change: link A afterwards              -> %s (%s)", p.confirm(la), state(t))
	})

	t.Run("second change after the cooldown", func(t *testing.T) {
		p := newProbeEnv(t)
		jwt := p.login("user2", pw2, "")
		p.changeEmail(jwt, "a@new.test", pw2)
		la := emailed(t, "a@new.test", "userEmailConfirm")
		waitOutCooldown(2)
		t.Logf("PROBE change: change to A, a minute later to B -> %s (%s)", p.changeEmail(jwt, "b@new.test", pw2), state(t))
		lb := emailed(t, "b@new.test", "userEmailConfirm")
		t.Logf("PROBE change: link A afterwards                -> %s (%s)", p.confirm(la), state(t))
		t.Logf("PROBE change: link B                           -> %s (%s)", p.confirm(lb), state(t))
	})

	t.Run("cancel, resend, expiry", func(t *testing.T) {
		p := newProbeEnv(t)
		jwt := p.login("user2", pw2, "")
		p.changeEmail(jwt, "a@new.test", pw2)
		la := emailed(t, "a@new.test", "userEmailConfirm")
		t.Logf("PROBE change: cancel the pending change -> %s", short(p.req(http.MethodDelete, "/api/v2/user/settings/email", "", jwt)))
		t.Logf("PROBE change: link A after cancel       -> %s (%s)", p.confirm(la), state(t))

		waitOutCooldown(2)
		p.changeEmail(jwt, "a@new.test", pw2)
		la = emailed(t, "a@new.test", "userEmailConfirm")
		waitOutCooldown(2)
		t.Logf("PROBE change: resend the link           -> %s", short(p.req(http.MethodPost, "/api/v2/user/settings/email/resend", "", jwt)))
		la2 := emailed(t, "a@new.test", "userEmailConfirm")
		t.Logf("PROBE change: first link after a resend -> %s (resent link differs: %v)", p.confirm(la), la != la2)
		backdate(t, 2, user.TokenEmailConfirm, 25*time.Hour)
		t.Logf("PROBE change: resent link, 25h old, cron not run -> %s (%s)", p.confirm(la2), state(t))
	})

	t.Run("pending change survives the owner securing the account", func(t *testing.T) {
		for _, how := range []string{"changes password in settings", "resets password by emailed link"} {
			p := newProbeEnv(t)
			// someone with the session and the password starts a change to their own address
			intruder := p.login("user2", pw2, "")
			t.Logf("PROBE takeover: intruder (session + password) requests change to intruder@evil.test -> %s", p.changeEmail(intruder, "intruder@evil.test", pw2))
			link := emailed(t, "intruder@evil.test", "userEmailConfirm")
			for _, m := range mail.SentMails() {
				if strings.EqualFold(m.To, "user2@example.com") {
					t.Logf("PROBE takeover:   owner is told by mail: %q", m.Subject)
				}
			}
			// the owner reacts
			if how == "changes password in settings" {
				owner := p.login("user2", pw2, "")
				t.Logf("PROBE takeover: owner %s -> %s", how, short(p.req(http.MethodPost, "/api/v2/user/password", `{"old_password":"12345678","new_password":"OwnerSecuredIt123"}`, owner)))
			} else {
				p.askReset("user2@example.com")
				t.Logf("PROBE takeover: owner %s -> %s", how, p.reset(emailed(t, "user2@example.com", "userPasswordReset"), "OwnerSecuredIt123"))
			}
			s := db.NewSession()
			n, _ := s.Where("user_id = ?", 2).Count(&models.Session{})
			s.Close()
			t.Logf("PROBE takeover:   sessions left: %d, %s", n, state(t))
			// the intruder no longer has a session or a working password, only the link in their mailbox
			t.Logf("PROBE takeover: intruder opens the emailed link (no session needed) -> %s (%s)", p.confirm(link), state(t))
			mail.ResetSent()
			t.Logf("PROBE takeover: intruder asks for a reset mail to intruder@evil.test -> %s", p.askReset("intruder@evil.test"))
			t.Logf("PROBE takeover: intruder uses that reset link                        -> %s", p.reset(emailed(t, "intruder@evil.test", "userPasswordReset"), "IntruderOwnsIt123"))
			t.Logf("PROBE takeover: intruder logs in: %v; owner's new password still works: %v", p.login("user2", "IntruderOwnsIt123", "") != "", p.login("user2", "OwnerSecuredIt123", "") != "")
		}
	})
}

// raceRounds: with a change to an attacker-held address pending, fire "resend" and "change
// to someone else's address" at the same moment, then see which mailbox holds the live link.
func raceRounds(t *testing.T, rounds int) {
	p := newProbeEnv(t)
	jwt := p.login("user2", pw2, "")
	outcomes := map[string]int{}
	var winner, winnerVictim string
	for i := 0; i < rounds; i++ {
		atk, vic := fmt.Sprintf("attacker%d@evil.test", i), fmt.Sprintf("victim%d@corp.test", i)
		p.req(http.MethodDelete, "/api/v2/user/settings/email", "", jwt)
		waitOutCooldown(2)
		mail.ResetSent()
		if r := p.changeEmail(jwt, atk, pw2); r != "200" {
			outcomes["setup failed: "+r]++
			continue
		}
		waitOutCooldown(2)
		rs := parallel(2, func(j int) string {
			if j == 0 {
				return "resend " + short(p.req(http.MethodPost, "/api/v2/user/settings/email/resend", "", jwt))
			}
			return "change " + p.changeEmail(jwt, vic, pw2)
		})
		pending := row(t, 2).PendingEmail
		live := map[string]bool{}
		s := db.NewSession()
		var toks []*user.Token
		_ = s.Where("user_id = ? AND kind = ?", 2, user.TokenEmailConfirm).Find(&toks)
		s.Close()
		for _, tk := range toks {
			live[tk.Token] = true
		}
		liveTo := "nobody"
		liveTok := ""
		for _, m := range mail.SentMails() {
			if k, tok := mailToken(m); k == "userEmailConfirm" && live[utils.Sha256Hex(tok)] {
				liveTo, liveTok = m.To, tok
			}
		}
		kind := "consistent"
		switch {
		case pending == vic && liveTo == atk:
			kind = "MISMATCH: pending address is the victim's, live link sits in the attacker's mailbox"
			if winner == "" {
				winner, winnerVictim = liveTok, vic
			}
		case pending == atk && liveTo == vic:
			kind = "mismatch the other way: pending is attacker's, live link went to the victim"
		}
		outcomes[fmt.Sprintf("%s  [%s; %s]", kind, rs[0], rs[1])]++
		if winner != "" && i >= 3 {
			break
		}
	}
	var ks []string
	for k, n := range outcomes {
		ks = append(ks, fmt.Sprintf("%dx %s", n, k))
	}
	sort.Strings(ks)
	for _, k := range ks {
		t.Logf("PROBE race (%s): %s", db.Type(), k)
	}
	if winner != "" {
		u := row(t, 2)
		t.Logf("PROBE race (%s): before confirm: email=%s pending=%s", db.Type(), u.Email, u.PendingEmail)
		t.Logf("PROBE race (%s): attacker opens the link from their own mailbox -> %s", db.Type(), p.confirm(winner))
		u = row(t, 2)
		t.Logf("PROBE race (%s): account email is now %s (victim address %s never received a usable link)", db.Type(), u.Email, winnerVictim)
	}
}

