func TestAuditProbeSecret6_TOTPCodes(t *testing.T) {
	const secret10 = "JBSWY3DPEHPK3PXP"
	try := func(p *probeEnv, code string) string {
		return short(p.req(http.MethodPost, "/api/v2/login", fmt.Sprintf(`{"username":"user10","password":"12345678","totp_passcode":%q}`, code), ""))
	}

	t.Run("reuse and time window", func(t *testing.T) {
		p := newProbeEnv(t)
		now, _ := totp.GenerateCode(secret10, time.Now())
		t.Logf("PROBE 2fa: current code                 -> %s", try(p, now))
		t.Logf("PROBE 2fa: same code again              -> %s", try(p, now))
		t.Logf("PROBE 2fa: same code via v1 login       -> %s", short(p.req(http.MethodPost, "/api/v1/login", fmt.Sprintf(`{"username":"user10","password":"12345678","totp_passcode":%q}`, now), "")))
