	s.Close()
	storedAs := "?"
	if len(stored) == 1 {
		switch stored[0].Token {
		case rt:
			storedAs = "CLEAR TEXT"
		case utils.Sha256Hex(rt):
			storedAs = "SHA-256 of the token"
		default:
			storedAs = "something else"
		}
	}
	p.reset(rt, "ChangedByReset123")
	p.reset(rt, "ChangedByReset456")

