	jwt = p.login("user2", "ChangedByReset123", "")
	p.changeEmail(jwt, "a@new.test", "ChangedByReset123")
	ct := emailed(t, "a@new.test", "userEmailConfirm")
	secrets["email-confirm token"] = ct
	p.req(http.MethodGet, "/?userEmailConfirm="+ct, "", "")
	backdate(t, 2, user.TokenEmailConfirm, 25*time.Hour)
	p.confirm(ct) // expired: rejected
	waitOutCooldown(2)

	// deletion link
	p.req(http.MethodPost, "/api/v2/user/deletion/request", `{"password":"ChangedByReset123"}`, jwt)
	dt := emailed(t, "user2@example.com", "accountDeletionConfirm")
	secrets["deletion token"] = dt
	p.req(http.MethodGet, "/?accountDeletionConfirm="+dt, "", "")
	other := p.login("user3", "12345678", "")
	p.req(http.MethodPost, "/api/v2/user/deletion/confirm", fmt.Sprintf(`{"token":%q}`, dt), other)

	// 2fa: secret at enrolment, a wrong code and a right code at login
	rec := p.req(http.MethodPost, "/api/v2/user/settings/totp/enroll", "", jwt)
	ts := field(rec, "secret")
	secrets["2fa shared secret"] = ts
	good, _ := totp.GenerateCode(ts, time.Now())
	p.req(http.MethodPost, "/api/v2/user/settings/totp/enable", fmt.Sprintf(`{"passcode":%q}`, good), jwt)
	statusAfter := p.req(http.MethodGet, "/api/v2/user/settings/totp", "", p.login("user2", "ChangedByReset123", func() string { c, _ := totp.GenerateCode(ts, time.Now().Add(30*time.Second)); return c }()))
	p.req(http.MethodPost, "/api/v2/login", `{"username":"user2","password":"ChangedByReset123","totp_passcode":"135790"}`, "")
	secrets["wrong 2fa code typed at login"] = "135790"
	secrets["valid 2fa code"] = good

	_ = w.Close()
	os.Stdout = orig
	<-done

	t.Logf("PROBE store: reset token in the user_tokens table is stored as: %s", storedAs)
	sdb := db.NewSession()
	tr := &user.TOTP{}
	_, _ = sdb.Where("user_id = ?", 2).Get(tr)
	t.Logf("PROBE store: 2fa row after enabling: secret column holds the secret in clear: %v; url column also contains it: %v", tr.Secret == ts, strings.Contains(tr.URL, ts))
	notif, _ := sdb.QueryString("SELECT count(*) AS n FROM notifications WHERE notification LIKE ? OR notification LIKE ? OR notification LIKE ?", "%"+rt+"%", "%"+ct+"%", "%"+dt+"%")
	sdb.Close()
	t.Logf("PROBE store: rows in the notifications table containing any of the emailed tokens: %v", notif)
	t.Logf("PROBE api: 2fa status endpoint after enabling returns secret=%q url=%q", field(statusAfter, "secret"), field(statusAfter, "url"))

	for _, m := range mail.SentMails() {
		k, tok := mailToken(m)
		if k == "" {
			continue
		}
		t.Logf("PROBE mail: to=%-18s subject=%-42q link in text part: %v, in HTML part: %v", m.To, m.Subject, strings.Contains(m.Message, tok), strings.Contains(m.HTMLMessage, tok))
	}

	lines := strings.Split(buf.String(), "\n")
	t.Logf("PROBE log: captured %d server log lines", len(lines))
	var names []string
	for n := range secrets {
		names = append(names, n)
	}
	sort.Strings(names)
	for _, name := range names {
		sec := secrets[name]
		hits := 0
		for _, l := range lines {
			if !strings.Contains(l, sec) {
				continue
			}
			hits++
			if hits <= 3 {
				l = strings.ReplaceAll(l, sec, "<"+strings.ToUpper(name)+">")
				if i := strings.Index(l, "level="); i > 0 {
					l = l[i:]
				}
				if len(l) > 230 {
					l = l[:230] + "..."
				}
				t.Logf("PROBE log: %-30s appears in: %s", name, l)
			}
		}
		t.Logf("PROBE log: %-30s -> %d log lines contain it", name, hits)
	}
}

