		t.Logf("PROBE delete: a password-reset token offered as deletion token -> %s (%s)", confirmDel(p, jwt, resetTok), sched(t))
		askDel(p, jwt)
		l := emailed(t, "user2@example.com", "accountDeletionConfirm")
		t.Logf("PROBE delete: a deletion token offered as reset token          -> %s", p.reset(l, "ShouldNotWork123"))
		t.Logf("PROBE delete: a deletion token offered as email-confirm token  -> %s", p.confirm(l))
		backdate(t, 2, user.TokenAccountDeletion, 30*time.Hour)
		t.Logf("PROBE delete: link is 30h old, cleanup cron has not run yet    -> %s (%s)", confirmDel(p, jwt, l), sched(t))
