		t.Logf("PROBE 2fa: enable with code            -> %s", short(p.req(http.MethodPost, "/api/v2/user/settings/totp/enable", fmt.Sprintf(`{"passcode":%q}`, code), jwt)))
		t.Logf("PROBE 2fa: log in with that same code  -> %s", short(p.req(http.MethodPost, "/api/v2/login", fmt.Sprintf(`{"username":"user2","password":"12345678","totp_passcode":%q}`, code), "")))
	})

	t.Run("one code, simultaneous logins", func(t *testing.T) {
		for round := 0; round < 3; round++ {
			p := newProbeEnv(t)
			code, _ := totp.GenerateCode(secret10, time.Now())
