			s := db.NewSession()
			n, _ := s.Where("user_id = ?", 10).Count(&models.Session{})
			s.Close()
			t.Logf("PROBE 2fa (%s): 8 simultaneous logins with one code -> %s ; sessions created: %d", db.Type(), tally(rs), n)
		}
	})
}

func firstOr(ks []string) string {
	if len(ks) == 0 {
		return ""
	}
	return ks[0]
}

