	"github.com/pquerna/otp/totp"
	"github.com/stretchr/testify/require"
)

type probeEnv struct {
	t *testing.T
	e *echo.Echo
}

func newProbeEnv(t *testing.T) *probeEnv {
	t.Helper()
	config.InitDefaultConfig()
	config.ServicePublicURL.Set("https://localhost/")
	log.InitLogger()
	files.InitTests()
	user.InitTests()
	models.SetupTests()
	events.Fake()
	keyvalue.InitStorage()
	config.MailerEnabled.Set(true)
	config.RateLimitNoAuthRoutesLimit.Set(100000)
	config.RateLimitTokenRefreshLimit.Set(100000)
	require.NoError(t, db.LoadFixtures())
	notifications.Unfake()
	mail.Fake()
	license.SetForTests([]license.Feature{license.FeatureAdminPanel})
	t.Cleanup(license.ResetForTests)
	e := routes.NewEcho()
	routes.RegisterRoutes(e)
	return &probeEnv{t: t, e: e}
}

func (p *probeEnv) req(method, path, body, bearer string) *httptest.ResponseRecorder {
	r := httptest.NewRequest(method, path, strings.NewReader(body))
	r.Header.Set("Content-Type", "application/json")
	if bearer != "" {
		r.Header.Set("Authorization", "Bearer "+bearer)
	}
	rec := httptest.NewRecorder()
	p.e.ServeHTTP(rec, r)
	return rec
}

func short(rec *httptest.ResponseRecorder) string {
	if rec.Code < 300 {
		return fmt.Sprint(rec.Code)
	}
	var b struct {
		Message string `json:"message"`
		Detail  string `json:"detail"`
	}
	_ = json.Unmarshal(rec.Body.Bytes(), &b)
	m := b.Message
	if m == "" {
		m = b.Detail
	}
	if len(m) > 60 {
		m = m[:60]
	}
	return fmt.Sprintf("%d %s", rec.Code, m)
}

func field(rec *httptest.ResponseRecorder, name string) string {
	var m map[string]any
	_ = json.Unmarshal(rec.Body.Bytes(), &m)
	switch v := m[name].(type) {
	case string:
		return v
	case float64:
		return fmt.Sprint(int64(v))
	}
	return ""
}

func (p *probeEnv) login(name, pw, code string) string {
	rec := p.req(http.MethodPost, "/api/v2/login", fmt.Sprintf(`{"username":%q,"password":%q,"totp_passcode":%q}`, name, pw, code), "")
	return field(rec, "token")
}

var linkRe = regexp.MustCompile(`(userPasswordReset|userEmailConfirm|accountDeletionConfirm)=([A-Za-z0-9]+)`)

func mailToken(m *mail.Opts) (kind, tok string) {
	if g := linkRe.FindStringSubmatch(m.Message + " " + m.HTMLMessage); g != nil {
		return g[1], g[2]
	}
	return "", ""
}

// emailed returns the token from the newest captured mail of that kind sent to that address.
func emailed(t *testing.T, to, kind string) string {
	t.Helper()
	ms := mail.SentMails()
	for i := len(ms) - 1; i >= 0; i-- {
		if k, tok := mailToken(ms[i]); k == kind && strings.EqualFold(ms[i].To, to) {
			return tok
		}
	}
	t.Logf("PROBE   (no %s mail to %s captured)", kind, to)
	return "no-such-token"
}

func row(t *testing.T, id int64) *user.User {
	s := db.NewSession()
	defer s.Close()
	u := &user.User{}
	_, err := s.Where("id = ?", id).Get(u)
	require.NoError(t, err)
	return u
}

func backdate(t *testing.T, userID int64, kind user.TokenKind, age time.Duration) {
	s := db.NewSession()
	defer s.Close()
	_, err := s.NoAutoTime().Where("user_id = ? AND kind = ?", userID, kind).Cols("created").Update(&user.Token{Created: time.Now().Add(-age)})
	require.NoError(t, err)
	require.NoError(t, s.Commit())
}

func runCleanupCron(t *testing.T) int64 {
	s := db.NewSession()
	defer s.Close()
	n, err := user.CleanupOldTokens(s)
	require.NoError(t, err)
	require.NoError(t, s.Commit())
	return n
}

// The resend cooldown is a timestamp in the key-value store; rewriting it stands in for waiting a minute.
func waitOutCooldown(id int64) {
	_ = keyvalue.Put(fmt.Sprintf("email_confirm_sent_%d", id), time.Now().Add(-2*time.Minute).Unix())
}

func (p *probeEnv) reset(tok, pw string) string {
	return short(p.req(http.MethodPost, "/api/v2/user/password/reset", fmt.Sprintf(`{"token":%q,"new_password":%q}`, tok, pw), ""))
}
func (p *probeEnv) askReset(email string) string {
	return short(p.req(http.MethodPost, "/api/v2/user/password/token", fmt.Sprintf(`{"email":%q}`, email), ""))
}
func (p *probeEnv) confirm(tok string) string {
	return short(p.req(http.MethodPost, "/api/v2/user/confirm", fmt.Sprintf(`{"token":%q}`, tok), ""))
}
func (p *probeEnv) changeEmail(jwt, to, pw string) string {
	return short(p.req(http.MethodPut, "/api/v2/user/settings/email", fmt.Sprintf(`{"new_email":%q,"password":%q}`, to, pw), jwt))
}

func parallel(n int, fn func(i int) string) []string {
	out := make([]string, n)
	start := make(chan struct{})
	var wg sync.WaitGroup
	for i := 0; i < n; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			<-start
			out[i] = fn(i)
		}(i)
	}
	close(start)
	wg.Wait()
	return out
}

func tally(rs []string) string {
	m := map[string]int{}
	for _, r := range rs {
		m[r]++
	}
	var ks []string
	for k, n := range m {
		ks = append(ks, fmt.Sprintf("%s x%d", k, n))
	}
	sort.Strings(ks)
	return strings.Join(ks, " | ")
}

const pw2 = "12345678"

