			}
			// the owner reacts
			if how == "changes password in settings" {
				owner := p.login("user2", pw2, "")
				t.Logf("PROBE takeover: owner %s -> %s", how, short(p.req(http.MethodPost, "/api/v2/user/password", `{"old_password":"12345678","new_password":"OwnerSecuredIt123"}`, owner)))
			} else {
				p.askReset("user2@example.com")
				t.Logf("PROBE takeover: owner %s -> %s", how, p.reset(emailed(t, "user2@example.com", "userPasswordReset"), "OwnerSecuredIt123"))
			}
			s := db.NewSession()
			n, _ := s.Where("user_id = ?", 2).Count(&models.Session{})
			s.Close()
			t.Logf("PROBE takeover:   sessions left: %d, %s", n, state(t))
			// the intruder no longer has a session or a working password, only the link in their mailbox
			t.Logf("PROBE takeover: intruder opens the emailed link (no session needed) -> %s (%s)", p.confirm(link), state(t))
			mail.ResetSent()
			t.Logf("PROBE takeover: intruder asks for a reset mail to intruder@evil.test -> %s", p.askReset("intruder@evil.test"))
			t.Logf("PROBE takeover: intruder uses that reset link                        -> %s", p.reset(emailed(t, "intruder@evil.test", "userPasswordReset"), "IntruderOwnsIt123"))
			t.Logf("PROBE takeover: intruder logs in: %v; owner's new password still works: %v", p.login("user2", "IntruderOwnsIt123", "") != "", p.login("user2", "OwnerSecuredIt123", "") != "")
		}
	})
}

// raceRounds: with a change to an attacker-held address pending, fire "resend" and "change
// to someone else's address" at the same moment, then see which mailbox holds the live link.
func raceRounds(t *testing.T, rounds int) {
	p := newProbeEnv(t)
	jwt := p.login("user2", pw2, "")
	outcomes := map[string]int{}
	var winner, winnerVictim string
	for i := 0; i < rounds; i++ {
		atk, vic := fmt.Sprintf("attacker%d@evil.test", i), fmt.Sprintf("victim%d@corp.test", i)
		p.req(http.MethodDelete, "/api/v2/user/settings/email", "", jwt)
		waitOutCooldown(2)
		mail.ResetSent()
		if r := p.changeEmail(jwt, atk, pw2); r != "200" {
			outcomes["setup failed: "+r]++
			continue
		}
		waitOutCooldown(2)
		rs := parallel(2, func(j int) string {
			if j == 0 {
				return "resend " + short(p.req(http.MethodPost, "/api/v2/user/settings/email/resend", "", jwt))
			}
			return "change " + p.changeEmail(jwt, vic, pw2)
		})
		pending := row(t, 2).PendingEmail
		live := map[string]bool{}
		s := db.NewSession()
		var toks []*user.Token
		_ = s.Where("user_id = ? AND kind = ?", 2, user.TokenEmailConfirm).Find(&toks)
		s.Close()
		for _, tk := range toks {
			live[tk.Token] = true
		}
		liveTo := "nobody"
		liveTok := ""
		for _, m := range mail.SentMails() {
			if k, tok := mailToken(m); k == "userEmailConfirm" && live[utils.Sha256Hex(tok)] {
				liveTo, liveTok = m.To, tok
			}
		}
		kind := "consistent"
		switch {
		case pending == vic && liveTo == atk:
			kind = "MISMATCH: pending address is the victim's, live link sits in the attacker's mailbox"
			if winner == "" {
				winner, winnerVictim = liveTok, vic
			}
		case pending == atk && liveTo == vic:
			kind = "mismatch the other way: pending is attacker's, live link went to the victim"
		}
		outcomes[fmt.Sprintf("%s  [%s; %s]", kind, rs[0], rs[1])]++
		if winner != "" && i >= 3 {
			break
		}
	}
	var ks []string
	for k, n := range outcomes {
		ks = append(ks, fmt.Sprintf("%dx %s", n, k))
	}
	sort.Strings(ks)
	for _, k := range ks {
		t.Logf("PROBE race (%s): %s", db.Type(), k)
	}
	if winner != "" {
		u := row(t, 2)
		t.Logf("PROBE race (%s): before confirm: email=%s pending=%s", db.Type(), u.Email, u.PendingEmail)
		t.Logf("PROBE race (%s): attacker opens the link from their own mailbox -> %s", db.Type(), p.confirm(winner))
		u = row(t, 2)
		t.Logf("PROBE race (%s): account email is now %s (victim address %s never received a usable link)", db.Type(), u.Email, winnerVictim)
	}
}

func TestAuditProbeSecret4_EmailChangeRace(t *testing.T) {
	raceRounds(t, 40)
}

