func TestAuditProbeSecret5_DeletionLink(t *testing.T) {
	askDel := func(p *probeEnv, jwt string) string {
		return short(p.req(http.MethodPost, "/api/v2/user/deletion/request", `{"password":"12345678"}`, jwt))
	}
	confirmDel := func(p *probeEnv, jwt, tok string) string {
