	t.Run("reuse, siblings, other user", func(t *testing.T) {
		p := newProbeEnv(t)
		jwt := p.login("user2", pw2, "")
		askDel(p, jwt)
		l1 := emailed(t, "user2@example.com", "accountDeletionConfirm")
		askDel(p, jwt)
		l2 := emailed(t, "user2@example.com", "accountDeletionConfirm")
		other := p.login("user3", "12345678", "")
		t.Logf("PROBE delete: link used without a session            -> %s", confirmDel(p, "", l1))
		t.Logf("PROBE delete: link used from another user's session  -> %s (%s)", confirmDel(p, other, l1), sched(t))
		t.Logf("PROBE delete: link #2 used by the owner              -> %s (%s)", confirmDel(p, jwt, l2), sched(t))
		t.Logf("PROBE delete: link #2 again                          -> %s", confirmDel(p, jwt, l2))
		t.Logf("PROBE delete: link #1 (issued earlier, never used)   -> %s", confirmDel(p, jwt, l1))
	})

	t.Run("link outstanding, then the user backs out", func(t *testing.T) {
		p := newProbeEnv(t)
		jwt := p.login("user2", pw2, "")
		askDel(p, jwt)
		l := emailed(t, "user2@example.com", "accountDeletionConfirm")
		t.Logf("PROBE delete: request, then 'cancel deletion' before confirming -> %s (%s)", short(p.req(http.MethodPost, "/api/v2/user/deletion/cancel", `{"password":"12345678"}`, jwt)), sched(t))
		t.Logf("PROBE delete: the emailed link afterwards                       -> %s (%s)", confirmDel(p, jwt, l), sched(t))
	})

	t.Run("link outstanding, then password changed", func(t *testing.T) {
		p := newProbeEnv(t)
		jwt := p.login("user2", pw2, "")
		askDel(p, jwt)
		l := emailed(t, "user2@example.com", "accountDeletionConfirm")
		p.req(http.MethodPost, "/api/v2/user/password", `{"old_password":"12345678","new_password":"ChangedInSettings1"}`, jwt)
		jwt2 := p.login("user2", "ChangedInSettings1", "")
		t.Logf("PROBE delete: link issued, password changed, link used from a new session -> %s (%s)", confirmDel(p, jwt2, l), sched(t))
	})

	t.Run("expiry and wrong kind", func(t *testing.T) {
		p := newProbeEnv(t)
		jwt := p.login("user2", pw2, "")
		p.askReset("user2@example.com")
		resetTok := emailed(t, "user2@example.com", "userPasswordReset")
		t.Logf("PROBE delete: a password-reset token offered as deletion token -> %s (%s)", confirmDel(p, jwt, resetTok), sched(t))
		askDel(p, jwt)
		l := emailed(t, "user2@example.com", "accountDeletionConfirm")
		t.Logf("PROBE delete: a deletion token offered as reset token          -> %s", p.reset(l, "ShouldNotWork123"))
		t.Logf("PROBE delete: a deletion token offered as email-confirm token  -> %s", p.confirm(l))
		backdate(t, 2, user.TokenAccountDeletion, 30*time.Hour)
		t.Logf("PROBE delete: link is 30h old, cleanup cron has not run yet    -> %s (%s)", confirmDel(p, jwt, l), sched(t))
	})
}

// ---------------------------------------------------------------------------
// 6: 2fa codes
// ---------------------------------------------------------------------------

func TestAuditProbeSecret6_TOTPCodes(t *testing.T) {
	const secret10 = "JBSWY3DPEHPK3PXP"
	try := func(p *probeEnv, code string) string {
		return short(p.req(http.MethodPost, "/api/v2/login", fmt.Sprintf(`{"username":"user10","password":"12345678","totp_passcode":%q}`, code), ""))
	}

	t.Run("reuse and time window", func(t *testing.T) {
		p := newProbeEnv(t)
		now, _ := totp.GenerateCode(secret10, time.Now())
		t.Logf("PROBE 2fa: current code                 -> %s", try(p, now))
		t.Logf("PROBE 2fa: same code again              -> %s", try(p, now))
		t.Logf("PROBE 2fa: same code via v1 login       -> %s", short(p.req(http.MethodPost, "/api/v1/login", fmt.Sprintf(`{"username":"user10","password":"12345678","totp_passcode":%q}`, now), "")))
		for _, off := range []int{-60, -30, 30, 60} {
			c, _ := totp.GenerateCode(secret10, time.Now().Add(time.Duration(off)*time.Second))
			t.Logf("PROBE 2fa: code for %+ds -> %s", off, try(p, c))
		}
		keys, _ := keyvalue.ListKeys("totp_used_")
		t.Logf("PROBE 2fa: used-code markers are kept in the key-value store (%s backend): %d keys, e.g. %q", config.KeyvalueType.GetString(), len(keys), strings.Replace(firstOr(keys), now, "<code>", 1))
	})

	t.Run("code spent on enabling 2fa, then tried at login", func(t *testing.T) {
		p := newProbeEnv(t)
		jwt := p.login("user2", pw2, "")
		rec := p.req(http.MethodPost, "/api/v2/user/settings/totp/enroll", "", jwt)
		secret := field(rec, "secret")
		code, _ := totp.GenerateCode(secret, time.Now())
		t.Logf("PROBE 2fa: enable with code            -> %s", short(p.req(http.MethodPost, "/api/v2/user/settings/totp/enable", fmt.Sprintf(`{"passcode":%q}`, code), jwt)))
		t.Logf("PROBE 2fa: log in with that same code  -> %s", short(p.req(http.MethodPost, "/api/v2/login", fmt.Sprintf(`{"username":"user2","password":"12345678","totp_passcode":%q}`, code), "")))
	})

	t.Run("one code, simultaneous logins", func(t *testing.T) {
		for round := 0; round < 3; round++ {
			p := newProbeEnv(t)
			code, _ := totp.GenerateCode(secret10, time.Now())
			rs := parallel(8, func(int) string { return try(p, code) })
			s := db.NewSession()
			n, _ := s.Where("user_id = ?", 10).Count(&models.Session{})
			s.Close()
			t.Logf("PROBE 2fa (%s): 8 simultaneous logins with one code -> %s ; sessions created: %d", db.Type(), tally(rs), n)
		}
	})
}

func firstOr(ks []string) string {
	if len(ks) == 0 {
		return ""
	}
	return ks[0]
}

// ---------------------------------------------------------------------------
// 7: where the secrets end up
// ---------------------------------------------------------------------------

func TestAuditProbeSecret7_WhereSecretsGo(t *testing.T) {
	// capture everything the server writes to its log while the flows run
	orig := os.Stdout
	r, w, err := os.Pipe()
	require.NoError(t, err)
	os.Stdout = w
	var buf bytes.Buffer
	done := make(chan struct{})
	go func() { _, _ = io.Copy(&buf, r); close(done) }()

	p := newProbeEnv(t)
	secrets := map[string]string{}

	jwt := p.login("user2", pw2, "")
	// reset link: clicked like a browser would (GET on the public URL), then used, then used again
	p.askReset("user2@example.com")
	rt := emailed(t, "user2@example.com", "userPasswordReset")
	secrets["password-reset token"] = rt
	p.req(http.MethodGet, "/?userPasswordReset="+rt, "", "")
	s := db.NewSession()
	var stored []*user.Token
	_ = s.Where("user_id = ? AND kind = ?", 2, user.TokenPasswordReset).Find(&stored)
	s.Close()
	storedAs := "?"
	if len(stored) == 1 {
		switch stored[0].Token {
		case rt:
			storedAs = "CLEAR TEXT"
		case utils.Sha256Hex(rt):
			storedAs = "SHA-256 of the token"
		default:
			storedAs = "something else"
		}
	}
	p.reset(rt, "ChangedByReset123")
	p.reset(rt, "ChangedByReset456")

	// email-change link
	jwt = p.login("user2", "ChangedByReset123", "")
	p.changeEmail(jwt, "a@new.test", "ChangedByReset123")
	ct := emailed(t, "a@new.test", "userEmailConfirm")
	secrets["email-confirm token"] = ct
	p.req(http.MethodGet, "/?userEmailConfirm="+ct, "", "")
	backdate(t, 2, user.TokenEmailConfirm, 25*time.Hour)
	p.confirm(ct) // expired: rejected
	waitOutCooldown(2)

	// deletion link
	p.req(http.MethodPost, "/api/v2/user/deletion/request", `{"password":"ChangedByReset123"}`, jwt)
	dt := emailed(t, "user2@example.com", "accountDeletionConfirm")
	secrets["deletion token"] = dt
	p.req(http.MethodGet, "/?accountDeletionConfirm="+dt, "", "")
	other := p.login("user3", "12345678", "")
	p.req(http.MethodPost, "/api/v2/user/deletion/confirm", fmt.Sprintf(`{"token":%q}`, dt), other)

	// 2fa: secret at enrolment, a wrong code and a right code at login
	rec := p.req(http.MethodPost, "/api/v2/user/settings/totp/enroll", "", jwt)
	ts := field(rec, "secret")
	secrets["2fa shared secret"] = ts
	good, _ := totp.GenerateCode(ts, time.Now())
	p.req(http.MethodPost, "/api/v2/user/settings/totp/enable", fmt.Sprintf(`{"passcode":%q}`, good), jwt)
	statusAfter := p.req(http.MethodGet, "/api/v2/user/settings/totp", "", p.login("user2", "ChangedByReset123", func() string { c, _ := totp.GenerateCode(ts, time.Now().Add(30*time.Second)); return c }()))
	p.req(http.MethodPost, "/api/v2/login", `{"username":"user2","password":"ChangedByReset123","totp_passcode":"135790"}`, "")
	secrets["wrong 2fa code typed at login"] = "135790"
	secrets["valid 2fa code"] = good

	_ = w.Close()
	os.Stdout = orig
	<-done

	t.Logf("PROBE store: reset token in the user_tokens table is stored as: %s", storedAs)
	sdb := db.NewSession()
	tr := &user.TOTP{}
	_, _ = sdb.Where("user_id = ?", 2).Get(tr)
	t.Logf("PROBE store: 2fa row after enabling: secret column holds the secret in clear: %v; url column also contains it: %v", tr.Secret == ts, strings.Contains(tr.URL, ts))
	notif, _ := sdb.QueryString("SELECT count(*) AS n FROM notifications WHERE notification LIKE ? OR notification LIKE ? OR notification LIKE ?", "%"+rt+"%", "%"+ct+"%", "%"+dt+"%")
	sdb.Close()
	t.Logf("PROBE store: rows in the notifications table containing any of the emailed tokens: %v", notif)
	t.Logf("PROBE api: 2fa status endpoint after enabling returns secret=%q url=%q", field(statusAfter, "secret"), field(statusAfter, "url"))

	for _, m := range mail.SentMails() {
		k, tok := mailToken(m)
		if k == "" {
			continue
		}
		t.Logf("PROBE mail: to=%-18s subject=%-42q link in text part: %v, in HTML part: %v", m.To, m.Subject, strings.Contains(m.Message, tok), strings.Contains(m.HTMLMessage, tok))
	}

	lines := strings.Split(buf.String(), "\n")
	t.Logf("PROBE log: captured %d server log lines", len(lines))
	var names []string
	for n := range secrets {
		names = append(names, n)
	}
	sort.Strings(names)
	for _, name := range names {
		sec := secrets[name]
		hits := 0
		for _, l := range lines {
			if !strings.Contains(l, sec) {
				continue
			}
			hits++
			if hits <= 3 {
				l = strings.ReplaceAll(l, sec, "<"+strings.ToUpper(name)+">")
				if i := strings.Index(l, "level="); i > 0 {
					l = l[i:]
				}
				if len(l) > 230 {
					l = l[:230] + "..."
				}
				t.Logf("PROBE log: %-30s appears in: %s", name, l)
			}
		}
		t.Logf("PROBE log: %-30s -> %d log lines contain it", name, hits)
	}
}

