package webtests

// TEMPORARY audit probe - not part of the codebase, removed after the run.

import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"regexp"
	"sort"
	"strings"
	"sync"
	"testing"
	"time"

	"code.vikunja.io/api/pkg/config"
	"code.vikunja.io/api/pkg/db"
	"code.vikunja.io/api/pkg/events"
	"code.vikunja.io/api/pkg/files"
	"code.vikunja.io/api/pkg/log"
	"code.vikunja.io/api/pkg/mail"
	"code.vikunja.io/api/pkg/models"
	"code.vikunja.io/api/pkg/modules/keyvalue"
	"code.vikunja.io/api/pkg/notifications"
	"code.vikunja.io/api/pkg/routes"
	"code.vikunja.io/api/pkg/user"
	"code.vikunja.io/api/pkg/utils"

	"github.com/labstack/echo/v5"
	"github.com/stretchr/testify/require"
)

var raceLinkRe = regexp.MustCompile(`userEmailConfirm=([A-Za-z0-9]+)`)

func raceReq(e *echo.Echo, method, path, body, bearer string) *httptest.ResponseRecorder {
	r := httptest.NewRequest(method, path, strings.NewReader(body))
	r.Header.Set("Content-Type", "application/json")
	if bearer != "" {
		r.Header.Set("Authorization", "Bearer "+bearer)
	}
	rec := httptest.NewRecorder()
	e.ServeHTTP(rec, r)
	return rec
}

func raceCooldownOver() {
	_ = keyvalue.Put("email_confirm_sent_2", time.Now().Add(-2*time.Minute).Unix())
}

func runEmailRace(t *testing.T, label string, rounds int, first func(e *echo.Echo, jwt, atk string) int) {
	config.InitDefaultConfig()
	config.ServicePublicURL.Set("https://localhost/")
	log.InitLogger()
	files.InitTests()
	user.InitTests()
	models.SetupTests()
	events.Fake()
	keyvalue.InitStorage()
	config.MailerEnabled.Set(true)
	config.RateLimitNoAuthRoutesLimit.Set(100000)
	require.NoError(t, db.LoadFixtures())
	notifications.Unfake()
	mail.Fake()
	e := routes.NewEcho()
	routes.RegisterRoutes(e)

	rec := raceReq(e, http.MethodPost, "/api/v2/login", `{"username":"user2","password":"12345678"}`, "")
	require.Equal(t, 200, rec.Code, rec.Body.String())
	jwt := regexp.MustCompile(`"token":"([^"]+)"`).FindStringSubmatch(rec.Body.String())[1]
	change := func(to string) int {
		return raceReq(e, http.MethodPut, "/api/v2/user/settings/email", fmt.Sprintf(`{"new_email":%q,"password":"12345678"}`, to), jwt).Code
	}

	outcomes := map[string]int{}
	for i := 0; i < rounds; i++ {
		atk, vic := fmt.Sprintf("attacker%d@evil.test", i), fmt.Sprintf("victim%d@corp.test", i)
		raceReq(e, http.MethodDelete, "/api/v2/user/settings/email", "", jwt)
		raceCooldownOver()
		mail.ResetSent()
		if label == "resend vs change" {
			if c := change(atk); c != 200 {
				outcomes[fmt.Sprintf("setup failed %d", c)]++
				continue
			}
			raceCooldownOver()
		}
		codes := make([]int, 2)
		start := make(chan struct{})
		var wg sync.WaitGroup
		wg.Add(2)
		go func() { defer wg.Done(); <-start; codes[0] = first(e, jwt, atk) }()
		go func() { defer wg.Done(); <-start; codes[1] = change(vic) }()
		close(start)
		wg.Wait()

		s := db.NewSession()
		u := &user.User{}
		_, _ = s.Where("id = ?", 2).Get(u)
		var toks []*user.Token
		_ = s.Where("user_id = ? AND kind = ?", 2, user.TokenEmailConfirm).Find(&toks)
		s.Close()
		live := map[string]bool{}
		for _, tk := range toks {
			live[tk.Token] = true
		}
		var liveTo []string
		for _, m := range mail.SentMails() {
			if g := raceLinkRe.FindStringSubmatch(m.Message + " " + m.HTMLMessage); g != nil && live[utils.Sha256Hex(g[1])] {
				liveTo = append(liveTo, strings.SplitN(m.To, "@", 2)[1])
			}
		}
		sort.Strings(liveTo)
		pend := "none"
		if u.PendingEmail != "" {
			pend = strings.SplitN(u.PendingEmail, "@", 2)[1]
		}
		verdict := "consistent"
		if pend == "corp.test" && strings.Contains(strings.Join(liveTo, ","), "evil.test") {
			verdict = "MISMATCH (pending = victim's address, a live link is in the attacker's mailbox)"
		} else if pend == "evil.test" && strings.Contains(strings.Join(liveTo, ","), "corp.test") {
			verdict = "mismatch the other way (pending = attacker's address, a live link went to the victim)"
		}
		outcomes[fmt.Sprintf("%s | responses %d/%d | pending=%s | live links mailed to %v (%d live tokens)", verdict, codes[0], codes[1], pend, liveTo, len(toks))]++
	}
	var ks []string
	for k, n := range outcomes {
		ks = append(ks, fmt.Sprintf("%3dx %s", n, k))
	}
	sort.Strings(ks)
	for _, k := range ks {
		t.Logf("PROBE race [%s, %s, %d rounds]: %s", label, db.Type(), rounds, k)
	}
}

func TestAuditProbeRaceA_TwoChanges(t *testing.T) {
	runEmailRace(t, "change vs change", 150, func(e *echo.Echo, jwt, atk string) int {
		return raceReq(e, http.MethodPut, "/api/v2/user/settings/email", fmt.Sprintf(`{"new_email":%q,"password":"12345678"}`, atk), jwt).Code
	})
}

func TestAuditProbeRaceB_ResendVsChange(t *testing.T) {
	runEmailRace(t, "resend vs change", 150, func(e *echo.Echo, jwt, _ string) int {
		return raceReq(e, http.MethodPost, "/api/v2/user/settings/email/resend", "", jwt).Code
	})
}

